/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140306-3","meetingId":"h26-c-budget","date":"2014年3月6日","dateIso":"2014-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後５時４２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件整理しています。","topics":[{"id":"topic-01","title":"平成２６年度品川区一般会計予算","agenda":"平成２６年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"１９６ページの選挙費、１７９ページの歴史館経費、それから時間があったら１６１ページの情報公開経費の三つお聞かせほしいと求めました。改めてこの当日の、本当は予定だった開票の終了時刻と、どうしてこんなに遅くなってしまったのかということで、お伺いさせてほしいと求めました。","respondent":"諸岡選挙管理委員会事務局長","answer":"帳票をちょっと変えたときに、軽微な変更だったために、チェックは行ったのですけれども結果的には不十分だったです。選挙事務全体でチェック体制を今後十分検討し直して、有権者の皆様に、二度とこのようなことがないように十分注意してまいります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に歴史館経費のことでお伺いさせていただきたいのですけれども、歴史館の今後の施設としてのあり方についてお伺いしたいと思います。それから観覧人数が７,９２０人ということで、年間８,０００人弱ということですけれども、お聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"歴史館の茶室については、文化遺産ということでご説明をさせていただいていますけれども、とにかく昭和初期に建てられた貴重な文化遺産です。一定の期間公開をして、区民の皆さんに親しんでもらうというふうには考えてありますが、また検討させていただきたいと思っています。","id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"２０２０年のオリンピック・パラリンピックに向けて、観光客を誘致するとか、アクセスの問題がやはり大きいのかなと思います。２０２０年には品川歴史館もできてから３５年を迎えるようになると思いますけれども、あそこの立地、今後のお考えをお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そこの上に建っているということで、庭園を見ていただければその跡だとわかるところです。そんなところで、今のところ、貴重な資料として生かしていきたいと考えています。","id":"exchange-003"},{"speaker":"つる委員","kind":"質問","question":"１５８ページの広報広聴費、１６１ページのシティプロモーション推進経費、１６５ページの固定資産台帳導入検討経費を伺います。タブレット端末を活用した会議等が高松市などでも行われていますけれども、そうした形でのさらなる推進を図るというお考えはいかがか尋ねました。","respondent":"秋山情報システム課長","answer":"タブレットは大きくてもＡ４程度で、Ｂ５程度というものが主流ですので、デメリットがまだあるかなというところが印象です。サーバーであるとか、幾つかの業者から売り込み等でデモ等はいただいていますので、この辺は現状は調査しています。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"１５８ページ、広報広聴費でツイッターについてです。この長野県佐久市の事例も含めながら、今後収集にも活かしたらどうかと思いますけれども、いかがか尋ねました。","respondent":"荒井広報広聴課長","answer":"現在のところ品川区においてはツイッターの活用を、災害時における緊急情報発信を中心に考えているところです。今後、そういった情報収集に活かすということも視野に入れながら、検討を進めていきたいと考えております。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"１６１ページ、シティプロモーション推進経費です。やはりその上で区として、品川区のブランディングをどのように考えているか、教えてほしいと求めました。","respondent":"荒井広報広聴課長","answer":"品川区の魅力をどういうふうに把握し、それをしていこうかというところと考えて答えさせていただきたいと思います。さらにそういったものをブラッシュアップして取り組んでいきたいという考えで、平成２６年度以降取り組みを考えているところです。","id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"先般こんの委員から提案させていただいた送迎保育ステーション事業、その世代を呼び込む手段として施策を講じているということであります。品川区からの提案という観点で、各自治体で採用しているＡＫＢ４８の「恋するフォーチュンクッキー」品川バージョン、お考えを説明するよう求めました。","respondent":"荒井広報広聴課長","answer":"ご提案については、今後の中で論議を進めたいと思います。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"それをアピールする対象ですとか、また売る手段をどうするのか、こういったことを積極的に品川区からも提案してほしいと求めました。発生主義の会計の導入の提案もさせていただいた中で、これについての現状の取り組みを、状況等教えてほしいと求めました。","respondent":"平澤経理課長","answer":"固定資産台帳の整備に関する検討状況です。昨年９月から東京都で実施しています台帳整備部会、先進自治体等の情報収集に当たっているところです。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"いわゆる課長クラスというのでしょうか、もっと言うと行政のマネジメント力の向上というのでしょうか、積極的な推進をお願いしたいと思います。これはどういった形で建設をしたのですかと現場の職員に聞いたら、建つとしたら何棟ぐらいができるのか、この辺を説明するよう求めました。","respondent":"多並公園課長","answer":"ＪＴ跡地につきましては今年基本設計を行い、来年度以降、詳細設計を行いながら整備を進めていく計画です。配置計画も含めながら検討していきたいということで、今後詳細について検討していきたいと思ってあります。","id":"exchange-009"},{"speaker":"向委員","kind":"質問・要望","question":"１９７ページの区長区議会議員選挙費の公報関係費についてお伺いしたいのですが、しながわＣＳＲ推進協議会を立ち上げることになったのか。そうなるとこういった選挙公報の配布数が変わってくるのではないかと思いますが、情報共有とかいうのはどうなっているのか尋ねました。","respondent":"工藤総務課長、秋山情報システム課長、諸岡選挙管理委員会事務局長","answer":"そういった中で、昼間人口が５０万人を超えているということで、協働のパートナーとしてますます重要になっているというふうに捉えております。… 誓約書というものはとりたててはありませんけれども、そういう公務員としての基本的な立場というところで縛りがあるのかなと考えております。… それは一軒一軒対応いたしまして、訪問して一軒一軒届けするというような対応はさせていただいているところです。","id":"exchange-010"},{"speaker":"向委員","kind":"質問・要望","question":"体育館の借りたりするのが１カ月前でないとできないとか、やはりお心くだきをいただきたいなと思いますが、このあたりはいかがでしょうか。いろいろな弁護士、専門の先生方もおっしゃっているのですが、そのあたりのお考えを最後に説明を求めました。","respondent":"工藤総務課長、秋山情報システム課長","answer":"ＣＳＲの勧誘企業によりまして、いろいろと活動という形態が異なると思います。いわゆる活動の状況等を見ながら、施設の条件等がありますので、よく所管を含めて研究していきたいというふうには思っております。 例えば一旦公開された情報は削除できませんよとか、そういう一般的なことを周知していくのがまずは大切かなと考えております。その辺の研修をしっかりやっていくというのが、まずは大切かと感じております。","id":"exchange-011"},{"speaker":"向委員","kind":"質問・要望","question":"今後も育てていっていただきたいのでぜひ、研究していただけるということでしたので、よろしくお願いします。区としてもぜひとも利用促進というのを、例えばそのためにも最低限のルール、いざというときのために。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初の３点、簡単でいいです、事業内容をさっと教えてほしいと求めました。お願いします。","respondent":"荒井広報広聴課長、柏原行財政改革担当課長、久保田地域活動課長","answer":"シティプロモーションについてのお尋ねです。平成２６年度の事業内容につきましては、どのように情報発信していくかということについての戦略プランを策定… そういったところの町会の役割というのは今後もますます深まっていくだろうということがあります。区との関係であるとか… そのうちこの間、板面の取り替え等の修繕を行ってこなかったもの３７０本を対象に、この３年間で集中的に建替えるというものです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"若者の意見というものを取り入れて反映していくべきだと思いますけれど、これはどのようなお考えなのか、お聞きしたいと思います。そういう目についたのかなとは思いますけれど、これまでに区内でこのようなことがございましたら、わかりましたら件数を説明するよう求めました。","respondent":"荒井広報広聴課長、柏原行財政改革担当課長、久保田地域活動課長","answer":"アンケートについてですが、区内の区民の方たちに対しては２,０００通、無作為抽出で郵送で行いました。こういったアンケートをどのように活用するか… 考え方としましては研究会を立ち上げまして、区の職員も当然入りますけれど、そういった中で調査研究をしていきたいと思ってあります。… それで今度建替える掲示板につきましては、今度はアルミ製のものですので、掲示板そのものが放火されるということはないと思ってあります。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"３年という計画ということで、なるべく早目に前倒しでお願いしたいと、これは要望させてほしいと求めました。法律相談に関してお伺いしたいのですけれど、弁護士の人数、どのように採用しているかを説明するよう求めました。","respondent":"荒井広報広聴課長","answer":"平成２４年度が１,５０５件、平成２５年度１月末で１,３１４件ということで、このところ推移しているかと考えております。品川区内で活動されている方というのが要件になっておりまして、現在１８名の方に委嘱しています。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"悩んでいらっしゃる方がどのような、弁護士の先生にお会いしてお話しした後、同じ案件だと３０分で３回とお聞きしております。そういうところへつないでいく、本当に小さい芽のうちに摘んで、ご相談をしっかり受けとめていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１４９ページの職員給与費関係と、もう一点は品川区の母子寡婦福祉連合会が運営をしています売店が閉鎖される問題、この２点をお伺いいたします。品川区互助会としての支援が必要ではないかと考えていますが、いかがか尋ねました。","respondent":"堀越人事課長","answer":"再任用が２５２名、嘱託非常勤というのは平成２６年度から任用制度の変更になりまして、いなくなる形になります。こちらはこのたび母子寡婦福祉連合会から、運営をしなくなったというお申し出を受けまして、区としてそれをお受けしたというものです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２年前にやはり職員費の質問をしたのですけれども、非正規雇用への置きかえをやめるべきであると求めたのですが、今回のテーマは公務労働です。教えていただきたいのと、先ほど財調人員が実際と比べると１４０人マイナスとなっていましたが、説明を求めました。","respondent":"堀越人事課長","answer":"こちらは母子寡婦の団体の中の問題だと思いますので、特に私のほうからという考えはございません。民間にできることは民間にお願いして、我々の中では効率的によりよいサービスを目指していくというのが、人員体制の考え方です。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"この関係がサービスを買うお客さんと、またサービスを提供する労働者、こういった関係に変わってきているのではないでしょうか。この件はいかがか尋ねました。","respondent":"堀越人事課長","answer":"我々といたしましては、しっかりと区民サービスに努めていく、効率的な執行体制の中でやっていくというのが基本の考え方です。繰り返しになりますけれども、そういうような考え方です。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私の質問は、区民のサービスが守れていないのではないか、そのことを言っています。行革のコスト削減は大事ですが、生存権、また発達権を守る区政をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"次に１８７ページの防災対策費で国道１５号線災害時徒歩帰宅者支援対策経費、時間があれば総務費全体で契約について伺います。いつから導入されるのか、簡単なロードマップ、スケジュールを説明するよう求めました。","respondent":"秋山情報システム課長","answer":"それから平成２８年１月になりますと、番号のカードをその時点から申請により交付することになります。情報の連携開始ということで、国同士が情報の連携をする、そういうステップでやっていくというスケジュールになっております。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問","question":"品川区はどの課がこれに当たるのでしょうか。これがそうなのか、それとも場合によっては平成２７年度でもいいですよと書いてあるのですけれども、その辺を説明するよう求めました。","respondent":"柏原行財政改革担当課長、秋山情報システム課長","answer":"全庁的な連絡体制、調整的なものをつくりまして、全庁調整を図っていこうと考えています。その中で国の動き等を見ながら、必要であれば担当セクションの話も出てくるかもしれませんが、現段階ではそういう形で動いているです。 私のほうから、予算書の番号制度対応委託についてご説明します。なかなか詳細が出てこないということで、予定としましては平成２７年度に大きな改修ということになると思ってあります。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"提案","question":"地域外の第三者の視点などを存分に活かせる仕組みの構築ということで提案させていただいたのですが、本当に期待しています。シティプロモーション、その次に観光アクションプラン拡充と載っているのですけれども、この二つの関係性について説明を求めました。","respondent":"荒井広報広聴課長","answer":"シティプロモーションは全体的なといいますか、統括とまでは言いませんけれども、観光アクションプランもシティプロモーションの取り組みをしていく上での一つの大事な計画だというふうに捉えているところです。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういうことは結構あるものですから、私が今回お願いしたいのは、それについて検討していただきたいということです。ぜひ大人の、やはり若い男女の方もぜひ入れていただいて検討してほしいと求めましたが、そのあたりはいかがか尋ねました。","respondent":"荒井広報広聴課長","answer":"今おっしゃっていただいたさまざまなアイデアを吸収していく、そういった柔軟な姿勢を持ちながら、委託業者を含めてまた区民の方たちの意見も何らかの形で酌み上げながら、進めていきたいと考えているところです。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひこんな話も進んでいますので、品川には品川カブをはじめ、大井人参とか、居木橋カボチャとか、いろいろあるわけです。こういったものをぜひ武器として使っていただきたいと、６年半ありますので活用してほしいと求めましたが、その辺はいかがか尋ねました。","respondent":"柏原オリンピック・パラリンピック調整担当課長","answer":"オリンピック・パラリンピックに向けていろいろな方がいらっしゃるということで、おもてなしとか、いろいろな視点があります。多くの方に来ていただいて、品川区がいいまちだと言っていただけるようなプロモーション、周知等々図っていきたいと考えています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"経緯のお話があったのですけれども、２０１２年２月の都議会の一般質問で、伊藤こういち都議会議員が石原都知事に対して質問いたしました。最後に、これの拡大については今後どのようにお考えになっているのか説明を求めました。","respondent":"鈴木防災課長","answer":"この徒歩帰宅者支援の対策ですが、今回初めての取り組みということで国道１５号線、実績のあるところでお願いをしております。訓練の実施等である程度成果が見えてきた時点で、ご指摘のありました国道１号線、取り組んでいきたいと考えております。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"意見","question":"まさに点と点を結ぶラインの形成ということで、非常に重要な事業だと思いますので、ぜひ拡大をお願いしていきたいと思います。契約については、時間がないので、また新たなところでやらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問・要望","question":"１６１ページ、１７５ページのオリンピック・パラリンピック開催周知事業、国際交流なども関連してくるので伺っていきたいと思います。それともう一度確認ですが、中長期的な流れというのですか、。","respondent":"荒井広報広聴課長","answer":"さらにそれを土台にして次に進んでいくといったようなことを段階的、らせん的に進めていくものではないかと考えているところです。区内部だけではなくて、こういったことを品川区はやっているということを全体的に発信していきたいと考えているところです。","id":"exchange-028"},{"speaker":"渡辺委員","kind":"質問・要望","question":"１人の力というのも当然ばかにできないものがあって、その辺の含みが、可能性があるかどうか。委託の内容とあわせて伺います。","respondent":"荒井広報広聴課長","answer":"一つ目の委託の内容ですが、平成２６年度につきましては戦略プランをつくるというのが最終的な目標になっております。そういった行動につながるような気持ちの醸成といいますか、気持ちを高めるといいますか、そういったことを一つの狙いとしているところでもあります。","id":"exchange-029"},{"speaker":"渡辺委員","kind":"質問","question":"そして国際交流の観点に絞って伺いますが、行政ですからいろいろ幅広くやらなければいけないと思いますが、どう表現されるか伺いたいと思います。その点についてのお考えを、文化で一つ、スポーツの観点、それと国際の観点で伺えればと思います。","respondent":"安藤オリンピック・パラリンピック推進担当課長、寺嶋協働・国際担当課長","answer":"これは一つですけれども、それが２０２０年を経過してもブラインドサッカーができるようなスポーツのあり方を、我々で考えていきたいと思っています。うちの所管では芸術祭をやっていますので… ポートランド市からいらっしゃった方が商店街を見学しまして非常におもしろかったと、次回もまたぜひ案内してほしいという声も実際に届いています。","id":"exchange-030"},{"speaker":"大倉委員","kind":"質問・要望","question":"１６９ページの生活安全サポート隊活動費、１８５ページの防災センター運営費について、伺います。民地の枝が折れたとき、倒木が民地であったのかどうかお知らせいただき、その対応についてもお聞かせほしいと求めました。","respondent":"稲田道路課長","answer":"対応した職員総数は２０名、建設防災協議会、５社５班で対応を実施しました。基本的には持っている方が対応していただくというのが基本ですけれども、その辺はまず一次的に通行の支障にならないように区が実施しまして。","id":"exchange-031"},{"speaker":"大倉委員","kind":"意見","question":"民地の枝折れ等も区のほうで対応してくださったということで、スムーズな対応をしていただいたのだと思います。区は対応できるのか、できないのか、お願いしますとの意見を述べました。","respondent":"稲田道路課長","answer":"民地の木についての対応ですけれども、これはやはりその所有者が、基本的には実施していただくというところでございまして、我々区とすれば、造園業者とか紹介しながら、ご自分での実施ということでお話ししています。","id":"exchange-032"},{"speaker":"大倉委員","kind":"質問","question":"次に、生活安全サポート隊の費用ですが、今回７００万円近く増えているのですが、パトロール隊の車を４台購入したと伺っています。どういった検討がされて、今回購入をして何年乗っていただくかとか、どうして今の時期なのかという検討がわかればお話しいただくよう求めました。","respondent":"上垣外生活安全担当課長","answer":"今回、買い替えを予定しております車につきましては、平成１６年に購入させていただきまして、その後約１０年間乗っております。それを踏まえまして、今回この４台について買い替えをお願いするところであります。","id":"exchange-033"},{"speaker":"大倉委員","kind":"質問・要望","question":"４月になると消費増税で８％と、その前に買うという検討はされたのかどうか、お話しほしいと求めました。例えば都市型水害であれば３０センチ水が増えるとドアが重いとか、ぜひ取り組んでいただきたいのですが、そこのお話もお願いします。","respondent":"上垣外生活安全担当課長、鈴木防災課長","answer":"１点目のリースか、あるいは塗装と特殊な仕様を施しておりますので、リースには必ずしもなじまないと考えました。購入時期につきましては、まだ消費税の導入が８％に上がるという前の段階での検討です。 防災センターのリニューアルの検討ですが、ご指摘のありましたような体験型のコンテンツも含めまして、今後しっかりと検討していきたいと考えております。","id":"exchange-034"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は１５５ページの人権啓発費のうち男女共同参画事業と、１７３ページの生涯学習推進事業のうち区民大学、公開講座について質問します。１５５ページの人権啓発費のうち、男女共同参画事業について質問いたします。","respondent":"提坂人権啓発課長","answer":"平成２４年度が４４.１％、今年度が１月末までの数字ですけれど４９.４％ということで、５％の伸びがあります。登録団体の数につきましては、ここのところ４５団体を増減しているような状況が続いております。","id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これを見ますと利用率が低下していると評価してもよろしいのでしょうか。登録団体数も平成１７年度は９３団体ありましたが、現在それから半減しているように思われるのですが、この数字をどのようにお考えか尋ねました。","respondent":"提坂人権啓発課長","answer":"登録団体を増やすように努めたいところです。平成２５年度はセンター改修工事を行いまして、定員を３６人まで利用可能にしまして、これから利用実績を伸ばしたいと考えております。","id":"exchange-036"},{"speaker":"鈴木（博）委員","kind":"質問","question":"どのような理由で、改修工事を行われたのでしょうか。改修工事を行うに当たって、力を入れたところとか、ここを変えたかったのでここを変えたとかいうようなところがあったら教えていただけますか。","respondent":"提坂人権啓発課長","answer":"見晴らしもよくするということで、利用者の方と職員とのコミュニケーションを増進させるということで、効果があったものです。それを最大３６人利用可能にしまして、自前の会議室で講座を行ったり、登録団体の方の打ち合わせが可能にしたという所存です。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"提案","question":"に男女共同参画センターにも、きゅりあんと同じような名称とか愛称を公募したらどうかという提案が出されております。会議室の利用は登録団体に限られておりまして、登録団体でないと利用ができないので、これに関してはご検討されたのか尋ねました。","respondent":"提坂人権啓発課長","answer":"センターという名前がわかりにくいですが、名称についても検討はしていますが、なかなか適当な名前が見つからないというのが実情です。本来の目的から外れたようなところから申請が出される可能性もありますので、その辺はちょっと検討課題とします。","id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今年度の予算でも２７０万円が計上されておりますが、どのような点を中心に基本計画の見直しが行われる予定なのでしょうか。ポイントの解説をお願いします。","respondent":"提坂人権啓発課長","answer":"東京都が平成２４年３月に、平成２４年度から平成２８年度までの５年間の基本計画を策定しました。それから、関係機関へのヒアリングによる現状把握と経過方針、各所管課への調査による施策把握と具体的施策の見直しに着手したいと考えております。","id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"デートＤＶについてお尋ねします。まだ若年層なので、例えば高校とか中学校などに、啓発のための出張講座というのは行われているのか尋ねました。","respondent":"提坂人権啓発課長","answer":"それから昨年１２月には、子どもと接する機会が多い区の児童センター職員２３名を対象に講座を行いました。引き続き昭和大学附属看護専門学校の新１年生を対象に行うのと、今の段階で品川エトワール女子高校の生徒を対象に行う予定です。","id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問","question":"公立の高校などは、予定とか計画というのはあるのか尋ねました。","respondent":"提坂人権啓発課長","answer":"以前に八潮高校の生徒を対象に実施しました。","id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"意見","question":"『マイセルフ』の４４号で、性別にかかわらず、適材適所が実践できればよいと述べられています。共同参画社会の推進のために、共同参画センターが果たす役割はより一層重要になると考えられますので、今後のご発展を期待したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"こんの委員","kind":"質問・要望","question":"１８３ページの防災地図情報システムについて、この２点をお伺いしたいと思います。１月から運用開始という形で、これはどのようにお考えになっているのか、お聞かせほしいと求めました。","respondent":"柏原行財政改革担当課長、鈴木防災課長","answer":"私からは、町会・自治会のあり方の研究等に関するご質問についてお答えいたします。そういったところを区独自の中で検討調査いたしまして、あり方等について今後改めて検討していきたいといったところで、始める事業です。昨年１２月に東京消防庁のほうから、今回その改修をいたしまして、消防庁の管理する水利も見ていただけるように改修したところです。","id":"exchange-043"},{"speaker":"こんの委員","kind":"質問・要望","question":"消火器は消火器の地図とばらばらのものを持っていて、そういった意味では非常にこれはいいシステムでありますし、活用してほしいと求めました。今紙ベースでしていただけるということですので、訓練の中でも生かされるということが大事だと思うので、その点いかがか尋ねました。","respondent":"久保田地域活動課長、鈴木防災課長","answer":"こうした中で、私どもより町会の支援をさらに進めるために、地域活動課に町会の活動支援をする相談窓口を設けていきたいと考えています。例えば地域の課題、横断的な課題であれば庁内連携で対応していきたいと思ってありますし… 防災地図の活用についてのお尋ねですが、委員ご指摘のように訓練等で消防水利や防災関係の情報を活用していくのは非常に有効だと思われます。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうかいいパートナー、さらなるパートナーとなるような関係を築いていってほしいと求めましたので、よろしくお願いします。ただホームページ上だけではなかなかだめだというところは、紙ベースということも先ほど伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"中塚委員","kind":"提案","question":"ぜひこうした避難行動とセットで、感震ブレーカーの設置助成を導入してほしいと求めましたけれども、伺いたいと思います。これはこれでもっと対策をたてていかなければならないと思いますけれども、あわせて伺いたいと思いますとの意見を述べました。","respondent":"鈴木防災課長","answer":"在宅で医療器具をお使いの方は、その電源も落ちてしまうという課題がありますので、あわせてその対策もセットで実施することが重要と考えております。ご提案のありました助成という点については、区として今、取り組むという考え方はないです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"震災時も火災発生の発見のためにも、一般世帯へも設置助成を広げていくべきだと思いますが、いかがでしょうか。それだけに発生の抑制、また発生の発見はとても大事だと思いますけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"自助で取り組んでいただく個人の財産、住宅の部分に関するものですので、区でのその辺についての助成は困難かなと考えているところです。もちろん啓発、周知はしてまいりますが、それに対しての助成を行うという考えは現在ございません。","id":"exchange-047"},{"speaker":"中塚委員","kind":"提案","question":"マンションも含めた一般世帯に拡大して、設置を徹底してほしいと求めましたけれども、この点伺いたいと思います。それぞれぜひ進めてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"この訓練等における使用の結果を踏まえまして、今後の検討をしたいと考えているところです。現時点で雨水タンクを設置するという予定はございません。","id":"exchange-048"},{"speaker":"中塚委員","kind":"提案","question":"そもそも学校の避難所について伺いますが、現在５２の避難所がありますけれども、逆に進んでいない避難所は幾つか伺います。住民に対して避難所運営のパンフレットを作成して、事前に配付するなど、ぜひ進めてほしいと求めましたがいかがか尋ねました。","respondent":"奥田河川下水道課長、鈴木防災課長","answer":"雨水利用タンクについてですけれども、既に平成１８年度から保育園や小中学校、集会所等の区有施設に設置しています。委員からありましたように雨水利用タンクにつきましては、避難所などに順調に整備していると考えています。 私からは避難所の環境とか対応に関するプランの作成についてお答えいたします。このマニュアルの見直しであったり、レベルアップを図っていただくような支援をしていきたいと考えているところです。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"避難所運営のマニュアルについては、ぜひパンフレットをつくって事前に住民に周知をしてほしいと求めましたので、この点伺いたいと思います。駅前とかにあります公衆トイレというのでしょうか、ここも下水道の耐震化を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木防災課長、多並公園課長、奥田河川下水道課長","answer":"避難所に関する周知については、パンフレットに限定せずいろいろな機会を捉えて、区民の皆さんにしっかりとお伝えしたいと考えております。マンホールトイレにつきましては、公園の新設・改修の際にこれまでも進めておりますが、今後もしっかり進めてまいりたいと考えています。下水道の耐震化についてですが、都と連携いたしまして既に避難所などにおいて実施しております。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問","question":"１４９ページの情報システム運営費、１５５ページの職員健康管理費を伺います。情報システム運営費ですが、そのものずばりではなくて、ここの中のシステムということについて伺いたいと思います。","respondent":"秋山情報システム課長","answer":"一つ目のつくるという部分は通常、開発費ないしは改修というような言葉を使っております。使い続けていくために機器の保守、点検ですとか、システムのプログラムの軽微な修正であるとか、そういうものが運用保守になるです。","id":"exchange-051"},{"speaker":"大沢委員","kind":"質問","question":"１０桁になったり、そこのところはどういうふうにお考えになりながら、金額というかそこのところの取り決めをされているのか説明を求めました。","respondent":"秋山情報システム課長","answer":"３桁なり、４桁、５桁というのはシステムの改修の大きさによって違ってまいります。小さいシステムであればＳＥが１人で１カ月、ということであれば、１人／月の単価ということになりますから、そういう違いが出てくるです。","id":"exchange-052"},{"speaker":"大沢委員","kind":"質問・要望","question":"１,０００万、１億と金額のばらつきが出てくるのではないかということで今聞きましたので、ちょっと訂正をしていただきたいです。それと、ＳＥについての上、中、下ということを今おっしゃいましたけれど、この上、中、下って誰が決めるんか尋ねました。","respondent":"秋山情報システム課長","answer":"リーダー的なＳＥと、プログラムを組むだけのＳＥということで役割によって金額が違うです。１,０００万、１億の単位ですけれど、その辺が変わってくるです。","id":"exchange-053"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこを気をつけないと予算組みとか、決算、数字についての透明性が保たれないのではなかろうかと。そこについてご感想があったら教えてほしいと求めました。","respondent":"秋山情報システム課長","answer":"どのぐらいの時間で働けばできるよという見積もりが出てきますので、そういうものを積み上げていくです。手法とかありますので、それに基づいて我々もしっかり見積もり等を精査して、透明性を保っているです。","id":"exchange-054"},{"speaker":"大沢委員","kind":"質問・要望","question":"十分な精査、要は基準が設けにくいものなのでそこのところは精査なり、しっかりとやってほしいと求めました。我々もそうですが、品川区の名刺に三つ青い線があるんですけれども、あれが意味するところは何なのか説明を求めました。","respondent":"荒井広報広聴課長","answer":"品川区の名刺の三つの線の意味するところですが、新感覚、チャレンジ精神、サービス精神です。","id":"exchange-055"},{"speaker":"大沢委員","kind":"質問","question":"そこのところでサービス精神、チャレンジ感覚ということで、日々皆さん御苦労されているのは十分にわかります。組織的なものと個人的なものの精神疾患にどういうふうに対処するかという、どのように区では対処されているのか説明を求めました。","respondent":"堀越人事課長","answer":"メンタルヘルスの関係ですけれども、精神疾患等につきましては、なかなか原因が特定するのが難しいと考えています。休職を取ってまた健全な状態、そういう対応をして、品川区の職員として職務等を担ってもらえるような形での対応を図っているところです。","id":"exchange-056"},{"speaker":"大沢委員","kind":"質問","question":"非常に不明瞭なところをどういうふうに対処しながら線引きをして、相談機能を充実したり、そういう取り組みをするのかなということを伺いました。時間が短くなってしまったので、お答えできる範囲で結構です。","respondent":"堀越人事課長","answer":"原因等をカウンセリング等で十分に聞きながら、話を聞きながら対応しているところです。休職ですとかそういった対応ですね、福利厚生的な面でいえば保健対応ですとか、総合的に対応しています。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"１６５ページの町会・自治会のあり方と区との協働に関する調査研究、それとふれあい掲示板についてお尋ねしたいと思います。ふれあい掲示板も先に言いますけれども、そもそもこのふれあい掲示板の目的は何か尋ねました。","respondent":"柏原行財政改革担当課長、久保田地域活動課長","answer":"今回の町会・自治会のあり方の検討の部分ですけれども。そういった中で行うものが、今回の調査研究です。 １点目が行政情報の周知をするということ、また２点目が地域の情報伝達といった大きな目的を持ってあります。それで町会・自治会と一緒になって、その維持管理等を行ってきたというものです。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"若い人はいるのですか、この中に。それをちょっと行政側からの情報の発信の工夫をぜひしてほしいと求めましたが、この考え方をお聞きしたいと思います。","respondent":"柏原行財政改革担当課長、久保田地域活動課長","answer":"そういったところを、そもそものところであり方というのはどういうものなんだろうという調査研究を、区独自としてやっていきたいといったものです。その調査研究をやっていく中で… できるだけ情報を集約して、誌面の節約に努めているといったところで、そのあいたところに地域の情報等を張っていただくといった工夫をしています。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"宣伝してあげるというような、ホームページでももちろんやっていますけれども、それだけではだめなのですね。幼稚園もあるわけですから、その辺の部分はこの調査に関して加えることを考えられるか、お聞きしたいと思います。","respondent":"柏原行財政改革担当課長","answer":"こちらの研究会はそもそも町会・自治会、区とのあり方というところがメインで調査研究、検討ということになっています。今、そういった町会・自治会の生のお声を伺いながら進めていくということですので、そういう声を聞きながら研究を深めたいと思ってあります。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、ぜひ若い方たちが一緒に考えていかれるような仕組みを、ぜひつくってほしいと求めました。それと、時間がなくなってしまっているので要望になりますが、地域の中で非常にいろいろな問題が生じています。","respondent":"久保田地域活動課長","answer":"私どももいろいろな課題もご相談いただいた際には、早急に現場に行って確認をしながら、町会・自治会の人と解決に向けて行動しています。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"私は１６２ページの財政管理費、１７４ページの区民施設費の２７節公課費、１８５ページの防災対策費の避難所管理費についてお伺いいたします。６年たちまして２３区の状況はどのような公開状況になっているのか、区は把握されていますか尋ねました。","respondent":"本城企画財政課長","answer":"予算の審議に当たって、各区それぞれ、審議の始まる事前に予算案の概要というような形でＰＲしているものと認識しております。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問・要望","question":"議会の予算審議の前に２２区全てが公開しています。ですからぜひ、予算審議の前にぜひ市民に公開をしてほしいと求めましたが、いかがか尋ねました。","respondent":"本城企画財政課長","answer":"ホームページにおきましてはちょうど議会に対して予算の提案理由という形で区からご説明させていただいた、ホームページのほうに上げしています。そういう意味では、議会への情報提供とバランスをとりながら、お知らせをさせていただいているところです。","id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"私たち議員としても市民の代表として広聴活動をしてこの審議に当たるわけですから、検討を求めたいというところで次に行かせていただきます。予算書では隊員が１４名となっておりますけれども、在任年数の基準があるのかどうか、現職の年齢構成はどうなっているかをお伺いしたいと思います。","respondent":"上垣外生活安全担当課長、本城企画財政課長","answer":"それ以前の若干例外はございましたけれども、通常は５年ということで交替いただいております。年齢につきましては、警視庁を定年で退職された方が受け継ぐことになっておりますので、６０歳から６５歳前後が中心となっております。 まず第１弾でプレス発表しましたという、予算案の情報提供は他区と同様の形でしているということをご説明させていただきました。ちょっと委員のほうで誤解があったと思いますので、その点ご理解いただければと思います。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問・要望","question":"私が確認したときはもうもっと前にほかの区は出ていましたので、だとすれば議会がどうのこうのということではなく、要望します。非常勤の報酬についての考え方をお伺いしたいと思うんですけれども、比較が適当かどうかは別にして、整合性がとれているとお考えか尋ねました。","respondent":"堀越人事課長","answer":"非常勤職員の報酬につきましては、それぞれ職務内容、専門性、勤務日数等を踏まえて、それぞれの職に合った内容で決定しているというものです。","id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"女性の割合を増やしていくという提案をしておりましたが、その後の学校避難所連絡会議の男女の構成率の現状を把握されているのか、伺います。なぜだかおわかりか尋ねました。","respondent":"鈴木防災課長","answer":"まいりますと、区内全ての５２の避難所で、合計しまして９７人の女性の委員がいらっしゃいます。男性の方にちょっと外を使っていただくとか、そういう工夫もこれからしっかりとお伝えして、避難所ごとで考えていただきたいと考えております。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"いざ震災になったときに何で自分たちは外なんだ、ぜひそういうことを進めるとともに、中で議論ができるような体制を工夫してほしいと求めました。昨年度そのプログラムの実績と、今後新年度拡充に向けた予算化がされているのかどうか、お伺いしたいと思います。","respondent":"鈴木防災課長","answer":"どういう判断をするか、またどういう行動をするかというのを、ご自分たちで考えていただくというような教材もあります。それから、ぜひ取り組んでいただいて、地域の方たちがご自分たちの判断や行動で安全が守れるというふうに進めていきたいと考えています。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問","question":"次は、１７４ページの区民施設費の２７節公課費についてですけれども、今回の公課費、昨年より、２,２００万円ほど増額となっています。昨年は０円だった光林荘の公課費が、今年は政策経費として２,３４０万円ほど計上されていますけれども、その理由をお伺いいたします。","respondent":"久保田地域活動課長","answer":"保養所等で使っているということがございまして、日光市に支払うための金額ということで、およそ２,３００万円ほど支払うものです。","id":"exchange-068"},{"speaker":"井上委員","kind":"質問","question":"品川荘の場合には、昨年も今年度もあって、どうして光林荘だけが、この法律は最近できたわけではなくて、あった法律だと思いますけれども、なぜ光林荘だけが今年２,３００万円という形になるのか尋ねました。","respondent":"久保田地域活動課長","answer":"教育施設という形で平成２３年３月３１日までは使っておりましたので、そのときにはそういった交付金というものがかからなかったです。平成２４年度から転用していますので、平成２６年度から発生するということで、それぞれ基準に基づいてお支払いをするというものです。","id":"exchange-069"},{"speaker":"井上委員","kind":"質問・要望","question":"平成２４年から貸出し施設としたということで、でも３月３１日現在の算定の１.４％というふうになると、そういう話なのか尋ねました。","respondent":"久保田地域活動課長","answer":"平成２５年度分をさかのぼって支払ってくれというものではございませんで、平成２６年度から発生したというものでございまして、算出されたものです。","id":"exchange-070"},{"speaker":"井上委員","kind":"質問","question":"そうすると、算定額の１.４％の交付ということになると、算出された光林荘の財産というのは、日光市が決めて、これだけですよということにはならないと思いますけれど、光林荘の財産価値というのはどのぐらいというふうに計算されて、この金額を支払った、交付しているということになるのか尋ねました。","respondent":"久保田地域活動課長","answer":"やはり委員ご指摘のように、それぞれつき合わせて協議をしながら、今回のものにつきましては算定標準額については約１６億円ほどになってあります。これに１００分の１.４を掛け合わせまして、２,３００万円を算出したというものです。","id":"exchange-071"},{"speaker":"井上委員","kind":"確認","question":"地域センターのお話ですけれども、この間借りに行った方が、空気が抜けていてその場で借りてこられなかったというお話をいただきました。メンテナンスとかそういったことは定期的にするようなルールがちゃんと定められていて、それが執行されているのかどうか、その確認をお願いします。","respondent":"久保田地域活動課長","answer":"地域センターで貸し出している車椅子につきましては、障害者福祉課のほうと連携をいたしまして地域の方に貸し出しているというものです。","id":"exchange-072"},{"speaker":"井上委員","kind":"質問","question":"借りに行ったときに使えないということにならないように、ぜひ皆さんに周知をして、メンテナンスをお願いしたいと思います。１５１ページの私立幼稚園の補助金についてですが、その中で私立だと３歳児のお子さん、ご指導されているか尋ねました。","respondent":"立川保育課長","answer":"私立に対する指導ですけれども、こちらにつきましては私立幼稚園協会等の会合の席で、常に子どもの健康と安全についてはお願いしています。","id":"exchange-073"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは１８５ページの防災センター運営費について、またもう一つは１６７ページの「家庭の日」啓発事業についてお伺いしたいと思います。平成６年に開館して２０年目ということで、具体的に違いといいますか、どのような形になるのか教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"３Ｄで飛び出す映像や椅子が揺れるというような映画で、災害の恐ろしさを知っていただくのが、今までのセンターの目的でございました。近年、それともう一つはワークショップによる考えるという部分、この二つを大きな柱としてリニューアルを検討しています。","id":"exchange-074"},{"speaker":"山元委員","kind":"質問","question":"その検討委員会と言うのですか検討されたメンバーというのは、どういう方たちでこのようにしようとお決めになったのか、説明を求めました。","respondent":"鈴木防災課長","answer":"平成２５年度、今年度の検討につきましては、またどんなコンテンツを入れるかというような基本の部分を検討するというのを。委員会のような検討の会議をつくって決定したものではございませんので、区の防災課と専門家、検討したというのが現在の内容です。","id":"exchange-075"},{"speaker":"山元委員","kind":"質問・要望","question":"もうちょっと今度は具体的にお話を聞かせていただきたいのですけれども、また何か映像を上映なさるというお話がありました。今までの３Ｄを使ったものがなくなるということは、どういうものが実際に触れるというか体験できるのか、もうちょっと教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"イメージとしては、ワークショップをやる上で必要になる情報を映像に映し出したり、というのを今考えているところです。それを実際に手に取って、どういうふうに使うのかとか、そういうところも体験していただくという趣旨の展示を想定しているものです。","id":"exchange-076"},{"speaker":"山元委員","kind":"質問・要望","question":"ここでちょっとお聞きしたいのは、例えば今までの防災センター、そういう看板的なものが足りないのではないかと思っています。検討する中に入っているのかということも教えていただきたいのと同時に、２階の食堂の入り口も、お考えを教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"それから２点目の展示の表示等、そういった点についても検討の中で、検討したいと考えております。明確にここからが防災センターということと、来た方が入り口からわかりすいサインと合わせて、しっかりお伝えできるように検討したいと考えています。","id":"exchange-077"},{"speaker":"山元委員","kind":"質問・要望","question":"できればそこに申込用紙を置いていただけるような工夫もしていただきたいと、これは要望ですので、よろしくお願いしたいと思います。今年で４０周年ということで、今までやってきた手応えというのでしょうか、どんな状況なのか教えてほしいと求めました。","respondent":"福島青少年育成課長","answer":"私どもとしましては、明るい家庭づくり運動を推進していくということでＰＲを続けてまいりました。こちらは４０周年を契機としまして、これまで以上に周知啓発に努めていきたいと考えているところです。","id":"exchange-078"},{"speaker":"山元委員","kind":"質問・要望","question":"この「家庭の日」は本当に大事にしていただきたいし、どこまで皆さん周知されているのかというのはちょっと疑問であります。そういう意味では今回冊子を作成するということで、１６０万部ですか、どの辺まで配ろうと思って、全家庭に回るまであるのか尋ねました。","respondent":"福島青少年育成課長","answer":"「家庭の日」通信というのは発行しますけれど、１回２万８,０００部です。各施設にて配りたいと考えています。","id":"exchange-079"},{"speaker":"藤原委員","kind":"質問","question":"普通財産で調査するだけで８７４万円かけるというのは、これはどうかなと思いますけれども、お伺いします。これは財調でちゃんとされるのですか、その辺についてお伺いします。","respondent":"平澤経理課長、柏原行財政改革担当課長、寺嶋協働・国際担当課長、安藤文化スポーツ振興課長、本城企画財政課長、井浦戸籍住民課長","answer":"９００万円弱とありますのは、まず場所ですが、旧豊葉の杜中学校、旧八潮北小学校ということで、普通財産として貸し付けている部分です。… 区の今後の跡地の検討に係る経費ということなんですが、こういった検討をする際には、これからどういった形で使っていくのかという。… 協働の視点から地域に向けて情報を発する形で社会貢献を実践しているという考えに基づきまして、積立をいたしました。… 当初は横断幕は必要がないというような判断でございました。","id":"exchange-080"},{"speaker":"藤原委員","kind":"質問","question":"どっちがどういいのか判断ができなくて質問しているのですけれども、やはりその辺はちゃんと考えてやっていかないといけないと考えています。今後そういう意味において行政サービスとして考えていくのかということが１点と、日曜開庁を今やっている課がありますね、その２点をお伺いします。","respondent":"井浦戸籍住民課長","answer":"１点目の自動交付機等につきましては、２３区でさまざまな取り組みもありますので、充実を図ってまいりたいと考えています。２点目の日曜開庁につきましては、平成２０年の開始当初に、実施状況を見ながら判断してまいりたいと考えています。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"確認","question":"たしか自分宛の年賀状に対して、直筆で返事を書くのは認められていいと思いますが、それを確認したいのと。それからこういうことに対してのいわゆる規定、罰則とかあるのでしょうかということ。","respondent":"諸岡選挙管理委員会事務局長","answer":"暑中見舞いにつきましては、電報あるいはファックス、どのようなものであっても禁止されております。これに関しましては特段罰則はございません。","id":"exchange-082"},{"speaker":"伊藤委員","kind":"確認","question":"これは今確認しますが、挨拶文等の規定に触れると思いますが、いかがでしょうか。説明を求めました。","respondent":"諸岡選挙管理委員会事務局長","answer":"レイアウトとか、そのようなものにもよると思いますけれども、その上で判断されるべきということにされております。アドバイスということで申し上げますと、法律に抵触する可能性が出てまいりますというようなことはアドバイスします。","id":"exchange-083"},{"speaker":"伊藤委員","kind":"確認","question":"確認程度で、やはりそれは共通認識として対処していきたいと思いますので、改めてこういうふうな形での啓発をお願いしておきます。要はそれを吸い上げて、まずどういう問題が出たと把握したでしょうかということが一点と、普段はどう計画をしていくかということを説明するよう求めました。","respondent":"鈴木防災課長","answer":"今度各地区の防災協議会の会長にお集まりいただく会議でご報告をしながら、またご意見をいただくという予定で、今取り組んでいるところです。具体的にいただいた意見の中には、今回一斉訓練を開始しまして２回目の実施になりました。","id":"exchange-084"},{"speaker":"伊藤委員","kind":"質問","question":"それも例えば今年１年間でつくっていくとか、そのことについてどうお考えか、もう一回お聞かせください。これから順次計画を立てて、備品等に対処すべきと思いますが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"その点につきましては区のほうでもしっかりと支援をしまして、支援なりたたみかけをしていきたいと考えております。マンホールトイレをメインに考えておりましたが、あわせてそれぞれの対応を進める上で、ちゃんと目指すように体制を整えたいと考えております。","id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問","question":"今、残念ながらこういうことで明らかになったわけだから、本当に一斉防災訓練をやってよかったじゃないですか。要は緊急時にあのヘリポートから区役所までの間の通路と言ったらいいのですかね、物資を輸送する通路が現状では道路しかない。","respondent":"多並公園課長","answer":"予算案の中にもあります備蓄倉庫の整備、それが邪魔にならないように地下式でできるような形だということで、３００平方メートルほど予定しています。そういう部分では道路確保がありますけれども、今後は２６号線全体の整備も含めながら、今のところ考えているところです。","id":"exchange-086"},{"speaker":"伊藤委員","kind":"質問","question":"やはりいろいろなルートを確保していったほうが大きな災害の際には、想定外の被害というふうに言われたじゃないですか。例えばさまざまなルートを考える、非常時だけ通用する仕組みを考えるなり、検討をお願いできないか尋ねました。","respondent":"多並公園課長","answer":"一つの考え方としまして、そこについてもつながるようにということで、ルートを確保することも考えてあります。そのようなことで可能なところがもう少しないかというのを、いろいろな角度から研究してまいりたいとは思ってあります。","id":"exchange-087"},{"speaker":"伊藤委員","kind":"意見","question":"このことについて要は助成金を出してほしいという話になるのだけれども、１０年という更新のときに、品川区のお考えをお聞かせください。お願いいたしますとの意見を述べました。","respondent":"上垣外生活安全担当課長、本城企画財政課長","answer":"品川区内では設置を望む声がたくさんあるところでありますけれども、まだ行き渡っていないというのが現状ですので、今の段階ではやはり設置促進に係るという意味での助成に力点をおきまして考えていきたいと考えております。 現行制度におきましても財調の関係で申せば、防犯カメラの設置の部分については、財調で算定されているという意味では、２３区の共通課題という認識の上に立って事業を展開している面は、ある程度あると考えているところです。","id":"exchange-088"},{"speaker":"伊藤委員","kind":"質問","question":"更新が必ず来るのです、機械ですから。こういう制度をつくったほうが防犯カメラの増設についてはプラスになると思いますが、改めてご答弁をお願いいたします。","respondent":"上垣外生活安全担当課長","answer":"７年間この防犯設備を利用していただいて、さらに設備後の防犯活動を継続するなど一定の要件がある場合には、この制度を活用していただくというのが一つの手であろうと考えております。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"確認","question":"今のご答弁で、７年後にもう一度対応できるというか、その確認だけお願いいたします。","respondent":"上垣外生活安全担当課長","answer":"そのとおりです。７年というのが要件になっています。","id":"exchange-090"},{"speaker":"高橋委員","kind":"確認","question":"１６６ページの地域振興費ですが、確認したいのですが、こちらはどちらに当たるのかということです。そこで、そういった観点でこの地域課題の自主的解決の支援については、どのようにお考えか尋ねました。","respondent":"久保田地域活動課長","answer":"町会・自治会の中ではさまざまな横断的な課題の対応が迫られているといったところで、そういった支援を品川区として進めていきたいと思ってあります。弁護士等の専門家とも連携をしながら、より的確、効果的に課題解決に向けて一緒に取り組んでいきたいと考えています。","id":"exchange-091"},{"speaker":"高橋委員","kind":"質問","question":"ですからそのあたり、どのように解決を図っていくのか、もう少し具体的にほしいと求めました。かつてはなかったのだけれども最近は非常に課題となっている、お話にあったような複雑な課題、もし具体的に何かありましたらお伺いします。","respondent":"久保田地域活動課長","answer":"地域活動課に来たりということで、どこの部署にもいろいろ行くのですが、そうするとなかなか横断的な連携がとれないというところもございました。各課で連携、力を合わせまして、課題解決に向けて全庁的な体制で当たっていきたいと考えています。","id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"ひいては地域の力、いわゆる住民自治が確立していくバックアップを、よろしくお願いしたいと思います。次に１４９ページ、いわゆる番号法で個人番号カードのいわゆる余力というのでしょうか、それについてお伺いします。","respondent":"秋山情報システム課長","answer":"今般、番号制度の法が成立しまして、平成２８年１月より区民の皆様に個人番号カードというものをお配りする予定になってあります。区としましては、周辺の状況と準備の状況等を見据えて、対応を検討していきたいと考えております。","id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"国は今あいている部分についてはいろいろなメリットがあるというお話があって、今ご説明いただいたこともあるのですが、一般の区民の方々にとってどのようなメリット、それがその独自利用のところでどういった具体的なメリットがあるのか、お伺いします。","respondent":"秋山情報システム課長","answer":"所帯情報というのが連携できるようになるということでして、課税証明書の添付の省略というのが、まず法に定められたもののメリットと考えております。その次に、余力部分の、例えばコンビニ交付であるとか、特定個人認証の部分とかというのは、その次に来るのかなと考えています。","id":"exchange-094"},{"speaker":"高橋委員","kind":"質問・要望","question":"条例で定める事務に利用することができるとありますので、ぜひそこの部分について活用する場合は、考慮して進めていってほしいと求めました。平成２５年度の予算特別委員会のときにもちょっとお話しさせていただいたのですが、よその行政の経験、少し具体的にお話しほしいと求めました。","respondent":"堀越人事課長","answer":"技術系事務系とおりまして、新しいプロジェクトをリードしたり、そういった面で現在の職員に対しては非常に刺激になっているというところがあります。","id":"exchange-095"},{"speaker":"若林委員","kind":"質問・要望","question":"１６５ページの固定資産台帳導入検討経費について、まず伺います。平成２６年度以降またゴールがあると思いますが、こういうことをひとつお伺いしたいのと、お聞かせほしいと求めました。","respondent":"平澤経理課長","answer":"こういったところを調査研究いたしまして、平成２６年度につきましては、基本的には策定方法の方針を策定する、そういったところから始めていく。そういった違いから、それに基づいて平成２６年度中にきちんとした形で、つまびらかにさせていただきたいと考えているところです。","id":"exchange-096"},{"speaker":"若林委員","kind":"質問","question":"台帳整備とはちょっとタイムラグがあるかもしれませんけれども、ここの対応についても、あわせてお聞きしておきたいと思います。この関連性とか、また国から言われているこの計画についての対応、この２点をお伺いしておきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"現在持っている中長期改修計画であるとか、そういったところを整理しながら、整合性をあわせていきたいと思います。具体的にそれに添うような、東京都がつくるのもどういうような形か、どういうものができるのかというのは、今後の研究だと思ってあります。","id":"exchange-097"},{"speaker":"若林委員","kind":"質問・要望","question":"国から正式な案として示されている段階で、３月中か新年度早々に正式に来るということで、今後しっかり対応してほしいと求めました。公会計の新しい段階に入ってきていると思いますけれども、ここについての今後の考え方、スケジュール等わかれば説明を求めました。","respondent":"本城企画財政課長","answer":"今ご指摘がありましたフルコストとしてのフロー、ストック含めたもの、全体の評価の把握が不可欠であると考えているところです。効率的な法律のあり方とか示されるような方針にありますので、それをしっかり見据えて、進めてまいりたいと考えているところです。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１８１ページの防災体制整備費ということで、小規模災害時の緊急避難、具体的にはソレイユ戸越についてお伺いしたいと思います。雨露はしのげるという感じではあるのですけれど、私は人間らしく過ごせる施設への改善が必要だと思いますが、その点についても説明を求めました。","respondent":"鈴木防災課長","answer":"そちらのほうにということで、それもできない場合に一時的な緊急避難ということで、お部屋を用意しているというのが現在の体制です。あくまで２、３日から１週間程度の一時的避難ですので、なかなか快適な住環境というところまでは整備ができないです。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的にはぜひカーテンは窓に合ったサイズにしていただきたい、湯沸かし器、洗濯機を配備していただきたい。寒さ、暑さをしのげる冷暖房の設備をしていただきたい、また風呂が入れるようにしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"更新のときにはしっかりと、機能を果たせるものに一応したいと、対応はしていくです。繰り返しになりますが、あくまでお住まいを探したり、対応する間の一時的避難ということで、ご理解いただければと考えております。","id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうことを考えると、２日間というのは現実問題とても無理なので、一定期間そこの中で生活せざるを得ないわけです。こんな劣悪な中で生活をせざるを得ないというのは、ぜひとも改善が必要だと思いますけれども、最後にもう一回お願いいたしますとの意見を述べました。","respondent":"鈴木防災課長","answer":"ご利用いただける期間が２日間ですが、これは原則２日間です。ただ、実際にはなかなか２日でお住まいが見つからない場合がありますので、１週間とか２週間、こちらのほうでもご相談しながら対応はしています。","id":"exchange-101"},{"speaker":"松澤委員","kind":"質問","question":"１８５ページの防災センター改修実施設計委託２,０００万円と、同じく１８５ページの防災訓練助成金、お聞きしたいと思います。防災センター改修実施設計委託について、体験型の防災教育施設としてリニューアルするということですけれども、この内容について示すよう求めました。","respondent":"鈴木防災課長","answer":"センターの改修で今検討している内容ですが、想定しているものとしては、消火の体験というコーナーをひとつ考えております。これが１号、２号という２種類あります、今検討しています。","id":"exchange-102"},{"speaker":"松澤委員","kind":"質問","question":"次はスタンドパイプ追加配備、１９７セットですけれど。これは予算が、おそらく一般財源だと思いますが、この予算措置はどういうふうな形で予算しているんか尋ねました。","respondent":"鈴木防災課長","answer":"ご質問いただきましたスタンドパイプ増配備の予算ですが、これは一般財源を財源として予定しているものです。","id":"exchange-103"},{"speaker":"松澤委員","kind":"質問","question":"これはどういうことなのでしょうか。詳しく説明を求めました。","respondent":"鈴木防災課長","answer":"区民消火隊のポンプに１組、ミニポンプ隊のポンプに１組という形で配備させていただきました。その活用体制、それぞれの実情に合わせた情報をお聞きした上で、ご希望に合わせて配備したいと考えております。","id":"exchange-104"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、細かいことですけれども、この１９７セットはポンと買うのですか、それとも必要に応じて買うのですか。その辺のところをお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"１９７セット分予算は計上しております。必要な内容を精査した上で、一括発注が一番効率的かつ早く配備できる方法ではないかというところで、今検討している段階です。","id":"exchange-105"},{"speaker":"松澤委員","kind":"質問","question":"実は８日ですか、雪が降って道が通れないときに、消防ポンプが火災現場に行き着けなかった、そのときにスタンドパイプから消火したのです。ですから、ただこれはどうしても温度差があって、中には要らないよという町会もあると聞いています。","respondent":"鈴木防災課長","answer":"ほかの場所もフルセットの台車になりますと、一定程度の倉庫のようなものが必要になりますので、そちらのほうも予算としては考えております。その課題がある場合にはそれを一緒に解決することも考えて、なるべく配備するような方向でご相談したいと考えております。","id":"exchange-106"},{"speaker":"松澤委員","kind":"質問・要望","question":"そういうときに、将来的にこれの半額助成とか、それを考えていただきたいなと思っています。そうすると、一般財源が続かないかなという気もするのですけれど、その辺の考えを説明するよう求めました。","respondent":"鈴木防災課長","answer":"地域での活用の状況、それから訓練も必要になりますので、その辺の状況を見きわめる必要があるというのが一点あります。それから国のほうの補助具としての評価なり、導入というところで検討が進めば、その後はまた活用方法や国の動向等を見きわめたいと考えております。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"続きまして、１８７ページの消防団運営費です。区民も都民もみんな同じ仲間ですから、区長から消防団を出せるようにという話ができないものか、その辺をお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"団員の方については、団長から区長に承認の申請をいただいて、それに区が同意して入団していただくという手続になっているところです。消防団の支援も行っているところですので、区としても何か支援ができないかというところは、検討したいと考えます。","id":"exchange-108"},{"speaker":"原委員","kind":"質問・要望","question":"プラネタリウムの９８万４,０００円、稼働に関しては伺ったので、これについての思いをほしいと求めました。非常勤で職員１２人、武蔵小山が９人ということになっていますけれども、費用想定とできればこの経費についてもご説明をほしいと求めました。","respondent":"工藤総務課長、寺嶋協働・国際担当課長、安藤文化スポーツ振興課長、井浦戸籍住民課長","answer":"東京韓国学校、東京中華学校に通学する児童生徒の授業料を納入した保護者に、１人につきまして７,０００円を補助する程度です。… こちらに記載の親善推進から広報調査までがいわゆる事業費に当たるもので、ご指摘いただきました運営費につきましては、人件費および管理費です。私からはプラネタリム事業についてご説明申し上げます。委託業者を含めて趣向を凝らして事業を企画しています。目黒駅に平成２９年以降の再開発の竣工に伴いまして、サービスコーナーの拠点ということで確保しています。","id":"exchange-109"},{"speaker":"原委員","kind":"質問","question":"ですから人材的には大賛成ですけれども、マネジメント的にはもう少し変えた方がいいのではないかと。ですからちょっとスパンが中長期的になってしまうかもしれませんけれど、その辺の思いをほしいと求めました。","respondent":"工藤総務課長、寺嶋協働・国際担当課長、安藤文化スポーツ振興課長","answer":"数でいいますと、平成２２年度１５名、２３年度２０名、２４年度１５名の実績がございまして、平成２５年度は今の見込みが１９名です。… 協力してやっていくという意味で、区政に非常に詳しい人間が要るということで、そのようなご評価はいただいていると思っています。… 私からはプラネタリウムについてですけれども、ハード面においては大切に使っていきたいと考えています。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問","question":"それについてお伺いしたいと思います。１５５ページの男女共同参画について、１７１ページの区民芸術祭について、防災等についてもお伺いしたいと思います。","respondent":"中山障害者福祉課長、平澤経理課長、久保田会計管理者、提坂人権啓発課長","answer":"この間、品川区障害者福祉課と経理課を中心に、品川区における障害者就労施設等からの物品等の調達方針というものを立てさせていただきました。今回… 私のほうからは、年度途中ではありますが平成２５年度の実施状況ということで、２月２０日現在で調査しました。… それから公共施設整備基金ですけれども、これはやはり日興證券が３０億円、みずほ証券が６０億円と大体そんな感じです。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問・要望","question":"やはり民間以上に厳しいモラルが求められている行政機関としては、質問していますが、この辺について改めて区の見解を伺いたいと思います。ですから、職員研修あるいは区民の方々にも、何か見える形でこの啓発をしていただきたいと、事業所ももちろんやってほしいと求めました。","respondent":"久保田会計管理者、提坂人権啓発課長","answer":"みずほ銀行の対応ですけれども、真摯にお答えしたつもりですけれども、この事件が起きたということでみずほ銀行から謝罪に私たちのほうに来ました。そういうことを通じて、今後必要であれば区としての姿勢をもう一度改めて考えて… 節目の職員研修ですとか、広報の特集号で記事として取り上げて、改善していきたいと考えています。","id":"exchange-112"},{"speaker":"浅野委員","kind":"質問","question":"ビデオオンデマンドの地域加入は昨年１０月末で終わっておりまして、今後このビデオオンデマンドもサービス停止と伺っております。頻繁に夜間工事でしょうか、インターネットが接続されないという時間帯がありますけれども、これは何の工事なのか教えてほしいと求めました。","respondent":"荒井広報広聴課長、秋山情報システム課長","answer":"２日に１件ということで減少しておりましたので、こういう状況に至ったという判断をさせていただいたところです。ビデオオンデマンドにある区がつくりました番組については約５００本… 最近行われている工事ですけれども、ケーブルテレビのほうからは設備の更新と、インターネットの利用等が増えておりますので、データ量が増大しているための帯域の拡大化という工事だと聞いております。","id":"exchange-113"},{"speaker":"浅野委員","kind":"質問","question":"ＷＥＢ映像館、こちらについては今年度スマホに対応していただいたということで、これはお願いしたとおりになってよかったかなと考えています。かなり前年に比べて１.５倍から２倍近くまで費用が増えていますけれども、スマホ対応なども考えられるのか、お伺いします。","respondent":"荒井広報広聴課長","answer":"これはトップページも含めて、中身についても見やすいように整理をしていこうということで、進めているところです。それからもう一つはスマートフォン対応ということで、そちらのほうのページも取りかかっているところです。","id":"exchange-114"},{"speaker":"浅野委員","kind":"質問","question":"これを廃止にするに当たって、区民の方から苦情とは言いませんけれど、何らかの問い合わせが何件かあったのかということ。それと、これが災害情報を流していない場合、どのような文言が流れているのか説明を求めました。","respondent":"荒井広報広聴課長","answer":"知っテル区んにつきましては、昨年９月末をもって終了したところですが、区民の方からのお問い合わせは特にいただいていないところです。平常時につきましては、「ただいま緊急情報についてはございません」といった内容のメッセージを発信しています。","id":"exchange-115"},{"speaker":"浅野委員","kind":"質問","question":"まさしく、「こちらは品川区役所です」ということで、その後に今、答弁いただいた内容が流れていると思います。今までにこちらは何件ぐらい入電があったのかどうかということと、私の記憶ではなかったかと思いますが、その点について説明を求めました。","respondent":"荒井広報広聴課長","answer":"１０月の同じく台風２１号だったと思います、それから１０月２７日の不発弾処理の際にも、情報を発信させていただいたとことです。そして受信の件数ですが、ちょっと古くて恐縮ですが、１２月２７日現在、昨年末までに４５件ございました。","id":"exchange-116"},{"speaker":"浅野委員","kind":"質問・要望","question":"４５件のアクセスということで、まだこの電話番号、至るところでこれは区民の方にも展開していってほしいと求めました。もう既に稼働しているのか、稼働しているのであればテストも行われたかと思いますが、状況について説明を求めました。","respondent":"鈴木防災課長","answer":"いろいろ詳しい説明会等がありまして、区の防災無線や複数の通信手段で区民の方にお伝えするというのが原則的な流れになっております。これも本年度末まで稼働が始まる予定で、今、作業の調整をしています。","id":"exchange-117"},{"speaker":"浅野委員","kind":"提案","question":"最後になりますが、公共情報コモンズ、こちらのほうも提案させていただきました。そしてまた１４社の情報提供会社が今、申し込みと言うのですか、簡単にお願いしますとの意見を述べました。","respondent":"鈴木防災課長","answer":"都のほうで今、接続の準備をしているということで、非常に有効な手段ですので、区としても参画したいと考えております。","id":"exchange-118"},{"speaker":"須藤委員","kind":"質問","question":"質問に入る前に、次が聞こえなくなってしまうのですけれど、そういうのは大変ですかね。ここに新しい事業は丸新と、何か事業名の後ろに印をつけるということは大変か尋ねました。","respondent":"本城企画財政課長","answer":"表記できるかどうかにつきましては、いろいろな形で検討はしてみたいと思います。ただ、もし仮に表記できなかったら、冒頭の私の説明の中でしっかりと説明していくようにしたいと思いますので、そのことを含めて。","id":"exchange-119"},{"speaker":"須藤委員","kind":"質問","question":"イベントホールの空調設備がどういうふうになるのか、教えてください。今回はどうやりますとどういうふうになってきているのか、それこそどういう計画でこれを積み立てていくのか、説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"あわせて、耐震の部分を合わせて改修工事を行う予定です。毎年このような形で再開発組合でもって計画的に修繕を行っているものです。","id":"exchange-120"},{"speaker":"須藤委員","kind":"質問","question":"今までこういうところがこうだったから、今度こういうふうにこうしますというのを教えてもらいたかったので。計画的にある程度貯金をしておいて、毎年補修だ何だというのが出てくるから費用ですよというので、よければそのままで返事いただくよう求めました。","respondent":"小林施設整備課長","answer":"空調の取り替えですが、老朽化のために多少効きが悪かったところがあります。照明の取り替え、並びに天井の張り替え、その三つの工事が今回のものです。","id":"exchange-121"},{"speaker":"須藤委員","kind":"質問","question":"イベントホールは、今度いくらかクーラーが効くよという感じで理解しておいたらいいなと思います。スクエア荏原のところはそういう考えを持ってやらなかったのかどうか、なぜそうなっちゃったのか、説明を求めました。","respondent":"小林施設整備課長","answer":"スクエア荏原の非構造部材の耐震化調査委託につきましては、建物竣工後に備品関係の棚とか、棚に載せる備品関係とか、それが転倒するおそれがあるのか、ないのかというそこについての調査委託です。","id":"exchange-122"},{"speaker":"須藤委員","kind":"質問","question":"備品が倒れるか倒れないかという調査をするということなのですか。非構造部材、材ですよ、だから私は天井とかそういうところを思ったのですけれど、そうでなくて単なる備品の調査をするのに２６４万円という。","respondent":"小林施設整備課長","answer":"ただ建設当時に非構造部材の特定天井と言われているものについては、ある程度情報が流れてきましたので、検討はいたしました。そちらのほうの部屋については、対応しておりますので、今回は非構造部材のものについては調査いたしません。","id":"exchange-123"},{"speaker":"須藤委員","kind":"質問・要望","question":"時間ないので、要望だけ。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"南委員","kind":"質問","question":"それと平成２５年４月１日現在の人数で教えてください。この４月１日の４歳児と５歳児の人口も何人かということを伺いたいと思います。","respondent":"立川保育課長","answer":"それから区立幼稚園ですけれども、こちらは６５７名です。人口ですが、平成２５年１月１日現在ですけれども、４歳につきましては２,７５６名、５歳につきましては２,６７０名です。","id":"exchange-125"},{"speaker":"南委員","kind":"質問・要望","question":"４歳、５歳で伺いたかったんですが、私立幼稚園のほうは３歳も入れてご答弁いただきました。区議会に毎年補助金を増額してほしいという趣旨の要望書をお出しになって、そのあたりの見解を伺いたいと思います。","respondent":"立川保育課長","answer":"都制度において上乗せを実施して、いわゆる典型世帯、区としまして上乗せで補助を実施してまいりました。国の動きというのもまた新たな展開があると思いますので、そちらのほうにつきましても注視していきたいと考えております。","id":"exchange-126"},{"speaker":"南委員","kind":"質問","question":"私立では５３万円かかると、こういう考え方を持つべきだと考えていますので、その点について後で回答してください。どういうふうな見解を持っておられるか、どういうところに置いていらっしゃるのか、そこを伺いたいと思います。","respondent":"立川保育課長、工藤総務課長","answer":"先ほど申し上げました繰り返しになりますが、今度とも幼児教育の無償化につきましては国の動向等を注視してまいります。１点目の国の動きをというご質問ですけれど、まさに国のほうでも、いろいろと教育委員会制度改革ということで、いろいろと議論されているです。","id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"住民、残念ながら形骸化されてきているところが、一般論ですけれども少なからずあるということでそういう声が出てきていると思います。そういう状況に対して、ここについては品川区の教育委員会としてはどのような努力をされているのか、ちょっとその辺の見解を伺いたいと思います。","respondent":"齋藤庶務課長","answer":"この教育目標、基本方針をインターネットで検索しますと、品川区のものは一番トップに出ます。今回教育長がかわりまして、話し合いの場として前校長とヒアリングも行っておりまして、十分取り組んでいるところです。","id":"exchange-128"},{"speaker":"南委員","kind":"質問","question":"先ほど聞けばよかったのですけれど、総務課長が懇談会の目的は何かという質問に、より強化したいとおっしゃったのですが、何を強化したいか、ちょっとここを聞きそびれてしまったので、そこを詳しく説明を求めました。","respondent":"工藤総務課長","answer":"私が先ほど回答しましたのは、相互の連携をより強化したいです。かねてから連携を密にしてやっておりましたけれど、緊密な連携を強化しまして、よろしくご理解いただきたいと考えています。","id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"区長に最後に問いたいと思いますけれども、こういう懇談会開催について、改めて区長はこの２回の開催でどんなことをあれしたのでしょうか。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"マグニチュード７.３級の首都直下型の大地震が起きた場合、それともちゃんと耐震補強してあるから、建物は全く問題なく残るのでしょうか。説明を求めました。","respondent":"小林施設整備課長","answer":"平成２７年度を目標に頑張っているところです。地震が来ても大丈夫なような構造計算をして、補強をしております。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"もう一度聞きます。入らない、傾くということも全くないというふうに、要はその後も建物が現存として残ると考えてよろしいか尋ねました。","respondent":"小林施設整備課長","answer":"私も、どの程度の地震が来るかわかりませんけれども、クラック、今言ったひび割れとか、そういうのはあるとは想像がつきます。ただ建物がクシャッと倒れて人が死亡する、そういうような建物の崩壊はないです。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"品川区は区有施設等に対して、早期に復旧できるように、自助としての減災対策はしているのでしょうか。説明を求めました。","respondent":"平澤経理課長","answer":"地震には対応してございませんが、これは９００施設ほどあるのですけれど、その中で１年間で２４０万円ほどの分担金で賄っているところです。現在の保険で、地震保険には加入していないという状況になっていると考えています。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"こういうことを考えると、やはり何かきちんとした、やはり何か対策として持っているべきではないですか。こういうふうにやれば相当負担が減るよということを、やはりきちんと名目化しておかないとまずいのではないかと思いますが、どうなのか尋ねました。","respondent":"平澤経理課長","answer":"先ほど申し上げましたとおり、この庁舎だけに限って言いましても、年間で１,７００万円という非常に大きな投資になると。そういった中で、平成２７年度までに耐震補強をきちんと確実に進めていく、そういったことがまず初めに大変大切なことであると考えているところです。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問・要望","question":"だめになりましたよ、後はわかりません、じゃあそのお金はどこから出るのですか。大都市災害に対して品川区は復興対策に対して、私はやはり自助ということを品川区としても考えていただきたいということで、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"いながわ委員","kind":"確認","question":"藤原委員がしましたので、藤原委員が質問したときのご答弁の中で、設置も含めて進めていくというお考えでよろしいかどうかの確認が一つ。カードが役所に関して多い人は３枚持つことになると思いますので、これは統合することが可能なのかどうか、いかがか尋ねました。","respondent":"井浦戸籍住民課長","answer":"その中の検討課題の一つとして印鑑登録も、委員ご指摘のとおり検討していく必要があるかなと考えています。それからコンビニ交付ということも視野に入れまして、今後番号法の施行というものに伴いまして検討していく必要があるなと考えています。","id":"exchange-136"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１９７ページ、この表記の仕方というのは正しいのかどうか、こういう表記をしなければいけないのかという。まとめなければいけないのか、バラしてやったら都合が悪いのか、何かあったら短めにお願いします。","respondent":"諸岡選挙管理委員会事務局長","answer":"ただわかりやすくということで、区長と区議会議員の選挙、合わせて執行と。区長選挙が行われますと、あわせて区議会議員の補欠選挙を付随して行われますので、それを表記したものです。","id":"exchange-137"},{"speaker":"いながわ委員","kind":"質問・要望","question":"消火栓は以前ちらっとお伺いしたら、品川区内に１,０００カ所以上あるというお話でありましたが、枠で囲ってあるのですね。２月の大雪が降ったとき消防団はみんな動員がかかって、消火栓の位置の確認も含めて雪を払う際にも、そこの工夫。","respondent":"加藤防災安全担当課長","answer":"なので、区内の消防署に確認すると２,８００カ所あります。消火栓の管理、表示をしていますので、今のところ品川区のほうで工夫していくというふうには考えてございません。","id":"exchange-138"},{"speaker":"いながわ委員","kind":"確認","question":"考えていないはいないと思うんですけれど、地域住民とか、誰でも消火栓の位置を確認できるように、工夫されたほうがいいのではないですかと私は質問しているので、そこは考えがないというか、むしろそういう研究をしていくとかいうご答弁をいただけたらありがたかったかなと思っていますので。","respondent":"鈴木防災課長","answer":"消火栓の位置等の消防水利のわかりやすい表示ですが、まちのサインにこだわらず、さまざまな方法がありますので、これから研究させていただければと思います。","id":"exchange-139"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は１５３ページの国際交流推進事業の国際友好都市交流事業と、１８１ページの防災対策費について伺いたいと思います。廃止になる中で、今後はこれはどのようになっていくのか、これを区の認識としてはどう考えているかということを説明するよう求めました。","respondent":"寺嶋協働・国際担当課長、鈴木防災課長","answer":"子どもの人生におきましていろいろな新しい方向性が見つかったとか、すばらしい体験をしたということで、好評を得ている事業だと認識しています。交流に参加していただけるかといったあたりのご指摘は… 東京都のほうにもＪＲのほうで今後そういう検討が始まっているというのはお伝えしておりますので、東京都、品川区。","id":"exchange-140"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いろいろな面で災害においても非常に力になるなということを感じたわけですけれど、その辺の認識を教えてほしいと求めました。例えばこちらの耐震性はどうなのか、それともここがだめならどこかほかに見つけるのかとか、その辺のところを説明するよう求めました。","respondent":"寺嶋協働・国際担当課長、溝口都市開発課長","answer":"東日本大震災の災害時におきまして、毎年友好都市のほうからさまざまな形でご支援いただいたという情報はこちらのほうにも入っております。何かの形で一緒にやれるようなことがあるかどうかということで… 一定の空地、広場等が確保されておりますので、そういった中で広域避難場所としての機能というのは確保されていると考えているものです。","id":"exchange-141"},{"speaker":"たけうち委員","kind":"質問・要望","question":"韓国とは１４９ということで、アメリカに次いでそれぞれ２位、３位と各自治体間で友好都市等を結んでいるです。城北区は２４.５７平方キロ、人口は約４５万人ということで、ご答弁をほしいと求めました。","respondent":"寺嶋協働・国際担当課長","answer":"アジア諸国との交流につきましても、数年前に調査等を行った経緯もあります。そういった災害等も含めまして、近隣諸国と交流できるかという点につきましては、引き続き研究してまいりたいと思います。","id":"exchange-142"},{"speaker":"たけうち委員","kind":"意見","question":"日本のかなり多くの自治体とオークランド市がいろいろな姉妹都市、友好都市を結んで、交流しているということが実はあるみたいなのですね。いろいろな面での、災害も含めた交流を深めていくということもまた大事かなと思うので、一応感想だけ説明を求めました。","respondent":"寺嶋協働・国際担当課長","answer":"今いただいたご意見を踏まえまして、オークランドとの交流をきっかけとしまして、国内のそういった都市との交流につきましては引き続き検討していきたいと思います。","id":"exchange-143"},{"speaker":"本多委員","kind":"質問","question":"それと、９００万円の計上について、先ほどのやりとりでは３００万円掛ける３件の予算計上というふうに説明がありました。現時点での具体的な件名とか、その辺さらにわかれば、説明を求めました。","respondent":"柏原行財政改革担当課長、久保田地域活動課長","answer":"それから、区有施設の跡地活用検討です。大体１件ほどを一から検討する場合には、そういったところで３件程度、検討ができるようにということで計上させていただいたものです。 支援担当組織を設置してはというご質問がございましたので、私からお答えいたします。先ほどもご説明したところがありますが、町会の運営の支援とか、個別の支援を積極的に行っていきたいと考えています。","id":"exchange-144"},{"speaker":"本多委員","kind":"質問・要望","question":"町会は戦後ＧＨＱに禁止されまして、講和条約発効後に復活をしました。そういったことをもっと全面的に出して、町会はもう本当に日本人の心というものを打ち出してほしいと求めましたが、その辺はいかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"こういった防災であるとか、地域の見守りであるとか、こういった事業が進められてこられたところです。果たしてこのあり方がいいのかどうかというところもありますので、その辺も含めて、区のほうと町会の方々含めて、検討していきたいです。","id":"exchange-145"},{"speaker":"本多委員","kind":"質問","question":"加入率が６割というふうにプレス発表でも書かれていまして、もう一度お話を伺えればと思います。町会・自治会は大体２０７ぐらいあるのでしょうか、この全部の町会に対して、協働ということをさらに踏み込んでみてはいかがか尋ねました。","respondent":"久保田地域活動課長","answer":"加入率等の抜本的な改善ですけれども、私どもこの間、やはり個別の対応が必要だということをこの間の事業の取り組みで考えてあります。会計の運営とか、いろいろな行事の相談とかに乗ってまいりましたので、個別の町会の支援をより一層充実していきたいと考えています。","id":"exchange-146"},{"speaker":"本多委員","kind":"質問・要望","question":"予算書のどこに入っているのか教えていただきたいのと、３万９,０００円を超える場合は町会負担になるのか、その辺を説明するよう求めました。","respondent":"久保田地域活動課長","answer":"予算書ですけれども、１６７ページの上から３行目、地域振興事業の１番、町会ホームページ運営支援等の中に含まれているものです。いろいろありますけれども、補正対応とか流用とかもありますが、町会に負担させるということは今のところ考えてございません。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663229?Template=document&Id=1004#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":117945,"voices":363}},{"id":"h26-20140307-3","meetingId":"h26-c-budget","date":"2014年3月7日","dateIso":"2014-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後５時４３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"２４７ページ、プレママ・プチママタウン、父親のための親育ちワークショップと２４３ページのオアシスルーム運営費をお伺いします。私、そういった認識をぜひ入れていただきたかったなと思うんですけれども、そのあたりのお考えを説明するよう求めました。","respondent":"伊崎子育て支援課長","answer":"今ご指摘いただきました事業目的に書かれております背景ですが、委員おっしゃるとおり、子育てを巡る状況はかなり変わってきております。それを踏まえた上でもこういった課題があるというところでこういった表現にしています。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"児童センターで２カ所ということですけれども、どこで何名ぐらいを予定されているのかなということをお伺いさせてほしいと求めました。それ以外で広報はどうされるのかなということ、１クール５回ということで、またこれについての広報もどうなっているのか説明を求めました。","respondent":"伊崎子育て支援課長","answer":"まだどなたかということはこれから検討ですが、前に出て行きたくなる、外へ出て行きたくなるような講座をやろうと考えております。実施する児童センターですけれども、今のところ予定は、水神児童センターと旗の台児童センターを予定しております。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほど、やはり区内産婦人科の病院にもそういった広報を置いていただくということもぜひ考えていただきたいなと思います。今回は乳幼児を持つ父親ということでしたけれども、そういったところもぜひとも考えてほしいと求めましたが、これだけ説明を求めました。","respondent":"伊崎子育て支援課長","answer":"出産前からのプレ父親に対する事業につきましては、現在のところは児童センターではやっておりません。ただ、プレママということで妊婦向けは始めますので、その状況を見まして検討していきたいと考えています。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、オアシスルームの運営費のことでお伺いさせてほしいと求めました。当然、品川区内では７施設を運用されていますけれども、そういった認識というか利用数も大変増えてきているという認識について尋ねました。","respondent":"立川保育課長","answer":"それで、１カ月前から予約ができるです。やはり時期等によっては予約がなかなかとりづらいということもこちらは認識していますので、各施設間で連絡をとっていただいて。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"臨時的に使う施設ですから、いざ本当に必要とされている人が使えないということがないようにぜひしていただきたいなと思っています。やっぱりこういった施設の意味がなくなってしまうと思いますので、工夫していくことが必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは、２１３ページの下から３行目の高齢者相談等事業とそれからその下の仮称ふれあいステーション事業についてお伺いしたいと思います。この２,４９０万円の内訳を教えていただきたいとともに、改めてこの高齢者相談等事業の役割について、これも教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"それから、また高齢者のみの世帯の方でちょっと気になる方に対して、民生委員が月１回の訪問や電話等を行いながら見守りをしているという内容です。その結果については、毎月区のほうに報告をいただいているところです。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"その辺の数というんでしょうか、教えていただきたいと同時に、こちらのほうも教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"それと、あと平均年齢ですけれども、全体の平均年齢は６４.５３歳です。年齢の基準ですけれども、新任の方は原則６７歳未満で、定年につきまして１２月１日が改選になりますので、７３歳未満というふうになっております。","id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"何か３年に１回実態調査をなさるということでありますが、これは現場の民生委員が何かアンケートをお持ちなさって実態調査をとっていくのか。民生委員の負担というのはどうなのかなという、ちょっと心配なんですが、その辺のちょっと実態も教えていただけますか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"民生委員が該当の方に対して１軒１軒回ってアンケートをとっていきながら、非常に参考になるということで、区としても非常に大事にしている事業です。","id":"exchange-008"},{"speaker":"山元委員","kind":"質問・要望","question":"どういうふうになるのかなということを教えていただきたいということと、実際さまざまなことをなさっているかと思います。実際、特にこの代筆・代読を利用なさっている、月何人ぐらいの方がおいでなのか教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"仮称ですけれどもふれあいステーション事業ということで、今回、予算を載せしています。品川第二、荏原第二、それぞれ毎月３０件から４０件程度の相談を受けております。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"私から２２９ページ被災見舞金と、２５１ページの就職力アップ支援、子ども家庭支援を新しく新規で計上されていましたので、これについて伺います。どういったこと、誰が、カウンセラーがやったり講習だったらどういった人が講習に来るのかというところを教えてほしいと求めました。","respondent":"鈴木防災課長、竹田生活福祉課長","answer":"１点目のお見舞金についてのご質問にお答えいたします。区のほうで実施していますこの見舞金ですが、国の災害救助法で災害を受けた方を救援するという趣旨で制度があります。専門支援員とケースワーカーが車の両輪のごとく連携して支援を行い、品川区から貧困の連鎖をなくす意気込みで取り組んでまいりたいと思います。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問・要望","question":"この中だと住宅等に関するものが多いんですが、こうした中で雪に関する明記というのは、雪害に対するお見舞金の考え方というのはないでしょうか。民間の方が警察とか医療とか学校等との連携というのはどういうふうに行えるのかなというのをちょっと疑問に思ったので、そちらを説明するよう求めました。","respondent":"鈴木防災課長、竹田生活福祉課長","answer":"それから大雪ですね、自然による災害の被害というもので考えておりますので、当然大雪の場合にも被害を受けた場合には見舞金の対象となります。それから床上・床下浸水というようなものになりますので、雪の場合には住居… 就労支援のほうですが、受給者の個々の個性に合った支援をしてまいりたいと考えておりますので、長い継続的な就労に結びつけたいと考えております。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"もう一度確認をさせてください。例えば、そういったところをうまく活用してボランティア等でも、そういった取組みというのはできないかどうか教えてほしいと求めました。","respondent":"鈴木防災課長、竹田生活福祉課長","answer":"関連しまして、もし雪による被害でお亡くなりになった場合には弔慰金ということで支給の規定があります。同様の制度で、条例のほうでも弔慰金に関する条例がありますので、そちらの支給も該当するということになります。 その委託先から、生活保護の受給家庭の状況に詳しい者を派遣していただいて、その者と十分に協議しながら支援を進めていきたいと考えております。幅広くいろいろな可能性を探って就労、経済的な自立につなげていきたいと考えております。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"生活困窮者自立支援法の法案が今出されておりまして、２分の１が国庫補助であとはやるかやらないかという話になってきているというお話を伺いました。そうした中で、しっかり品川区としても貧困の連鎖、こうしたものを断ち切るためにもぜひ続けていってほしいと求めましたが、あればお願いします。","respondent":"竹田生活福祉課長","answer":"国庫補助率につきましては、各事業ごとにその割合が示されているところです。残りの部分が東京都と私どもの負担となりますが、東京都と十分協議してまいりたいと思います。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのコンセプトを教えてほしいと求めました。そして保育従事者の条件ですね、それとあと平成２７年４月に制度化されるということをお聞きしましたけれども、何がどう変わるかを説明するよう求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"次に、今後の制度の関係ですけれども、平成２７年４月から子ども・子育て支援新制度のほうに移行してまいりますけれども。これら家庭的保育や小規模保育を含む地域型保育事業につきましては、区の認可によります認可事業という形に移行してまいります。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"補助金に関しては、名前が変わるということで、同じように下りていくということをちょっと認識示されるようです。その背景でどうして給食になっていくのか、それについてのまた問題点がいろいろあると思うんですけれども、その辺はどうなのか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、これも５年間の経過措置がありますので、平成２７年から５年間は経過措置の中で区も対応していこうと考えております。国も検討しておりますけれども、補助制度が必要だと考えておりまして、国もそれを認める方向で今検討を進めております。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"４点足しまして、今現在働いている方を対象とお聞きしましたが、大体何割ぐらい働いている方々いらっしゃるのでしょうか。５万円上限とプレスにありましたけれども、再度受験することができるのか尋ねました。","respondent":"立川保育課長","answer":"実際に不合格になりましたら、また再受験していただいて、合格の折には５万円までは補助を出す予定となっております。いわゆる新しい認定こども園の制度で保育教諭というのを設置するという考え方でございまして、この資格取得試験の制度を利用していただいて。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりすごく保育士の人材不足の問題点、あると思うので、子どもたちに特に影響してくると思いますので、ぜひこの支援で多くのよい先生を送り出していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２１７ページの同行援護と、あと障害者の雇用についてお伺いしますのでよろしくお願いします。視覚障害者の移動支援、ガイドヘルパーから同行援護に変更になりましたけれども、支援内容に変更があるのかどうか教えていただきたいのが１点です。","respondent":"中山障害者福祉課長","answer":"ガイドヘルプから同行援護に変わって内容に変更があったかということですが、基本的なところでは変わっておりません。それに合わせて給付の決定をしておりますので、少ない方ですと５時間、多い方では大体７０時間ということになっているところです。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１時間約２,０００円なんですかね、１日１回は散歩に出たい、こう言っています。ぜひかなえていただきたい、時間を増やしてほしいという、この検討をしていただきたいんですけれども。","respondent":"中山障害者福祉課長","answer":"そういったサービスの対象になる、ならないという仕分けもさせていただきながら、標準的なところで支給検討をさせていただいています。ただ、それによってどうしてもこういった部分の外出が必要なんだということがあれば、そのときにまた個別にご相談いただければと考えています。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前回の予算のところで、私は品川区自らが雇用をつくり出すこと、これを求めました。この品川区役所が全庁的課題として検討してほしいと求めましたがいかがか尋ねました。","respondent":"中山障害者福祉課長、堀越人事課長","answer":"同行援護につきましての予算ですけれども、今年度平成２５年度予算に比較しまして、約２０％のアップとなっております。実績に合わせてこちら増やしていますので、皆さん… 区の職員の採用につきましては、身体障害者を対象とする２３区共通の採用選考を行っています。民間のサービス等々、いろいろと連携しながら、そういった確保にも努めているところです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ社会参加を促すツールを十分使えるように、予算措置のほうも手厚くして、希望がかないますようによろしくお願いいたします。これも以前に求めたんですけれども、目立つところに常設をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"堀越人事課長、中山障害者福祉課長","answer":"私から障害者の雇用に関しまして、全庁的な対応をですが、職員としての対応のそれ以外の全庁的な対応として、さまざま取組みを進めているところです。社会福祉団体の皆さん等ともいろいろお話を進めながら… 物品の販売についてですが、今回ネットのほうにはカタログも載せさせていただきました。実際の現物を見ていただけるような場については確保していきたいと考えているところです。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"雇用についてなんですが、この間、この課題をどこでどのように議論して、どういった問題が出ているのか聞かせていただきたいのと、売店。","respondent":"堀越人事課長","answer":"私ども人事部門はそうですし、障害者福祉部門もそうですし、そういった中でさまざまないろいろな制度を使うということが一つあります。それから、社会福祉団体等ともいろいろお話し合いの中で可能性を探っているということでございまして、そういう中で対応しているです。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"時間があれば２１５ページ、高齢福祉費、熱中症等予防対策事業について伺います。ならし保育についてご相談を受けておりますので、制度の細かいことですが伺います。","respondent":"立川保育課長","answer":"入所日以降に通常の保育の実施よりも短い時間限定して保育することをいわゆるならし保育というふうに考えております。こういった方につきましては、ご要望によっては入園する保育園の園長と相談していただいて、１週間程度実施をする場合もあります。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"品川区のお考えとしては、ならし保育は行わないと。厚生労働省、どのように考えているのか、何か方向性が出ているのであれば説明を求めました。","respondent":"立川保育課長","answer":"平成１８年なんですけれども、保育に欠ける状態でなくても１週間程度なら弾力的に欠けてないけれどもならし保育を目的として入所日をずらしていいというのは、そういった助言というのを過去に受けています。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"認知症のケアについて大変造詣の深いお話を伺うことができました。これからその構築を国は求めていますけれども、品川区は小規模多機能施設、その中においてどのような位置づけを考えておられるのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"住みなれた地域の中で要介護状態にある高齢者が普通に生活ができるというところで、平成１８年度の介護保険法の改正で設置をされております。ご家族の方も安心だし、高齢者の方も非常に安定した生活ができるということで、これからの中心になるかと考えています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"意見","question":"要介護５で３万９０３円、そして訪問介護、この三つが受けられるということで非常にいいんではないかなと思いました。こういうことで利用をためらうという声が一般的にあると言われていますが、この点、品川区はどのようにお考えになるのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"いろいろなサービス事業者をご利用されてしまうと、継続した支援がなかなか難しいというような欠点があります。同じ人が支援をするということで、その方の毎日の状況がよくわかるということで、区のほうもそれに取り組んでいきたいと考えているところです。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"知っている方、ＮＨＫのその番組では小規模多機能施設が認知症介護の切り札であると、このような言い方をしておりました。選択肢がいろいろある中での紹介というのはなかなか難しいと思うんですが、この辺の課題についてお伺いができたらと思います。","respondent":"永尾高齢者福祉課長","answer":"非常にこういう考え方がまだまだ在宅介護支援センターのほうまで定着されていないということが原因かと考えています。行政側としても、もう少しこの小規模多機能についての特色、連携の仕方等、ケアマネときちんと話をしていきたいと考えています。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"補正でもお伺いしましたけれども、来年度様式をどのように改善をしてどのような効果が期待をされるのか教えてください。来年度１,３６０万円と見込んでおり、これは大分控えめなのかどうか、この辺について伺いたいと思います。","respondent":"間部国保医療年金課長","answer":"はがきサイズですと、来年度につきましてはＡ４判サイズのカラーで、視覚に訴えるような形の様式に変更する予定で今検討しているところです。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのときは日本の普及率２３％、その辺を教えていただきたいのと、またデータヘルスという考え方が国で示されました。やはり、非常にいい事業なんですけれども、施設によっては入り口が全然涼しくないというか、なかなか施設が涼しくないという話も伺います。","respondent":"間部国保医療年金課長、永尾高齢者福祉課長","answer":"これは国保と介護と後期を串刺しにして、その方を経年で見て、こういう疾病の方がこういう介護になりやすいだとかそういうものを検討するものです。我々もこのシステムについては期待をしています。 熱中症のシェルターについてですけれども、直接区のほうにそういうお話はじかには聞いておりませんけれども、今後その表示につきましては工夫をしていきたいと考えております。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのあとどうなるかというところでこれは間違いなかったかというのをまず教えていただきたいのと、いろいろな活動が報告されたと思います。どのような形でまた増えたところがあったのかどうか教えてほしいのと、救急医療キットがこの６１団体に販売されたという事業概要が出ています。","respondent":"永尾高齢者福祉課長","answer":"こちらの事業、かなり実績が積まれておりまして、団体数ですけれども、平成２５年度に７団体増えて、今合計３８団体になっているところです。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"でも今お伺いしたところ、若干ずつ増えていて、３８団体になられた。何らかの形でこういう町会がこういうことをやっていますというのは、広くほかの町会に活動報告、アナウンスはされているのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"こちらの事業、区としても重視しているものでございまして、講演会や研修会等を開催して、その中でいろいろないい事例の紹介を行っているとともに、そのときに、やはり救急医療キットのご説明についてもあわせてやっているところです。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問・要望","question":"それとあと一つ確認なんですけれども、この質問、最後になります。この補助金といいましょうか助成金はあくまでも町会・自治会なんでしょうかね。","respondent":"永尾高齢者福祉課長","answer":"こちらの助成金につきましては、あくまでも町会・自治会のもので、もし高齢者クラブでやりたいということであれば、やはり町会と自治会、高齢者クラブが力を合わせて共同でやっていただければと考えています。","id":"exchange-032","title":"町会・自治会支援"},{"speaker":"渡部委員","kind":"質問・要望","question":"よその社会福祉法人等でつくられているのも入ってるだろうなというのは確認はしたんですが、これは、実際区内だとどこで買えるのでしょうか。あれって買えるんか尋ねました。","respondent":"中山障害者福祉課長","answer":"売店のところには月１回ということで、第３木曜日に来て、あの場をお借りして売っているような状況です。一応こういうものを作業でつくっておりますということで展示をさせていただいているところです。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"ちょっともったいないじゃないですか。その考え、お聞かせいただきたいのと、やはり販売できるところを区の目立つところにつくってほしいなという思いがあります。","respondent":"中山障害者福祉課長","answer":"できれば購入していただきたい、それは私どもの願いでもありますので、ぜひそういった場については考えていきたいと思っています。その中で１件１件どういったことならできるか、そういうことについても検討してまいりたいと考えています。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問","question":"スクール・ステイ事業をお伺いしたいと思います。小１プロブレムの解消が目的なんでしょうが、そして一緒に行動するわけですから、今後どのような形になっていくのかというのがまず一つ。","respondent":"立川保育課長","answer":"スクール・ステイにつきましては、現在保育園・幼稚園２７園と小学校２０校、平成２６年度は２０校まで拡大して実施する予定になっております。いわゆる保育園の分園化、小学校の利用については、今後については分園化ということは考えておりません。","id":"exchange-035"},{"speaker":"渡部委員","kind":"質問","question":"最後に一点お伺いします。そのようなところとの連携の可能性を最後説明を求めました。","respondent":"伊崎子育て支援課長","answer":"それは、あくまでも個別のつながりで支援していただいているところ、それはそれとして計画をしていっていただければと考えています。ほかにも、こういったつながりを持てる大学がございましたら、検討していきたいと思います。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"外出習慣化事業、この事業スキームというのはやっぱり何とか見直していただきたいなと思っているんですが、いかがでしょうか。先日の井上委員の質問の中では、品川区としてはぜひつくっていっていただきたいということで、もう一回ご答弁をお願いしたいと考えています。","respondent":"永尾高齢者福祉課長、白鳥高齢者いきがい課長、中山障害者福祉課長","answer":"ユマニチュードですけれども、本人の立場に立った支援を続けているところですけれども、より質の高いケアを目指していきたいと考えているところです。決算特別委員会におきましても、そちらのほうの人件費等がかかる関係で、１人当たりの単価の計算というのが高うなってあります。… 確かに今通過型１カ所ということで、病院と医療とのかかわりというところが大変大事になってきます。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"過労死などもありますので、燃え尽き症候群もありますので、ぜひ適正な人員配置ということを区全体で考えていただきたいと私は思っております。それと、高齢者福祉との連携についてご答弁がなかったように思います。","respondent":"永尾高齢者福祉課長","answer":"障害者と高齢者、分けるという意味ではなく、障害の方が高齢化されるし、高齢者も障害になっていくという意味で、やはり一緒に両方の課で連携しながらその人によりよいケアをするべきだというふうに考えているところです。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"すみません、最初の質問、連携のところでは、例えば浴室を使えるようにというようなものは、どこでどのように検討をしていくかということで質問をさせていただいたので、そのことをお願いします。","respondent":"永尾高齢者福祉課長","answer":"実際に障害の方も、特養に入っている方も現在もいらっしゃいます。空きスペース等いろいろ課題はありますので、施設とも相談しながらよりよい方向を考えていきたいと考えています。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問","question":"今のは、高齢者福祉課が中心となって高齢施設と検討していくというふうに理解してよろしいのか尋ねました。","respondent":"中山障害者福祉課長","answer":"障害者のサービスだけでなく、例えば高齢者のほうの社会基盤を使って何かできないかというようなことのお尋ねだと思います。同じ事業部ですので高齢者福祉課と協議しながら社会資源をどういう形で使えるかということは常に検討しています。","id":"exchange-040"},{"speaker":"あべ委員","kind":"質問・要望","question":"０・１・２歳で保育を受けている子どものうち、それから３歳以降の定員に今十分余裕があるかどうかということを教えてほしいと求めました。それから、父親の親育ちワークショップですか、これは内容を簡単に教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長、伊崎子育て支援課長","answer":"現在０・１・２歳の保育ママ、そして認証が０・１・２歳が多いと認識しておりますので、足りなくなってはいないというふうな認識ではおります。工事期間中につきましては、今開設期間前の家賃補助ということを検討しておりますので… こちら、来年度はモデル事業としまして２カ所、児童センターで実施を予定しております。父親としての専門講座を、まだ講師は決めておりませんが、どなたか専門家をお呼びしてやりたいと考えています。","id":"exchange-041"},{"speaker":"あべ委員","kind":"質問・要望","question":"その中で、１歳園というものをもう一度視野に入れてもいいのでないかと考えていますが、お考えを聞かせてほしいと求めました。父親の親としての部分だけではなくて、父親の意向、どう生きるかというところもぜひ加えていただきたいと考えています。","respondent":"今井制度改革・待機児童対策担当課長、伊崎子育て支援課長","answer":"３歳児の受け入れの枠については新規開設の中でどのように見ていくかが今後の検討課題、定員の枠も含めて検討課題ということで十分認識しております。委員ご指摘のところは… 今ご指摘がございました点を含めて、専門家の方と一緒に検討していきたいと考えています。","id":"exchange-042","title":"町会・自治会支援"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は２０５ページの各種援護事業のうちホームレス対策事業と、２４５ページの幼保一体施設運営費について質問します。２０５ページの、各種援護事業のうちホームレス対策事業７９４万１,０００円について質問いたします。","respondent":"竹田生活福祉課長","answer":"ホームレスの件についてお答えします。施設等に入所を承諾した者については、品川寮等の施設に案内し、支援しています。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それともなかなか成果が見えないというように評価したらいいのか、どのように解釈したらいいのか、一言ちょっとご説明をお願いします。","respondent":"竹田生活福祉課長","answer":"平成２５年８月に都の行う路上生活者の概算調査によりますと、前年同期よりもマイナス１５％、１８９人の減となっております。この減少傾向は長期にわたって続いているものです。","id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"品川区における路上生活者の実態はいかがなんでしょうか。品川区の路上生活者においては、大まかな傾向と大まかな概算でよろしいんですが、その数字についてお示しいただきたいです。","respondent":"竹田生活福祉課長","answer":"品川区の路上生活者の数字も、東京都とほぼ同一傾向でございまして、減少傾向です。品川区内は１８人、前年同期の調査時が２５人でございましたので、マイナス７人ということになっております。","id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"質問","question":"幼保一体施設の運営費についても質問したかったんですけれども、時間があまりないんで、ちょっと１点だけお聞きしたいことがあるんです。ほとんどが、これはどのような理由でこのようなばらばらな名前になっているのか、何かつけ方に理由があったのかちょっとご説明をお願いしたいんです。","respondent":"立川保育課長","answer":"近隣の保育園の名前をそのまま持ってきて第二というふうにつけております。","id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"意見","question":"いずれにしろ、利用する保護者の方に親しみやすく愛着が湧くような名称の検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"あわせてうれしいご報告もお聞きできて、個人的にも楽しみにしたいと思います。これに関連してもう一回教えていただきたいのと、それで情報取得をしたり、いろいろな友人とかと連絡を取り合ったりというケースが割と多いんですね。","respondent":"伊崎子育て支援課長","answer":"それがこの２月から携帯版を作成いたしまして、スマホに登録していただければ、そこからキッズルームを見られるようになっております。そういったところでも、周知をしていこうと考えております。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"それを品川区としても全力で支援するさまざまな取組みを平成２６年度も行ってほしいと求めました。今現在のこの事業展開の方向性と、配置されているコーディネーターの資格または役割などについて改めてお伺いします。","respondent":"永尾高齢者福祉課長","answer":"これまでやっていたふれあいサポート活動と連携しながらうまく整理してできるだけ拡大したいというふうには考えているところです。それで、コーディネーターの資格ですけれども、社会福祉士を取っている方にお願いしています。","id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"これについては改めて提案もさせてほしいと求めましたが、ぜひ研究をお願いしたいなと要望として述べさせていただいています。そうした中で、生活保護利用家庭の声だとか、ご認識はありますか尋ねました。","respondent":"竹田生活福祉課長","answer":"例えばホームレスだった方が講演会を各地でして回ったりとか、受給者の方がお顔を出してお話をされたりというのは聞いてあります。『はるまち』という雑誌もあるのは承知しています。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"５３５ページ、在宅介護者研修・支援事業であります。こんの議員からは家族介護者支援について質問もさせていただきましたが、こうしたものの調査、把握等というのはされているのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"人数的なことは把握はしてございません。ただ、世代といたしましては、やはり老老介護がだんだん進んできているところかなと考えているところです。","id":"exchange-051"},{"speaker":"つる委員","kind":"意見","question":"介護者が気軽に、このケアラーズカフェですね、こうしたものの展開をしていったらどうかと考えています。例えば子ども１１０番の家のようにステッカーを張らせていただいているおうちがあると思うんですが、ご認識を説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"やはり同じ仲間同士で相談し合いながら、またいいアイデアを出しながらというのは非常に大事だと認識しております。区といたしましても、具体化できるようにできるだけ相談に乗ったり支援をしていったりしていきたいと考えています。","id":"exchange-052"},{"speaker":"つる委員","kind":"提案","question":"ぜひ区としても積極的にかかわってそうしたケアを進めてほしいと求めました。あくまで確認なんですが、提案させていただきましたが、その後何か工賃向上という観点で進展があれば何か教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"それから障害者福祉課、あと区内の就労各施設、みんなで行ってまいりました。そことの関係もありますけれども、何かしら方向が見出だせないかということは清掃事務所とともに探っていきたいと考えているところです。","id":"exchange-053"},{"speaker":"つる委員","kind":"提案","question":"私もまた、さらにいろいろと研究も深めていきたいと思いますし、また時を見て改めてまた提案等もしていきたいと思います。そういった工賃向上についての取組みをしっかりと進めていただくということも大切な要因だと思いますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問・要望","question":"特に重度の方というところと、５３３ページにまいりますが、ただいま質問にありました地域包括支援から伺っていきたいと思います。何というんですかね、乖離というんですか、近隣区と極端に違うケースというのを聞き及んだものですから。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"近隣においては、実際上２４時間１人のケースの方にずっと支援者が寄り添っているということは、事実上は少ないんではないかと思っているところです。それと同時に、個別の支援におきましては… 介護福祉専門学校も見学をしていただいて、１階にあるサポしながわ、高齢者の就職のあっ旋の部分についても見ていただきました。","id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問・要望","question":"言葉の定義と、あとはケース・バイ・ケースで伝え方でどう工夫していくべきかというところのお考えを伺いたいのが一つです。仕事上に活かせる、職員研修等に活かせる資格、どのようなものがあって現在やっていたりとかも含めてどんなことが想定されるのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それに対していろいろな講座も現在やさしいまちづくり推進費の中で実施しているところですけれども、今のところは資格取得という形ではなくて。その中では、実際に車椅子に乗ったり、白杖で歩いたりとかそういう実体的なものも体験していただいているところです。","id":"exchange-056"},{"speaker":"渡辺委員","kind":"質問","question":"ここへの力の入れ方を一つ伺いたいのと、あと、どんなことが品川区として把握をされているのか伺いたいと思います。５年の実施計画ですか、類似あるいは同趣旨の取組みがあるかと思いますが、この点の展望を伺えればと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、シルバー交番設置事業の件です。こちらにつきましては、今２カ所やっているところの成果を踏まえまして、今後の展開を検討していきたいと考えているところです。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ところどころの点字ブロック、私たちも喜んでいるところなんですが、ここ２年ぐらいでどこがどう進んでいるのかをちょっと伺いたいと思います。駅のホームドアについても、この２年間ぐらいで新たについたところを伺いたいと思います。","respondent":"中山障害者福祉課長、稲田道路課長、藤田都市計画課長","answer":"あの後、切り込みを入れたときにどれぐらいの費用が掛かるのかというようなことを考えてまいりましたが。障害者福祉課では… 大井町のペデストリアンデッキですか、都市計画道路の歩道設置とかというところにおきましても、点字ブロックの設置等順次行っております。エスコートゾーンにつきましては、この暮れに３カ所新たに追加をいたしまして、区内には全部で５カ所設置をされているところです。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"整備は鉄道会社が進めるものということを以前にも伺っているんですけれども、やはり要望の強い旗の台駅、障害者の施設があります。そういったところには、強く鉄道会社に求めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"中山障害者福祉課長、藤田都市計画課長","answer":"例えば、１枚の封筒に切り込みを入れるのに１円かかるとして、区役所から区民の方に差し上げる封筒というのは、年間で１億通以上になります。こちらのほうにつきましては、障害者福祉の立場から… 先ほど委員からもお話がありましたとおり、乗降客の多い駅、これを中心に優先的に今整備を進めていくというふうにしているものです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、その一つとして、この封筒のところをぜひ、費用対効果ではなくて、権利として進めていっていただきたいなと私は思います。それとあと、ホームドアのところですけれども、旗の台駅はそうなると乗り入れが結構多いので難しい駅というふうになっているんか尋ねました。","respondent":"中山障害者福祉課長、藤田都市計画課長","answer":"日ごろのそういった社会的な障壁というのは物だけではなく、先ほども人の心の障壁みたいなものもありました。地域のパワーとしてあらわれるものと考えておりますので… そのようなことがあるために、なかなか難しいというようなお話を聞いてあります。反対にそれが危ないということでもあるので、その辺については簡単には解決しませんけれども、これからもお話をしていきたいと考えています。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"２３５ページの次世代育成支援対策費となっていますが、これは新制度になっていく上で、この次世代育成という名前での予算書はどうなんでしょうか。いろいろな保育園・幼稚園の体制が確立している中で、品川区はどういう支援を今後は持っていこうとしているのでしょうか、について、答えるよう求めました。","respondent":"永尾高齢者福祉課長、立川保育課長、福島青少年育成課長、今井制度改革・待機児童対策担当課長","answer":"活動の報告会等も実施していますけれども、地域に対しては、高齢者等見守り活動報告書というのを毎年つくってあります。… ならし保育についてのご質問です。実施しないということは通知していますけれども、育児休業明けの方等については今後… 次世代育成のことですけれども、こちらにつきましては次世代育成支援対策推進法に基づいて事業を行ってまいりました。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"何が差なんですか。品川区で公立保育園とか持っているというところの意味合いというのは何か尋ねました。","respondent":"永尾高齢者福祉課長","answer":"救急キットの件ですけれども、まず、基本的にはご家族だけでなくて町会が配布のときにお手伝いをしてあげながら記入するです。グッズの配布については花の小鉢をプレゼントしていたりするところもありますので、町会と協力していきたいと思います。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問・要望","question":"三年の０歳、１歳、２歳の入園定員数に対する入園数の推移をまず教えてほしいと求めました。先ほどもほかの委員より質問もありましたけれども、なぜここの場所を選んだのか、その理由を説明するよう求めました。","respondent":"立川保育課長、伊崎子育て支援課長","answer":"１歳が２３０に対して２０４。２歳が２００に対して在籍が１７２です。 大学と連携をした中高生支援事業ですが、こちらは八潮児童センターで行う予定になっております。八潮児童センターは以前から杉野服飾短期大学と交流がありますので、ここで実施をする予定です。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問","question":"そうなると、どうなんでしょうか、認証保育所もこうしたものをシステム化して公開されるという。いわゆるモデル事業ですのでこれはよしとなったら展開をしていくんでしょうから、そこら辺のところ、その点を説明するよう求めました。","respondent":"立川保育課長、伊崎子育て支援課長","answer":"先ほど過去３年間の４月１日時点の空き状況についてお話ししたところですけれども、実はこの数字が固まるのは４月の中旬ぐらいなんです。入ってこないのかはっきりわからない状況がありまして… 親育ち支援事業は平成２０年度からやってきておりますが、この中の現状の事業を検証した結果、新しく二つの事業を今回やろうということになりました。","id":"exchange-064"},{"speaker":"こんの委員","kind":"質問・要望","question":"５月の時点でどこが空いているのか、一次保育、こうしたシステムを構築するというお考えをぜひご検討をいただきたいのですがいかがでしょうか。その点だけ。","respondent":"立川保育課長","answer":"利用者支援の視点から認証保育所含めて情報提供のあり方については、一定研究課題にさせていただきたいと思います。","id":"exchange-065"},{"speaker":"こんの委員","kind":"質問","question":"研究課題ということで、そうですか。そうした方への子育て支援のあり方としても大事な事柄だと思いますので、もう一度ご答弁お願いいたします。","respondent":"立川保育課長","answer":"システム構築は難しいかもしれないですけれども、事業者等の協力を得て積極的な情報提供に努めてまいりたいと考えております。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"２１５ページ、定住外国人福祉給付金、それと２４９ページ、家庭あんしんセンター運営費です。最初にあんしんセンター運営費からお尋ねいたしますけれども、まず、あんしんセンター運営費の中でショートステイの利用要件を説明するよう求めました。","respondent":"伊崎子育て支援課長","answer":"お子さんの年齢は身の回りのことが１人でできるお子さんから１２歳、小学生以下のお子さんを対象としております。利用料金につきましては１泊２日で６,０００円、２泊目以降は３,０００円となっております。","id":"exchange-067"},{"speaker":"大沢委員","kind":"意見","question":"今お母様が入院しているということで利用要件ということでありましたけれども、この中で例えば精神疾患の方、要は症状のぶれに違いのある方に関しては、ここのところはどういうふうに取り扱っていらっしゃいますかとの意見を述べました。","respondent":"伊崎子育て支援課長","answer":"こちらは、症状のぶれがある精神疾患のある方ですけれども、お子さんの養育が困難ということであれば対象となってくると考えております。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"精神疾患ですから調子のいいとき悪いとき、ショートステイ、お母さんと子どもが別々に引き裂かれてしまうような事態も一部想定できるわけであります。子どもというのは常にお母さんの近くにいたいわけでありますから、そこのところはどういうふうにお考えになって整理をつけていきますか尋ねました。","respondent":"伊崎子育て支援課長","answer":"希望者の方が病状からどうしてもお子さんの養育が一時的に困難ということであれば、そこはお預かりいたします。ただ、その際には当然面接等を行わせていただき、お子さんに不安がないように預かるということを心がけております。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問・要望","question":"受け入れる割合が少なかったのか、それとも多く受け入れられることができたのか、結果をお示しほしいと求めました。何割ぐらい。","respondent":"伊崎子育て支援課長","answer":"ショートステイの利用状況ですけれども、昨年度、平成２４年度が全件で８４件でございました。持ち合わせておりませんが、面接等をした者からの聞き取りによりますと、そういった方は数件であったです。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"ショートステイのところ受け入れられるやに聞こえましたけれども、数件という実績を見る限りそれが非常に困難な状況であると受け取られるんですけれども、そこのところはどのようにお考えになっていますか尋ねました。","respondent":"伊崎子育て支援課長","answer":"失礼しました、説明が不足しておりました。ご利用になった方が８４件でございまして、今、お申込みはあった方の中で数件しかお受けできなかったということではございません。","id":"exchange-071"},{"speaker":"大沢委員","kind":"質問","question":"引き裂くという言葉が妥当かどうかわかりませんが、精神疾患があって、そこのところ工夫方お願いしたいと思います。定住外国人を質問しますけれども、ここのところについての説明、どのような事業なのかというのがわからないので説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"そのほか、大正１５年４月以前に生まれた者だとか、障害になったのが昭和５７年以前になった方とか、そういういろいろ細かい条件がたくさんあります。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"それともう一つ、高齢者福祉のほうにも、二つありますけれども、障害者福祉ですか、こちらのほうにも定住外国人福祉給付金ということがありますけれども、これについてもご説明いただきたい。","respondent":"中山障害者福祉課長","answer":"障害者のほうにあります定住外国人等福祉給付金についてご説明いたします。現在、障害者のほうの給付を受けている方はいらっしゃらないということです。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"なぜこういうことを申し上げるかというと、かつて１０年ぐらい前ですか、社会を明るくする運動、これは管轄が障害者福祉でありました。支給金なので最初の社会福祉総務費に入るべきではないのかなと思うんですけれども、そこのところ答弁をお願いします。","respondent":"本城企画財政課長","answer":"今までの経緯もあるかもしれませんが、現在の区分につきましては障害者の方、高齢者の方、それぞれが高齢者、障害者という要件の中なので、それぞれ分かれた形で予算上載っていると考えているものです。","id":"exchange-074"},{"speaker":"大沢委員","kind":"意見","question":"先ほど障害者福祉、先ほど課長から障害者の方はいらっしゃらない。だけれども、この給付金は、中にはいらっしゃらないとおっしゃいましたけれども、そこのところはどういうふうにつじつまを合わせていかれますかとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"予算書になりますので、予算としては１人分の予算を見込んでいるところです。失礼いたしました。","id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"民生費のところだと思うんですが、児童相談所の移管について少しお尋ねしたいと思います。それから教育委員会の教育センター、それらとの連携ですね、一体化した仕組みをどのように構築していくとお考えか尋ねました。","respondent":"伊崎子育て支援課長","answer":"児童相談所の移管に向けましては、２３区それぞれが区の対象の中でどういった方針、あり方を考えていくかということを今検討しています。","id":"exchange-076"},{"speaker":"高橋委員","kind":"質問・要望","question":"東京都、今の課題がそのまま、ぜひ今お話にあったところを考慮しながら有機的に虐待対策が進められるように検討してほしいと求めました。日常業務が多々あって重要なものがたくさんあると思うんですが、幾つか挙げていただければありがたいんですが、。","respondent":"伊崎子育て支援課長","answer":"児童相談所の業務といたしましては、やはり虐待対応が一番知られているところではありますけれども、そのほかにお子さんの障害相談、非行の相談、あとは学校不登校、育児、しつけなどの育成相談などの、多くの相談業務もやっているところです。","id":"exchange-077"},{"speaker":"高橋委員","kind":"質問","question":"並行して虐待に関する対応をされているというような状況があって、大変厳しく重い、忙しい仕事の中でいろいろやられていると。発達の診断等も担当するんですが、そういったことに対する体制の整備、特に人材の確保等についてはどのようにお考えか尋ねました。","respondent":"伊崎子育て支援課長","answer":"こちらの養成につきましては今、そのほかにも今後、児童福祉士の資格取得に向けて区としての取組みを進めていきたいと考えています。そのほかの専門の職員ですが、これは移管が決まりましてから具体的にどういう形で対応するのかは考えていくことだと考えております。","id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"人材の確保については、人材の確保についてはこれから非常に重要なところになってくると思いますので、ぜひ確保をお願いしたいと思います。平成２６年度に予定されている児童学園の改築の検討ですか、そちらとの関係、その点についてはいかがか尋ねました。","respondent":"中山障害者福祉課長","answer":"児童学園の改築につきましては現在、早急に行われなければいけない喫緊の課題がありますので、その喫緊の課題に対応してまいりたいと思っています。それで、児童の入所ということですけれども、児童の入所施設というのはある程度広域的な対応が必要だと考えているところです。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問","question":"広域的な対応ではなく児童相談所とはちょっと切り離して児童学園の改築の検討をされていくと、現時点ではという形のお話ですが、そういった認識でよろしいか尋ねました。","respondent":"中山障害者福祉課長","answer":"それだけではない今後の障害者の高齢化・重度化という課題の解決も考えておりますので、総合的に来年度この計画をつくる中で、必要なサービスは何なのかを見極めながら計画を進めてまいりたいと考えています。","id":"exchange-080"},{"speaker":"高橋委員","kind":"質問・要望","question":"児童学園については児童相談所の移管も考慮してぜひ検討してほしいと求めました。ぜひそういうことも含めて児童相談所の移管については取り組んでいっていただきたい、積極的に取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２０７ページの紙おむつ支給と、それから介護保険についてお伺いさせてほしいと求めました。せめて他区並みにしてほしいという声に応えていただきたいと思うんですが、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"支給につきましては、現在、目的が在宅で苦労している人を支援ということですので、入院者については除いているところです。これについて新たに設置するという考えは今のところございません。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"財政的にということであれば、入院時のおむつ代の現金支給をぜひ実現してほしいということで要望します。これからより、より深刻な状況が品川区であらわれることになりますので、このことについてお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"他区のやり方と品川区のやり方とまたそれぞれ、他区でも、いろいろな区によって認定の方法はさまざまのように聞いております。専門非常勤の人も採用しながら一件一件きちんと訪問やチェックをしながら審査会に臨んでいるところですので、より丁寧にやっていると認識しています。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところを私はマニュアルどおりではなくて実態を見るというところでの認定というのはぜひ丁寧にやっていただきたいということでお願いしたい…総合事業というのは全国で２７自治体、品川区がなぜその事業をやることになったのか、その経緯を説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"現状、入っている方についてはそのまま継続される予定です。日常生活総合支援事業の利用者数ですけれども、平成２５年１２月末現在ですと７７件実施しています。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４４自治体ということでしたので、なぜやることになったのかということもお聞かせほしいと求めました。品川区では要支援１、あとスケジュールとしては今後どういうスケジュールでいくのか、あわせて説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ヘルパー派遣のほうをさらに発展して、現在の生活機能向上支援訪問事業をやっているところです。要支援１、要支援２の方のこれからの事業についてですけれども、国のほうで夏ごろにガイドラインが出る予定になっておりますので。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"利用者の負担１割という、そこのところもまだはっきりしないというところでしょうか。そこのところも教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"負担の１割の話ですけれども、これは国のほうで今検討しておりまして、まだはっきりそこが出てきていないところです。","id":"exchange-086"},{"speaker":"若林委員","kind":"質問","question":"２１０ページの高齢福祉費について伺います。全体として地域包括ケアシステムについてお伺いしたいんですが、そういう意味で一般質問させていただいたんですが、お伺いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"現在も進めているところですけれども、生活の支援、全て一体的に提供されるようなものを考えていくところです。相談を基準として適切な支援、サービスにつなげていきたいと考えております。","id":"exchange-087"},{"speaker":"若林委員","kind":"質問","question":"新しい体制の連携の全体像についてお話を、一つ一つの部会の意味も含めてお話を伺うのが一つ。介護とか、区、これがどのような話し合いをされて今回の構築に至ったのかというのを三つ目にお聞きしておきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"そして、その下に医療連携検討部会と、もう一つ今問題になっている新型インフルエンザ等対策連絡会議という部会を設置しております。医療と福祉の連携のための学習会や意見交換会等も実施しているところで、大分顔の見える関係ができつつあるのではないかなと評価しています。","id":"exchange-088"},{"speaker":"若林委員","kind":"質問・要望","question":"その上に連携をやっていくものだというふうに、これは確認させてほしいと求めました。在宅で生活ができる、こういうサービスを私は利用者は求めているんだと思うし、民生委員と連携する中でどうしても段差を感じる一人なわけです。","respondent":"永尾高齢者福祉課長","answer":"品川区でも利用者の視点というのは大事に考えております。現在では在宅介護支援センターのケアマネジャー、どうやって滑らかにそれがうまくいくかどうか、この部会を通じて検討していきたいと考えております。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問","question":"２１３ページのひとり暮らし高齢者等福祉費に関連して、それから２５０ページ、生活保護に関連して質問いたします。要はいろいろな方々の力を総合していって、この問題に対処していく仕組みを長期的にわたって検討していくべきだと思いますが、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"それで、先日ですけれどもさわやか信用金庫や城南信用金庫とも連携した高齢者の地域見守りネットワーク事業というものも開始しております。これからもいろいろなアイデアを募りながら、高齢者の方の見守りを進めていきたいと考えております。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"確認","question":"新聞配達の方は毎日、新聞配達するわけでありますし、それから電気やガスのメーターを確認する方は毎月訪問している。だけれども高齢者の名簿を持っているのは品川区であるからそこのところの整合性をさらに検討して進めていくべきと思うんですが、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"支え愛・ほっとステーションの中では、これは郵便の配達員に協力していただきまして、そこでの見守り活動等もやっております。配達員だけではなく、いろいろな方が地域の中で回られていますので、そういうところとうまく連携しながら拡大していきたいと考えています。","id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"今言ったことをより具体化していくためには例えば民間の方々の協力を得ていくとか、どういう構想をお持ちなんでしょうか。答弁をお願いします。","respondent":"竹田生活福祉課長","answer":"あるいは地域の方々の企業、あるいはＮＰＯ等の、あるいは民生委員の方たちのお力をお借りしながら支援していきたいと思います。就労をして金銭を得るということもさることながら、外部とのコミュニケーションをとるきっかけとしての就労支援を進めていきたいと考えております。","id":"exchange-092"},{"speaker":"藤原委員","kind":"質問","question":"２１５ページ、住宅あっせん等、実績と今後の課題についてお伺いします。２４９ページ、目的と、内容についてお伺いします。","respondent":"白鳥高齢者いきがい課長、福島臨時給付金担当課長、福島青少年育成課長、伊崎子育て支援課長、竹田生活福祉課長、今井制度改革・待機児童対策担当課長、中山障害者福祉課長","answer":"そのうち２８名の方が契約をされて、入居をしている状況です。これがわかりやすく、今後の高齢者の住宅確保のためにもっとＰＲをしていきたい… しかし、いろいろ区でも検討しましたけれども、私どものほうで臨時給付金担当課ということで進めてまいります。しかし… 平成２４年度が１,８８４人。平成２５年度が１,９６５人という推移です。そのほか、学習支援事業は今年度初めて実施いたしまして、参加数は２３人でいらっしゃいました。","id":"exchange-093"},{"speaker":"藤原委員","kind":"質問","question":"そのときにすごく高齢者いきがい課は丁寧にあっせんしているじゃないですか、一生懸命。その辺の対策はどういうふうにしていくのか説明を求めました。","respondent":"伊崎子育て支援課長、竹田生活福祉課長、品川木密整備担当課長、立川保育課長、今井制度改革・待機児童対策担当課長","answer":"先ほど生活福祉課長から生活保護受給世帯の子ども家庭支援という説明がございました。子育て支援課ではひとり親の方を対象にした学習支援事業を今年… 今現在は低所得者あるいは生活保護受給者に対して塾代の支援等を行っております。今回の貧困の連鎖の支援員を通じて… これから木密事業を進めていくに当たって、高齢者の住宅対策というのは非常に大切な問題であります。","id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"２目の扶助費の法外援護と、２３６ページ、それから２１９ページの日中一時支援事業についてお伺いしたいと思います。この民間事業者というのはどういう選考をして、いつごろ決めるのか、あわせてお伺いしたいと思います。","respondent":"竹田生活福祉課長","answer":"さらなるスキルアップに努めてまいりまして、平成２７年４月には適切な支援ができるように体制づくりに努めていきたいと考えています。","id":"exchange-095"},{"speaker":"井上委員","kind":"質問","question":"相談支援事業では区の中に生活福祉課のほうに窓口を置いて、進めるという解釈でよろしいのかということと、民間の入札というのはいつごろ予定をされているのか尋ねました。","respondent":"竹田生活福祉課長","answer":"そういった関係から、現状の場所を最大限有効活用いたしまして、低所得者対策あるいは生活保護のご相談をしていきたいと思います。４月からの事業ですので早い時期に入札を行いまして、事業者を決定し、詳細を決めてまいりたいと考えております。","id":"exchange-096"},{"speaker":"井上委員","kind":"質問","question":"次は、２５５ページの法外援護についてお伺いいたします。昨年記載されていた法外援護の修学旅行支度金などの５項目が今年度は表記されていませんが、何か意図があるのか説明を求めました。","respondent":"竹田生活福祉課長","answer":"１件、２件等の少ないものと、事業内容そのものの変更はございません。","id":"exchange-097"},{"speaker":"井上委員","kind":"質問","question":"法外援護は３５０万円ほど減額されていて、款をまたぎますけれども教育費の就学援助に当たる扶助費は４００万円ほど減額になっております。子どもの貧困対策法の趣旨を活かしているとは到底思えないという感覚がありますが、生活福祉課と教育委員会の見解を伺いたいと思います。","respondent":"竹田生活福祉課長、和氣学務課長","answer":"基準改定によって、廃止になった方は０人ですので影響はないと考えております。最近お風呂のない施設からお風呂のある施設への転居が今年に限らずここ数年ずっと続いておりまして、そういったことから入浴券の減が主な要因です。 その成果で基本的に平成２５年８月の生活保護改定前の生活保護費によって算定をするということでやったものです。ですから、見ていただくと増えたところ、減ったところがありますけれども、その結果３００万円減ったです。","id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"今後３年間、そのままでぜひ区長の判断をいただいて継続をしてほしいと求めましたが、いかがか尋ねました。","respondent":"和氣学務課長","answer":"これにつきましては消費税分が増加になったりとか、さまざま動きがあります。こういう状況をしっかり見ながら、しっかり検討してまいりたいと思ってあります。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"認可保育園の基準についてお伺いしたいんですけれども、その中で、これの申請がないから３００万円ほど減額しましたよというお話がありました。ちなみに、年齢構成としてはどのような方がこの制度を利用されているか尋ねました。","respondent":"伊崎子育て支援課長","answer":"年齢構成といたしましては３０代から４０代が中心です。","id":"exchange-100"},{"speaker":"井上委員","kind":"質問","question":"そうすると、この方たちは保育の需要があったのかどうかということと、せっかくの助成事業が活きないことになってしまう。保育園事業と関連して思われるんですが、その辺の評価、検証はちゃんとできているのか尋ねました。","respondent":"伊崎子育て支援課長","answer":"保育園に入園を前提としての申込みという方もケースとしてはあり得るとは考えております。ただ、その場合は保育園の入園の基準で特に今のところは、こちらから上乗せをというお話はしてございません。","id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"これは要望ですが。次に、先ほどの５項目の中で、就労を前提にした日本語を習得するという要件は含んでいると考えてよろしいか尋ねました。","respondent":"立川保育課長","answer":"いわゆる技能習得、就学につきましては、保育所入所選考基準においてその他の項目ということで基準を設けております。その中身につきましては、その方の習得のための時間数と日数を勘案しまして、就労と同じような時間数、日数であれば、その指数として配慮しています。","id":"exchange-102"},{"speaker":"井上委員","kind":"提案","question":"３日というのも、そこを通れば要件に入っているということで確認させていただいたんですが、一つ提案させていただきたいんですけれども。保育者募集、そういった方たちとのご協力をいただくなどの対策で国際友好協会にも提案はしていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"私のほうに、委員ご指摘のように隠れたニーズがあるという部分も場合によってはあるかもしれませんので、そういった希望調査も含めて前向きに検討するように申し入れしたいと思います。","id":"exchange-103"},{"speaker":"井上委員","kind":"質問","question":"そういった方たちが語学、言葉でコミュニケーションをとっていただける方にもなっていくと思うので、ぜひよろしくお願いします。昨年より３９０万円のプラスということで、今年と来年は同じような事業運営でできるのか、その辺の説明をお願いしたいと思います。","respondent":"中山障害者福祉課長","answer":"日中一時支援事業ですが、こちらのほう、約４００万円の増ということでつけしています。来年度はいろいろとアセスメントをしたりですとか、個人面談をしたりということで、そういった整理はしていく予定です。","id":"exchange-104","title":"町会・自治会支援"},{"speaker":"井上委員","kind":"提案","question":"今までずっとそういう提案をしてまいりまして、定員数で人件費計算されていましたけれども、リスクがある子どもたちに１対１とか、そういうところではないということを評価していただいたわけですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"浅野委員","kind":"質問","question":"そしてまたその率というのでしょうか、数字があればここ数年でしょうか、そしてまた理由についても教えてほしいと求めました。述べ人数も相当な人数になると伺っております。","respondent":"永尾高齢者福祉課長","answer":"平成２１年度には１５人、平成２２年度には１４人、平成２３年度では１２人というような推移になっております。施設のほうに勤務している方のスキルアップということで移行されておりまして、継続してそのままほとんどの方は勤務されているという状況です。","id":"exchange-106"},{"speaker":"浅野委員","kind":"質問","question":"品川児童学園ということから考えると、先ほどもちょっと質問がありましたけれども、子どもの施設との合築の考え方はあったのか、なかったのか。メリット、そしてまた検討していかなければならない課題、これはどのように考えておられるのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"すみません、述べ人数は今計算中ですので、のちほど答弁いたします。","id":"exchange-107"},{"speaker":"浅野委員","kind":"質問","question":"国内で見る限りだと前例というんでしょうか、必要な施設として考えられたのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"全国を見ましても、障害者サービスと高齢者サービスを両方やっている法人というのは少ないと思います。それがまして児から成人期を経て高齢期へということになると、多分全国発の試みになろうかとは思っているところです。","id":"exchange-108"},{"speaker":"浅野委員","kind":"質問","question":"初の試みということで、また新しい大きな施設を含めて品川区からの発信ができることをぜひとも期待をしていきたいなと思います。時間がなくなってまいりましたが、では、答弁をお願いします。","respondent":"永尾高齢者福祉課長","answer":"平成２４年度につきましては述べで７３２名。平成２５年度につきましては２月４日現在で６９１名ということになってあります。","id":"exchange-109"},{"speaker":"浅野委員","kind":"意見","question":"介護のほうに戻りますけれども、７００名前後が毎年卒業といいましょうか、スキルアップをされているということで、こちらの方々がこれからの品川区で本当に働き続けたいということを考えられるように、またその環境をこれからも継続して取り組んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問・要望","question":"質問の前に、１点、委員長にお願いがあります。私の質問に対して後で施設整備課長のほうで補足説明がございまして、そのことについて、昨日の発言は取り消しをしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"須藤委員","kind":"質問・要望","question":"この件についてはいろいろ毎回質問させていただきまして、トップの方はわかっていただいていると非常に感謝の言葉を家族会の方からもいただきました。どんなところが、項目はまだ相談ということなんだけれども、どのあたりが新しい試みとして出されてくるのか教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"高次脳機能障害者支援の充実ということでは、今、地域医療コーディネーターとして医療デイケアの支援ということで。あるいは居場所支援ということで今、失語症友の会の方の応援ですとか、その辺の数字なのかなと考えています。","id":"exchange-112"},{"speaker":"須藤委員","kind":"質問・要望","question":"近隣の３区で、やはり先ほど来出ている福祉は品川だということで負けないように、いろいろなことでご支援のほどをお願いしたいと思います。そのあたりについて考え方、見通しというのを教えて、前年度よりも繰出金が少なくなっている状況についてご説明ほしいと求めました。","respondent":"間部国保医療年金課長","answer":"今までは一般会計の繰入金で対応してきた高額療養費につきまして、平成２６年度から保険料算定することになったことに伴う減です。ただ、今般、激変があってはいけないということで、国につきましては平成２６年から平成２９年の４年間で段階的に行っていくというものです。","id":"exchange-113"},{"speaker":"須藤委員","kind":"質問","question":"後期高齢者、そして介護保険、国保で、あわせてお尋ねします。後期高齢者の審査手数料というか、レセプト１件について幾らとなっているのか、そのあたりをわかっている範囲で説明を求めました。","respondent":"間部国保医療年金課長","answer":"審査料支払手数料につきましては、レセプト１件当たり幾らということで、国保も、介護も、後期も全て国保連合会に委託をしています。国保連合会のほうで単価のとり方が違うということで、このような反映になっているものです。","id":"exchange-114"},{"speaker":"須藤委員","kind":"質問","question":"全体の予算の７５億２,９００万円ですから、手数料というのは１.１６％、総額予算の中から見るとそういう数字になっているんです。そのあたりを説明するよう求めました。","respondent":"間部国保医療年金課長","answer":"現在も後期高齢者医療保険におきましても４項目の支援ということで、保険料低減策を東京都だけは打っています。ただ、本当にどうしようもない部分を入れていくという考えです。","id":"exchange-115"},{"speaker":"須藤委員","kind":"意見","question":"少子高齢化と言われて高齢者が増えてくるので、いろいろな課題が、国保についても広域連合という形をこれからやらざるを得ないだろう。長期的にいろいろなことを見ながら対応をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"},{"speaker":"南委員","kind":"質問","question":"２３５ページの待機児童解消対策費について伺い、区立認可保育園をつくれ、こういう立場から質問したいと思います。不承諾通知をもらった方の中で自営業の方、転園希望の方、また調整指数が４０点以上だった方は何人かそれぞれ説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"それから、そちらの内訳ですけれども、転園の人数は例年１００人程度です。調整指数のことにつきましても、こちらも確認しておりません。","id":"exchange-117"},{"speaker":"南委員","kind":"質問","question":"異議申立てをした方、とりわけ昨年と例年数人いらっしゃるというお話が前にあったと思うんですけれども、昨年は何人か、今年は何人か、この人数を説明するよう求めました。","respondent":"立川保育課長","answer":"異議申立ての人数ですが、昨年４月入園に限っては０人です。今年度は６名です。","id":"exchange-118"},{"speaker":"南委員","kind":"質問","question":"２月２８日を締め切りとして２次募集しましたけれども、１次募集で不承諾通知をもらった８９４人と、２次募集に新規に応募した方が何人いらっしゃるのか、募集した数と応募した数をそれぞれの年齢ごとに説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現在、２次申込みの締め切りといたしまして、例年より多く１,１００件程度と今把握しておりますが、年齢の数の詳細は持ち合わせておりません。重複についても確認しておりません。","id":"exchange-119"},{"speaker":"南委員","kind":"質問","question":"募集した数というのはわかるのではないんでしょうか。その点、説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"４月の２次の保育園入園可能数という形でホームページに公表させていただいた数は、公私立認可保育園合わせて２７８。そして、保育ママが７３という数になります。","id":"exchange-120"},{"speaker":"南委員","kind":"質問","question":"それぞれありがとうあります。平成２６年度の入所が昨年度、平成２５年度ですね、前年度より厳しい状況になっているというふうにわかったのはいつの時点なんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"平成２４年度より平成２５年度の待機児童数も一定増えておりましたので、平成２５年度途中の補正予算でも保育ママ等の開設をお願いしたところです。私ども待機児童数が増えたということは昨年４月時点で十分認識しておりまして、対策もとってきたところです。","id":"exchange-121"},{"speaker":"南委員","kind":"確認","question":"そうすると、今年の４月１日に入所する方たちがかなり応募が増えると、そういうことだということでいいんですね。その辺、確認をしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１点目に、前年度より今年度の待機児童数が増えたことで、私どもも対策はさらに積極的に進める必要があると考えておりまして、その対策をとりました。","id":"exchange-122"},{"speaker":"南委員","kind":"質問","question":"しかし、現実的に今年４月１日の入所が８９４人、例年になく２６２人でしたかしら、多くなっているという現実があるわけですね。そのあたりのことを伺いたいのと、いつの時点で認識されたのか、それを伺います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"人口の推計をもとにしまして、私ども毎年、入園の申込率というのは０.５％程度ほど高まっているという現状の認識はしておりました。１次での申込み者数は２,５３２人ということで、私たちの考える想定よりも、最終的に締め切ったところで多かったというのが現状です。","id":"exchange-123"},{"speaker":"南委員","kind":"確認","question":"そうすると、その時点で２,３００人程度とふんでいたけれどもそれよりもオーバーをしていたということがわかったわけですね。あるいは今年仕事初めの日、その時期については確認をしたいと、大事なところだと私は思うので確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そういった中では、その分析も含めて実際には入園審査を行う時期まで、ぎりぎりまで見極めていたというのが現状です。単なる件数の多さ、私たちどもはそれを確かに多いということは確認しましたけれども、その内訳についても確認をしていたというのが現状です。","id":"exchange-124"},{"speaker":"南委員","kind":"質問","question":"大体２月１９日が発表ですからそれまでの間、２月に入って審査会をするんでしょうかね、そういう時期のときまでにいろいろ分析もして見極めたと。その点について何か数字を見たときに対策をとる必要があったと感じたのか、あるいは対策をとる必要はなかったと踏んだのか、そこを説明するよう求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私どもは新規開設、特に緊急対策として待機児童対策を平成２２年から取り組んでまいりました。認可外の移行支援という形で２園という形で取り組んで、予算の中で今、積極的な総合対策を進めるということの姿勢はお示ししていると考えております。","id":"exchange-125"},{"speaker":"南委員","kind":"意見","question":"そういう対策で十分だと思ったのかどうか、そこを聞いているんです。そこを答弁してくださいとの意見を述べました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私ども、毎年これは定員枠の拡大を着実に実行しておりますので、その中でこの対策を十分積み重ねてきたと考えております。","id":"exchange-126"},{"speaker":"南委員","kind":"質問","question":"そして、私はなぜそこを繰り返ししつこく聞くかというと、現実的に８９４人が入れていないわけです。したがって、対策が十分だと思ったのかどうかを説明するよう求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今回、８９４名の中からどのように待機児童数という形で、２次も含めてご発表できるか、また、私どものほうで今、第２次審査を行っている段階です。","id":"exchange-127"},{"speaker":"南委員","kind":"質問・要望","question":"昨年６３２人に対して待機児童は６２人だからいいんだというふうには絶対に言えないじゃないですか。８９４人と、２次に新しく応募した方々のその後の状況がどうなっているのか追跡調査をして、その点はどうか尋ねました。","respondent":"金子子ども未来事業部長","answer":"今回かなり申込者が増えたという中で、この出されている中で、私ども、なかなか分析がしきれないなと考えています。というのは、そういう意味では真の、本当のニーズというのはどの辺にあるかというところは非常に難しい把握だと考えております。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"もちろん品川区の社会保障費の膨張は続くわけですが、財源的にこれだけどんどん増えていく状況を見て、品川区として財源的にどうなってしまうのかな。２０２５年、そして将来にわたってどうなのか、まず説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"２０２５年、後期高齢者の方がかなり増えるという見込みの中で、今回、国といたしましても社会保障審議会のほうでずっと検討されております。区といたしましても、国の動き等も踏まえまして対策を整えていきたいと考えているところです。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"ここで、給付の抑制についてどのようにお考えなのかお聞かせ願いたいんですが、特に介護について絞ってお答えほしいと求めました。そして、また今回の介護保険改革について介護サービスは相当減ってしまうのかどうか、その辺について、答えるよう求めました。","respondent":"永尾高齢者福祉課長","answer":"それを見込んでの今回の介護保険法の改正の案が出ているところです。全国では１７％という数字が出ていますけれども、実際に各施設を調べてみますと平均で８から十二、三％というような状況になっているところです。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"アルバイトしても勤めているということなんですから、アルバイトしたら年収というは２００万円、２４０万円に限られてしまいます。認知症はじめ実際に社会保障は絶対に必要な人たちが救われない状況になってしまいますが、その辺についてどのようにお考えなのか、答えるよう求めました。","respondent":"永尾高齢者福祉課長","answer":"この問題については全国レベルで課題になっているところで、国のほうもそれの検討をしているところかと思います。異動は報酬という部分もありますけれども、人間関係というところも要素に入っていますので、単純に数字だけでの判断は難しいかなとは思っております。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問・要望","question":"何で教育を福祉で補わないといけないんですか。それが僕は義務だと思いますが、いかがか尋ねました。","respondent":"竹田生活福祉課長","answer":"貧困の連鎖を防止する子ども家庭支援の事業についてご説明いたします。そういった家庭内の問題を改善すべく私どもが今回の事業を考えましたので、学校の教育とは別の領域だと考えております。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"教育の方がいるんですか、ケースワーカーの中に。全然そんな教育のことを知らなくても指導できるんか尋ねました。","respondent":"竹田生活福祉課長","answer":"子どもの養育に関しては早い時期の対策が必要だと考えています。そういったもの、家庭内でできるものをケースワーカーとともに支援して、貧困の連鎖を防いでいきたいと考えております。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"生活福祉課でやってくれるんなら、生活福祉課が教育委員会の中に一部入ればいいじゃないですか。そこは本当に子どものことを考えたら、そこまで意欲を持ってやるべきだと思いますが、どうか尋ねました。","respondent":"竹田生活福祉課長","answer":"生活保護世帯に実施している事業からご説明しますが、学校の教育は十分足りていても、塾代の補助をしたりもしております。そういった子ども、親御さんの意識啓発、それから生活改善等を通しまして、健全な育成を図っていきたいと考えております。","id":"exchange-134"},{"speaker":"石田（し）委員","kind":"質問","question":"２３９ページ各種児童手当、２２３ページシルバーセンター改修検討経費、２５０ページ生活保護費についてお伺いします。２２３ページ、シルバーセンター改修検討経費３０万円計上されていますが、何をされるのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ひとり暮らしの高齢者の人数ですけれども、平成２３年１１月１日時点での民生委員調査の結果でいきますと、ひとり暮らし高齢者は８,２２１人。高齢者のみの世帯が１万１,９６２人となっております。","id":"exchange-135"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"第３子以降の支援、金額を先ほど教えていただきましたが、区でもぜひ独自に第３子以降の支援の拡充を行ってほしいと求めました。これは今日は要望で終わります。","respondent":"白鳥高齢者いきがい課長","answer":"こちらのほう、改修検討経費につきましては、平塚橋シルバーセンターならびに大崎シルバーセンターの経費につきましては含まれてございません。","id":"exchange-136"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"生活保護費についてお伺いします。この契約、どういった契約を結ばれているのか教えていただきたいのと、金額が増になっているのが消費税分の増であるのか確認したいと求めました。","respondent":"白鳥高齢者いきがい課長、竹田生活福祉課長","answer":"基本設計、実施設計ということで、今年度中に終わらせる予定です。この二つの施設につきましては、その他のシルバーセンターにつきまして改修の検討経費ということで計上させていただいているものです。 ただ、ちなみに実績で申し上げますと平成２４年度の就労支援の述べ人数でいきますと６１７名、就職者数でいうと５１１名。相談員の報酬につきましても消費増税分です。","id":"exchange-137"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"リーマンショック前は働いていたわけですから、そういったことをぜひとも把握をしていただきたいなと思います。１点、今年は２５名となっていますが、この人たちと就職力アップの新しい事業との関連性というのがもしあれば教えてほしいと求めました。","respondent":"竹田生活福祉課長、白鳥高齢者いきがい課長","answer":"生活を建て直していただき、阻害要因がなくなった方から順次、就労に向けて支援をしていくところです。今回の新規事業の就労支援につきましては在宅でいる方を対象にしておりますので、更生施設は更生施設で別のルートで支援しています。 新しいシルバーセンター、今現在進めておりますけれども、こちらのほうを参考にしながらも今後、可能性を含めて検討をしてまいりたいと思っています。","id":"exchange-138"},{"speaker":"たけうち委員","kind":"提案","question":"私も厚生委員会等でも提案させていただきましたので、これは要望ですけれどもぜひお願いしたいと思います。２点目はヘルプカード、その状況と、助けを求めた際に区民の方がそれをしっかり理解していただくような区民への周知についてお伺いしたいと思いますとの意見を述べました。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"１回目のときには移行理由、移行年月日、１月に入りましてからは予定の利用申請書の書式とあわせまして移行される方についての調査をしたところです。３月に撤去と工事の説明を事業者からご連絡させていただきまして… 移行につきましては平成２６年度中に徐々に説明、一軒一軒お訪ねしながら徐々に移行していこうかと考えているところです。","id":"exchange-139"},{"speaker":"たけうち委員","kind":"意見","question":"１点だけ、緊急通報システム、ぜひ、これで切り替えしなかった方が今度見守りが必要になってくるんですよね。障害者も既に６人ぐらい切り替えないということですので、高齢者も含めてお願いしたいと思いますけれども、一言だけお願いしますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"一人ずつお宅にお邪魔しながらご説明しておりますので、個人名もわかっておりますので、もしものことがあれば民生委員等に引き継ぐとか、いろいろな方法を考えていきたいと考えています。","id":"exchange-140"},{"speaker":"本多委員","kind":"質問","question":"２３１ページの大井六丁目グループホームと、同じく東五反田四丁目グループホームについて伺います。規模、設計がこれからですけれども、大前提の概要だけわかる範囲で示すよう求めました。","respondent":"永尾高齢者福祉課長","answer":"区立の施設として整備をする予定で、１ユニット９名で、家庭的な支援ができるような設計になっているところです。平成２６年度は用地取得をして、また区立のグループホームにする予定ですので、事業者を公募して、基本設計というところまで予定しております。","id":"exchange-141"},{"speaker":"本多委員","kind":"確認","question":"開設準備経費が１,０００万円となっていて、入る方が自分の使いなじんだ家具とかそういったものを持ち込めるのかどうか、その確認をさせてください。東五反田四丁目グループホームですが、ざっと坪２００万円ぐらいなのかなと思うんですが、その辺の金額の算定を説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"大井六丁目グループホームにつきましてはグループホームですので、ご自分が使いなじんだ家具の設置は可能となっております。こちらの用地取得はこれからということですので、まだ暫定での予算ということで、まだ決定しているものではございません。","id":"exchange-142"},{"speaker":"本多委員","kind":"質問・要望","question":"認知症のケアで香りのある花ですとか、動物とのふれあいなど、感覚を常に刺激する工夫というか効果が大切だと思います。ライフスタイルに合わせたことをやはり続けていっていただきたいと思うんですが、その点についてはいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"今回、指定管理の候補になっている事業者につきましては、グループホームの経験が非常に豊かなところとなっております。現在、大井六丁目グループホームにつきましても引き続きそういう支援をしていっていただくようにこちらもお話をしておきます。","id":"exchange-143"},{"speaker":"本多委員","kind":"意見","question":"これまで区内に９カ所ありますけれども、１０カ所目、１１カ所目になるわけですけれども、一時自宅に帰宅したいケースとか、そういったケースというのはこれまでの９カ所のケースですとか、あと新しくつくる２カ所についても何か方針等があればお知らせくださいとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"認知症の方の場合、どうしてもそのときの気持ちの中で自宅に戻りたいという方や、また徘徊等の可能性などもあります。そういう場合につきましては支援者がその人のお気持ちになって、再度戻ってきていただいて生活をするという繰り返しをしています。","id":"exchange-144"},{"speaker":"本多委員","kind":"質問","question":"指定管理者のスタッフの方たちが腰痛防止ですとか、研修等をされていると思うんですが、そういうのは区がどこまで把握されているのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ケアの仕方、技術的なことにつきましては福祉カレッジでの講座だとか、ＮＰＯでも研修会を区のほうで委託して行っておりますので、そういうところに参加しながら質の向上を図るようにしています。","id":"exchange-145"},{"speaker":"本多委員","kind":"質問","question":"常に把握をされているというふうに理解していいのでしょうか。超高齢化社会に向けて、その辺、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"薬の開発についてはいろいろな国で今研究しているところで、現在ではまだそこまでの薬は出てはございません。飲むのを忘れてしまったりということがありますけれども、貼るものであれば少しそういう方についての効果はあるのではないかと聞いているところです。","id":"exchange-146"},{"speaker":"本多委員","kind":"質問・要望","question":"そのところの今後の方針、考え方を伺うのと、薬等なるべく情報をキャッチしていってほしいと求めました。最後にそれだけお願いして終わります。","respondent":"永尾高齢者福祉課長","answer":"整備するに当たって、区立でやる場合と、事業者創設型とかいろいろな方法があります。いずれにしても認知症の方が地域の中で安心して暮らせるような体制ということで、グループホームはこれからも進めていきたいと考えております。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663229?Template=document&Id=1006#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":116834,"voices":380}},{"id":"h26-20140310-3","meetingId":"h26-c-budget","date":"2014年3月10日","dateIso":"2014-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後５時３４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を136件整理しています。","topics":[{"id":"topic-01","title":"平成２６年度品川区一般会計予算","agenda":"平成２６年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"２８１ページの清掃費の普及広報費の中に入るのかと思いますけども、リサイクル情報紙『くるくる』についてお伺いさせてほしいと求めました。それから、掲載料をこれは取っていないということなのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"下期も同程度の掲載が継続されております。何か不都合があれば、もちろん清掃事務所のほうにご連絡いただければ、その真偽のことも含めて対応してまいります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"大体何部ぐらい発行されているのかというのをちょっと教えていただきたいのですけども、大分、入っていないことも多いかと思いました。どれだけお考えであるのかということと、なかなか利用者の方が少なくなってきてるのではないかと思うのですが、その辺のお考えを説明するよう求めました。","respondent":"小林品川区清掃事務所長","answer":"内容の精査、それから持ち出していただきます情報についてのＰＲ、入手に努めてまいりたいと思います。その意義という点では、こういった情報提供で需要と供給を結びつけていく努力は引き続き維持してまいりたいと思います。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、大気汚染調査のことでお伺いします。このときの区の観測体制と、それから状況と、あと問い合わせ等あったのかをお聞かせほしいと求めました。","respondent":"野呂瀬環境課長","answer":"状況からご説明しますけれども、東京都のほうで機械を設置しておりまして、区内は４カ所設置されております。こういう考え方でございまして、数日前から区のホームページにも掲載して、そういうお知らせは区民の皆様に周知しています。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"東京都全体で対応していくということだと思いますけども、近隣区との連携等、これからも深めていってほしいと求めました。昨年６月の公開のときに、２,３００もの人々が来てということで、それから今後の小野学園との連携の可能性等をお聞かせほしいと求めました。","respondent":"野呂瀬環境課長","answer":"それで認識はしておる。こういう取り組みは今後も継続していきたいと考えているところです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"すばらしい事業だと思いますので、ぜひともこの大井町から蛍をということで、広めていってほしいと求めました。まあここであるわけですから、ビオトープ構想等、進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"私からは、２６２ページ、保健指導費、それから２７３ページの環境保全事業についてお尋ねしたいと思います。毎週火曜日１０時から１６時まで相談体制を敷いているということでありますけれども、品川区の体制、また不妊症についても説明を求めました。","respondent":"亀井品川保健センター所長","answer":"相談があれば丁寧に対応していくと、体の関連だけではなくて精神的な問題とか、いろいろあると思います。妊娠の大体１０％から２０％に起こると言われてますので、お話を聞いて、少し継続的なサポートをするというようなこともしております。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"ちょっとこれは確認ですが、２４年度が、本文が不妊治療医療費助成。同じく保健指導費の中でお聞きしたいと思いますが、品川区の妊娠・出産・子育てに関するさまざまなサービスの調整はどこが担っているのか尋ねました。","respondent":"亀井品川保健センター所長、江部健康課長","answer":"流産という言葉をそのまま載せるどうか、いろいろなところからそういう相談窓口にリンクできるようなことは検討していきたいと考えています。… 基本的には母子の関係は健康課のほうで、事業連携、相談体制等は保健センター全体と調整しながら進めているものです。すみません。 今、いろいろなことをしていくという形になりますので、個々のケースの全体的な調整といえば保健センターの保健師が担っていると考えていいと思います。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"これまでもさまざまな提案をしていますが、それについては積極的に検討を進めていただきたいし、また改めて提案もさせてほしいと求めました。４０自治体ぐらいでしょうか、そうした形で品川区も設置すべきだと思いますが、その辺を含めていかがか尋ねました。","respondent":"亀井品川保健センター所長","answer":"今、妊娠・出産包括支援モデル事業という形で、さらに幼児期までにわたる母子保健の確立というのは非常に重要なものだと考えております。今後については、厚労省のモデル事業の動向であるとか、経過を見て判断していきたいと思います。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"こころの体温計を提示しておりますけれども、そこに産後ケアの一つとして、赤ちゃんママモードを追加したらどうでしょうか。ご見解を説明するよう求めました。","respondent":"亀井品川保健センター所長","answer":"お母さんにアンケート様式でお答えいただきまして、継続的なフォローみたいなことをやっておりますので、直接訪問してお話を聞かせていただくという形でのフォローアップを提示していきたいと考えています。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"平塚市が２３年度に導入してから、この赤ちゃんママモード、ぜひ積極的に追加の検討をお願いしたいと思います。これについて品川区として把握しているところの範疇で教えていただきたいのですが、こうしたものを研究・導入されてはどうかと思います。","respondent":"小林品川区清掃事務所長、野呂瀬環境課長","answer":"大井競馬場の馬ふんですけれど、こちら、事業系の一般廃棄物ということで、該当処理業者によって処理されています。有機農業に使えるような土壌づくりにということで、堆肥として処理・販売しているというふうには聞き及んでおります。 そういう施設をどうするのか、においはどうするのか、いろいろな課題が大いにある。考え方として、いろいろ中長期的にいろんなことで進めていくのは、有効であると考えているところです。","id":"exchange-010"},{"speaker":"向委員","kind":"質問・要望","question":"このあたり、今、お答えいただける範囲で、区がとるべきと考えている対応策等々を教えてほしいと求めました。こちらを先にお伺いします。","respondent":"伊津野保健予防課長","answer":"ここにつきまして、少し方針が変わりまして、今後検討を進めていきたいと考えています。２期が８９.６％、３期は２４年度で終わったのですが８５％、４期が７５.３％という数字となっております。","id":"exchange-011"},{"speaker":"向委員","kind":"質問・要望","question":"女性に特化した助成、男性の不妊治療助成についてはどのように区はお考えなのか、ちょっとそのあたりをお尋ねしたいと思います。その後、医師会と、そのあたりの協力体制、どうなったか教えていただきたいのと、あと品川区での超音波検査の助成回数を改めて説明を求めました。","respondent":"江部健康課長","answer":"あり方検討の中で認められたやり方というのは、我々も認識しておりますので、それについては医師会のほうにはお願いをしています。超音波検査はお１人１回ですが、その件数ですが、２４年度で２,９６４件です。","id":"exchange-012"},{"speaker":"向委員","kind":"質問","question":"今後、区として助成していく予定というのは、これが重要と考えていらっしゃるのかどうか、そこら辺をもう少しちょっとお尋ねしておきたいと思います。平成２７年度からですか、子ども・子育て支援の新制度が新しく施行されて、妊婦健康診査事業についても項目の中に挙がっていると思います。","respondent":"江部健康課長","answer":"検討の推移を見守りたいと思いますが、男性のほうも治療助成しておりますので、引き続き事業としてはやっていきたいと考えております。時間を盛り込んだということであって、基本的には今の事業を充実させていくということで、特に変わっておりません。","id":"exchange-013"},{"speaker":"向委員","kind":"質問","question":"もっと具体的に内容をお尋ねできるのかと思いますけれども、推定体重をお医者様に教えていただいて、毎回される方が大半だと思うのですよね。１回までの助成、このあたりのところ、今のお考えを説明するよう求めました。","respondent":"江部健康課長","answer":"これは今のところ動かないという状況の中でやっておりますので、現実的に医療機関で行っていることについてはちょっと把握はしておりません。あり方検討会の中で、基本的には１回でよろしいですので、変える予定はしておりません。","id":"exchange-014"},{"speaker":"向委員","kind":"質問・要望","question":"どうしても、基本的には妊娠３カ月までの、３カ月にもう入っているのですよね。３０代、３０代から４０代の女性、何かそういった思いがあれば説明を求めました。","respondent":"亀井品川保健センター所長","answer":"かなり前から、ふだんから葉酸を積極的に摂っておくべきというのが、本来では考え方。妊婦ということではなくて、そういうところで、どんな形でこういった問題を取り上げていくかということを検討していきたいと考えています。","id":"exchange-015"},{"speaker":"向委員","kind":"質問・要望","question":"残り少しだけですが、母親学級、その後、昨年の決算特別委員会でお尋ねしました。平日のみではなくて週末もとお話をしましたが、その後、変更があったかどうか、そのあたりを簡単にお願いします。","respondent":"亀井品川保健センター所長","answer":"１日で出たり、そういった説明で受けとめていただいて、平日の両親学級については特に考えておりません。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"時間があれば、２６３ページ、母子健康診査費のうち、妊婦健康診査に関連した質問を行いたいと思います。２５９ページの任意予防接種の中のＢ型肝炎について質問いたします。","respondent":"伊津野保健予防課長","answer":"この事業は、０歳児を対象としまして、１回３,０００円、３回まで、Ｂ型肝炎ワクチンの費用を助成するものです。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"それとともに区議会でもたびたびＢ型肝炎について、それを予防できるＢ型肝炎ワクチンの接種の重要さについて訴え、助成の要望を行ってきました。助成を要望してきた区議会議員として、この決定を誇りに思うものであります。","respondent":"伊津野保健予防課長","answer":"定期化されるまでの間、任意接種として区の事業として行うことは、保健施策として胸を張れるものであると考えております。将来の肝臓がんの予防、肝硬変の予防、そういう意味でも大変意義のあるワクチンであると考えております。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、２５９ページの感染症対策費に関連して、現在のはしか、麻疹の流行についてお伺いいたします。はしか、麻疹という病気について、簡単な説明をお願いいたします。","respondent":"伊津野保健予防課長","answer":"麻疹ウイルスに感染して、風邪の症状、それに続きまして３９度以上の高熱と全身発疹を示す病気で、肺炎ですとか脳炎ですね、そういうものを合併する大変恐ろしい病気です。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"意見","question":"なぜならば、今回の流行でも、麻疹に感染した小児・大人のうち、ワクチン未接種者は相変わらずかなりの割合を占めているからです。","respondent":"伊津野保健予防課長","answer":"１期につきましては、先ほども伝えましたが、９９.３％で、２３区中８番目の高さであります。２期につきましては８９.６％で、１４位という形になっております。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"毎回報告なのですが、５歳から６歳の保育園児、幼稚園児が受けるＭＲの接種率が、流行を阻止できると言われている９５％に届いておりません。接種率９５％というのを目標値として、強く体系的に取り組むことが必要なのではないかと思いますが、これについてはいかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"現在でも、小学校の入学前の就学時健診の際の確認というのを行っておりますが、今後さらに関係機関との連携を強めまして、ぜひ９５％以上の接種率を確保していきたいと考えております。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"続きまして、２５９ページ、感染症対策費のうち、先天性風しん症候群対策についてお伺いいたします。さしもの風疹の大流行も下火になり、マスメディアの報道も激減しましたが、風疹流行の現状はいかがなものか尋ねました。","respondent":"伊津野保健予防課長","answer":"風疹の発生数ですが、東京都で今年、２２名、品川区では１人でした。先天性風疹症候群につきましては、東京都で今年になりまして３名の発生を見ております。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２つの感染症を予防する混合ワクチンでありまして、多くの品川区民がＭＲワクチンを接種しやすい環境を整えることが極めて重要なことだと思います。これに関して、最後に一言ご見解をもう一度伺いたいと思います。","respondent":"伊津野保健予防課長","answer":"委員ご指摘のように、風疹だけではなく麻疹のほうの流行も危惧されるところでありますので、今回の機会を捉えまして、ＭＲワクチンの接種を、妊娠を希望する女性だけでなく、その周りの方にも今後拡めることを検討していきたいと考えております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に２６３ページ、妊婦健康診査に関連してお尋ねいたします。今回はこのうちヒトパルボウイルスＢ１９の感染症についてお尋ねしたいと思います。","respondent":"伊津野保健予防課長","answer":"発熱に伴いまして、ほっぺたが赤く紅斑状になる病気であります。そんなに重篤な病気にはなりませんが、ただ、妊娠中の妊婦が感染しますと、胎児に影響があると言われております。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"確認","question":"胎児へのパルボウイルスＢ１９の感染を確認、中絶が３例、出産は１７例だったと発表されたものです。一般的に、パルボウイルスの感染症が胎内感染を起こした場合に胎児に異常が出る率はどのぐらいだと言われているのか尋ねました。","respondent":"伊津野保健予防課長","answer":"妊娠中に感染しても、胎児に影響が出る確率としましては、一般的には５％以下と言われています。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"パルボウイルスＢ１９に感染したことがない妊娠初期の女性が初感染を起こすと、重度の貧血や心不全になり、死亡し流産してしまいます。胎児に影響が出る可能性があるので、配慮が必要と思われますが、現状はいかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"なかなか対応は難しいと思いますが、なるべくしないような形で、このようにするという形で考えております。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"パルボウイルスＢ１９の抗体を持っていれば、逆に免疫があれば、これは終生免疫ですので、子どもに異常は全く起こりません。これに対する配慮を品川区のほうでもお願いしたいと思いまして、これは時間がないので要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"中塚委員","kind":"提案","question":"私からは２９３ページ、空き店舗解消支援とマイスター店にかかわって、商店街や中小企業の営業支援について伺いたいと思います。具体的な提案は後ほどしますが、これでよいのか、ちょっと伺いたいと思いますとの意見を述べました。","respondent":"米田商業・観光課長","answer":"いわゆる街路灯の建替え等に使える東京都の補助支援のメニューですけれども、こちらにつきましては昨年度よりわりかし多かった。いわゆるソフト的な支援については、むしろ例年より充実しているものと、このように理解しています。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"その上で、こうした視点を中小企業にも向けてほしいということです。こうした位置づけで、一番店発見プロジェクトにかかわって、ぜひこの中小企業版を実施していただきたいと思うのですけども、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"昨年度、今年とやってきまして、トータルな視野で優れた製品を認定しているものです。区長が認定製品・技術について、プレゼンテーションなども行いながら、区としてはＰＲさせていただいているというような状況です。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"去年の１０月の決算特別委員会ですけれども、商店街の新規個店開設支援についてちょっと伺ったところ、そんな答弁がありました。出店を願う方を募って、そういう立ち上げ支援もよいのではないかと思いますけれども、こういったことはいかがか尋ねました。","respondent":"米田商業・観光課長","answer":"今年度既に予算の上で、３つの商店街、３つの店舗で開設の予定があるというようなことで計上しています。昨年度は組織力強化支援事業として、それ以外の予算に計上されないものも含めまして、つなぎ合わせていければと考えています。","id":"exchange-030"},{"speaker":"中塚委員","kind":"提案","question":"そういう店舗探しにつないでいく、あわせて進めてほしいと求めましたが、今後の見解について改めて伺いたいと思います。家賃などの固定費、商店街の空き店舗を活用した新しいにぎわいづくりをぜひ進めてほしいと求めましたが、この点もあわせて伺いたいと思いますとの意見を述べました。","respondent":"米田商業・観光課長","answer":"いろいろな条件もあろうかと思いますので、その辺は一つ一つのご相談に丁寧に答えてまいりたいと思ってあります。まず第一義的に商店街支援の一環といたしましては、その上でそういう、こちらのほうも商店街を中心とした支援に努めてまいりたいと考えています。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"質問順で、２９１ページ、２９７ページ、創業支援センター関係、お伺いします。２９７ページの施設管理費等に含まれているのか、もしそれに含まれるとすれば、なぜ分けなかったのか、その件について説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"西大井創業支援センターの予算ですけれども、ベンチャー創業支援事業の中の内訳といたしまして、西大井創業支援センター施設管理費等というところで。それからソフトの支援については、その中でさらに含まれておりまして、１,０００万円ほどです。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"品川区でなぜ創業の支援をしなければならないのか、この件について改めて教えてください。そんな小さなことではなくて、もっと大きな視点でボトムアップを図る、そういうことなのかどうか説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"創業支援センターの施設を活用していただいて、その後につきましては、特段いわゆる条例あるいは規則などで縛りはございません。ものづくりの、創業者に場所を貸しまして、あるいは誘致するというようなことを通じて活性化を図ってまいりたいというような目的があります。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問","question":"ただ、その大義というところでまたちょっと伺いたいのですけれども、まず西大井の施設で伺います。やめてしまっているという例もよくお聞きしますけれども、いわゆる生存率とか売上等、もしわかれば説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"こちらのほうは、中小企業白書などによりますと、一般的に創業して５年で継続している率というのは４０％ほどという数字も出ております。それに比較して、区の創業支援センターは一定、効果があるものというような形で認識しているものです。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"武蔵小山創業支援センターを伺います。それとも委託先から提案を受けて、比較的自由な形で経営を任せているのか、それについて説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした起業を支援するためのさまざまなソフトにつきましては、区と図って、区の意向を十分お伝え申し上げてつくっていただくというようなことです。それから委託のメンバーですけれども、６名で通常は対応していただいているというような状況です。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"提案","question":"非常に私も伺ってみて、自由度が高い、そして民間感覚のある、珍しい施設だと。最後伺いたいのが、第１回グランプリの方がその後、それは現在どうなっているのか説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"年々、いろいろ事業は、反省し改善してつないでいくというような視点です。ここに応募していただいた方をさまざまな観点で支援しようということで、さまざま連携をとりながら、継続させていただいているような状況です。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"スムーズに２台着けられるということが大事ではないかと思いますけれども、その点、いかがでしょうか。私も現場へ駆けつけたのですけれども、建設委員会でご報告があったと思いますが、再発防止という観点でお伺いします。","respondent":"米田商業・観光課長、小林品川区清掃事務所長、野呂瀬環境課長","answer":"事業といたしましては、夕方、目黒川のイルミネーションを楽しむということで実施していただきました。総合的に勘案した上で考えてまいりたいと思いますの… 清掃車両の火災事故につきましては、カセットボンベが原因となっております。今回はこの２月４日から３月５日までに開催されました、出し方のご案内… いわゆるわなを設置したのが２１件ありまして、そのうち捕獲したのが２匹いたと、ハクビシンだという目撃情報。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"意見","question":"ただ、二十何カ所仕掛けて２件しかとれなかった。虚心坦懐に捉えていただいて、ぜひしっかり駆除のほう、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"この出生率というのがあって、その把握数というところの把握率というのが事務事業概要にありますけど、これはどういう意味でしょうか。訪問件数自体は、そのうちの何件もありましたよというので、これだけ訪問しましたというのはわかるのですが、それを教えてほしいです。","respondent":"亀井品川保健センター所長","answer":"それを足したものが、把握率の分子になっています。ですから、それ以外に、全く、出生届は出されているけれども出生通知票、すくすく赤ちゃん訪問の申込書が出されないという方は残る部分という形です。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"この数字ですから、周知度は高いと思うのです。残り５％の方々が、１００％、いわゆる連絡等はとれているのか尋ねました。","respondent":"亀井品川保健センター所長","answer":"確かに実際には１００％に至ってないので、来られてない方についてはいる。やはり少し要支援家庭としての要素が高くなってきますので、子育て支援課とタイアップしてフォローアップしていくという形になっております。","id":"exchange-040"},{"speaker":"渡部委員","kind":"意見","question":"１歳半健診も受けられない、３歳児健診も来られなかったという中で、連絡がつかない方っていますか。１００％、品川区の子どもたち、連絡とれていますかとの意見を述べました。","respondent":"伊崎子育て支援課長","answer":"２４年度の健診未受診者のケースの件数ですが、保健センターから連絡をいただいたのが２１件ございました。そのうち、何回かの訪問を重ねたのですが、１１件につきましては、居所不明ということのままです。","id":"exchange-041"},{"speaker":"渡部委員","kind":"意見","question":"３歳児健診を終えましても、学齢期になりましたら、あなたの小学校はどこですよというような案内も必ず行くと思います。まだ不明になっているというようなことは、課長、ありますかとの意見を述べました。","respondent":"伊崎子育て支援課長、和氣学務課長、亀井品川保健センター所長","answer":"子育て支援課で対応しておりますのが、最終的には３歳児健診の居所、未受診者というところでふるい分けいただいているところです。その後は… 就学時の際における不明児童については、３年前に全件調査をいたしまして、全て不明チェックが終わりました。毎年１人ぐらいいらっしゃるのですが、全部… 先ほどのご答弁でちょっと追加します。２４年度から、それが２４年度、ちょっと多くなった理由です。","id":"exchange-042"},{"speaker":"渡部委員","kind":"質問・要望","question":"さまざまなフィルターをかけていって、これからも子育てに優しい品川区であってほしいと思います。今回、策定に当たっての基本的なスケジュールのところを教えてほしいと求めました。","respondent":"江部健康課長","answer":"は庁内で関係部署での検討部会、基本的にはつくり上げていく予定でございまして、年度末にはつくり上げるという予定です。","id":"exchange-043"},{"speaker":"渡部委員","kind":"質問","question":"実際、紹介だけではなく健康大学を出られた方で推進委員になられている方、いるのかどうか。それと、推進委員の構成員、町会だけではないと思いますので、そことあわせて説明を求めました。","respondent":"江部健康課長","answer":"それから現在は、町会・自治会から基本的には１名出していただく、推薦をいただくということで、２１５名の方が活動されております。その推進委員という形でのあり方につきましては、今回の策定、プランの策定委員会の中で、あり方についても検討していきたいと考えております。","id":"exchange-044"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば共同出展に関しては、今までたしか海外１回の合計が２回だったでしょうか、品川パビリオン、出してますね。例えば海外進出は、前回もベトナムへの調査研究があったと思うのですが、であればベトナム、どういうふうな形になっているか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"通常、東京ビックサイトで行われるさまざまな技術展などに、区としましてご支援をさせていただいているところです。ベトナムは、やはりグローバル化時代の関係でもって、海外資料も踏まえた中小企業の活力アップのために取り組んでいるというような状況です。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問・要望","question":"景気もよくなってきています、つけていただくためにも、さまざまな支援をこれからも続けてほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"若者就業支援事業について伺います。この同じ事業について質問したとき、その調査、行ったらどういった結果が出たのか教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"広く企業の、中小企業の支援のためのニーズ調査という形で切りかえをしまして、期待するものというような形のアンケートのものでした。やはり中小企業でフレッシュな人材を求めたいというような要望も、このアンケート結果で出たものです。","id":"exchange-047"},{"speaker":"大倉委員","kind":"意見","question":"８５名の方が応募していただいたということで、今現在３６名しか事業参加はできなかったのですが、参加者を増やしていくというお考えがあるかどうか説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"８０名いらっしゃったのですけど、結局は事業には、状況として参加できますよという方が絞られて３５名というような形になったものです。いろんな、さまざまな事業の実施した方法・結果を見きわめまして、適切な若者事業を行ってまいりたいと考えているものです。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後こういった需要が増えて、いくのかいかないのかわからないですけども、しっかりとぜひ支援をしてほしいと求めました。何かちょっと抜けてるような気がするのですが、そういったのは、何かここでできるのか尋ねました。","respondent":"福島青少年育成課長、山崎ものづくり・経営支援課長","answer":"１６９ページの青少年育成の中の一番下、若者育成支援事業、ニートについて検討していくということになってあります。 生保の関係につきましては、区のほうで就業センターを開設しておりまして、そちらの支援員のほうと十分連携をとりながら、生保の方の就業環境をつないでいただいて、対応しています。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問","question":"エイズ予防啓発費について伺います。６月ということだったので、１２月１日には世界エイズデーということで、メディア等にも多く取り上げられるところではあると思います。","respondent":"伊津野保健予防課長","answer":"かなり人数が集まったものですので、来年度の予算では２日の実施に拡充を考えております。１２月１日の世界エイズデーに合わせて１２月開催を考えましたが、さらに、あえてその時期を外しまして１０月に実施する予定であります。","id":"exchange-050"},{"speaker":"大倉委員","kind":"質問・要望","question":"なかなか１社しかなくて難しいということではありますが、ぜひとも取り組んでほしいと求めましたので、これはぜひお願いいたします。例えば今回２６名の方が就労したという中で、またぜひ取り組んでいただきたいと思うので、その後の後追い調査についてお話をお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"現在まで継続して皆様頑張ってお仕事をしていただいている状況ですけれども、その後の会社勤めのお悩みだとか、体制も含めて組んでいるところです。地域の中に溶け込み、仲間づくりというようなことも含めて、地域ともども今就業事業について取り組んでまいりたいと考えています。","id":"exchange-051"},{"speaker":"大倉委員","kind":"質問","question":"品川区ももう、３回ぐらいになるのか、取り組みをされていると思います。その中で、特に教職員という視点で、今どのぐらいの方が受けたのかというのを教えてほしいと求めました。","respondent":"大石荏原保健センター所長","answer":"３回、１回目は４９名中、教育委員会の方が８名。３回目は３３名受けられた方の中で教員が２４名という形で受けていただいています。","id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"自殺ではなくていじめとかでも、きっと変化に気づくというところではゲートキーパー、役に立つのかと考えています。ゲートキーパーに有効かどうかを、もしちょっとわかれば教えていただきたいのと、どうか尋ねました。","respondent":"大石荏原保健センター所長","answer":"３回目を７月３０日、８月２６日と、教員の方が受けやすい体制を整えています。教育委員会からも積極的に働きかけていただいたことも、一定、かなりの方が受けられた要因だと考えております。","id":"exchange-053"},{"speaker":"大倉委員","kind":"意見","question":"受けやすい期間を設定していただいて、受けていただいているということなのですが、まだまだ数が少ないと思いますので、ぜひとも多くの方に研修を受けていただいて、子どもの気づきに効果があるということでしたので、取り組んでいただけますようにお願いいたしまして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"このイベント事業で２つありますが、この違いは何でしょうか。このまちゼミをすることによって、なぜ商業発展につながるのか、その仕組みは何でしょうかということでお聞きします。","respondent":"米田商業・観光課長","answer":"各商店街あるいは全体の商店街はどれぐらい経費を要したか、その辺の動向を見据えつつ今後の対応についてはまた考えてまいりたいと考えています。こういう取り組みを支援し、またそのほか、新たな商店街の顧客の獲得につなげていければというようなことで考えてあります。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう形で交流するのかわからないですけど、やはり皆様に知らせていくことが必要なのではないかと思いますが、そのお考えをお聞きします。リピーターが増えてるのか、どうなんだろうかというところがありますので、それとリンクする形で何か策があるのかどうかお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"その中で、また商店街のほうにこういう支援を行っているというようなことは、その辺についてはさらなる研究をしてまいりたいと考えています。これは商店街連合会とも仕組みのほうについて十分精査した上で実施してまいりたい。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問","question":"もう一つが、戻りますが２６３ページの公衆便所費について、この２点をお伺いいたします。区全体で何カ所あるのかということと、また主にどのような場所に整備されているのか、現状を説明するよう求めました。","respondent":"亀井品川保健センター所長、多並公園課長","answer":"それから３歳児の健康診査ですけれども、２４年度対象者が２,９７６人で、未受診者が２３７名いらっしゃいました。ちょっとこちらのほうでは事実をつかんでいないのですけど、先ほど子育て支援課長のほうが… 私からは公衆便所についてお答えします。公衆便所につきましては、現在３６カ所、駅前などの人が多く集まる場所を中心に設置されているところです。","id":"exchange-057"},{"speaker":"こんの委員","kind":"提案","question":"訪問型の健診、これを提案したいと思うのですが、いかがでしょうか。つけていただきたいという、こういうこともあるかと思いますので、このまま着実に進めていただきたいという要望で終わりますとの意見を述べました。","respondent":"亀井品川保健センター所長","answer":"現時点で全面的に否定するつもりはありませんけれど、ご提案として受けとめさせていただいて、今後の研究課題とさせていただきたいと思います。","id":"exchange-058"},{"speaker":"渡辺委員","kind":"質問","question":"私は２８９ページの観光アクションプラン推進事業と、２９３ページ、商店街活性化事業費から新規出店とマイスターの関連で伺いたいと思います。新規出店の把握というのですか、結構地域によったら、新規出店が元気なエリアがあるかと思います。","respondent":"米田商業・観光課長","answer":"電子ベースで何らかの対応ができないかというようなことで、開発費用として、開発あるいは取材等の費用として見込んでいるものです。それからお土産コンペティション事業の継続ということで２５０万。","id":"exchange-059"},{"speaker":"渡辺委員","kind":"質問・要望","question":"特に私ども自民党も強く要望させていただいたり、やはり全国的に観光への投資というのですか、膨らんでいっていいものと思えています。ではここまでで、見解を伺えればと思います。","respondent":"米田商業・観光課長","answer":"区のいろいろな商店街の支援策、今後、こういうような支援もまた継続して行ってまいりたいと考えています。１カ月ぐらいたって、大体５００ぐらい出ていくというようなことでは、そういう地道な活動のほうも継続して行ってまいりたい。","id":"exchange-060"},{"speaker":"渡辺委員","kind":"提案","question":"その中で、当然、増やしていかないと足りないのではないか、あるいは増やすことで波及効果があるのであれば、自治体としてそこをどう活かしていくか。一つ提案をすれば、宿泊施設、民間への支援も含めてどんなふうに考えられるかお知らせくださいとの意見を述べました。","respondent":"米田商業・観光課長","answer":"そういった意味では、例えば食事がついていなければ、そこの周辺でお料理を楽しんだりというようなことも一つの重要な要素であろうと思います。大きくまちづくりの中で検討していくべき課題ではあるかと思いますが、今後検討を進めてまいりたい、このように考えてあります。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"放射能対策、どう強化をされているのか、まずお伺いしたいと思います。このような実態をどう受けとめられているのかお伺いします。","respondent":"野呂瀬環境課長、高山生活衛生課長","answer":"毎週ホームページ等でアップしていますけれども、０.０６から０.０８の、基準値の３分の１ぐらいの値で推移している。こういう状況です。 私のほうから食品中の放射性物質に関するお尋ねについてお答えいたします。このように考えております。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この認識を持っていらっしゃるかどうか、これが１点。これは大気汚染も、あと給食もそうです、食品もそうですけれども、ぜひ拡充強化をしてほしいと求めましたが、いかがか尋ねました。","respondent":"野呂瀬環境課長","answer":"この姿勢に関しては今までどおり継続しておりますので、そういう形でこれからも空間線量については取り組んでいきたい。区民の皆様に、区内の空間線量については安定した値であるという周知は、今までの私どもの対策でできてきているからだと考えているところです。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民が求めている、流通しているもの、安全とは言い切れないところがあることをぜひ知っていただきたい。そして測定器の設置、これ、区の責任であると思いますが、再度求めますがいかがか尋ねました。","respondent":"野呂瀬環境課長、高山生活衛生課長","answer":"いわゆる継続して何か状況が変わって、高い値が出てくるような状況になったら、その都度対策をしていくと。こういうことは申し上げております。 私のほうからは、食品の放射性物質の定期の件数、お問い合わせについてお答えいたします。食材の持ち込みですとか、流通品などの検査を重ねてする必要性は薄いと、このように考えております。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"あっても赤ちゃんの姿が確認できない実態、児童虐待も大変な勢いで増えていますけれども、こういった心配を取り上げていました。先ほども子育て支援のほうと連携しているという話を伺い、このようなケースがありましたら、内容とか具体的な問題点を教えてほしいと求めました。","respondent":"亀井品川保健センター所長","answer":"そういう事例は、それほど多くはありませんが、あります。子育て支援課に情報提供して、そういった中で、関係者が集まって情報共有してフォローアップしていくという体制を整える。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"この点お尋ねしたいのと、たばこのことですけれども、受動喫煙。私、この啓発が大変重要と思いますが、いかがか尋ねました。","respondent":"亀井品川保健センター所長","answer":"さらにそれに何かお土産的なものというのは、ちょっと今、あまり大きなものは考えておりません。たばこに対しては、対策を徹底していきたいと考えています。","id":"exchange-066"},{"speaker":"井上委員","kind":"確認","question":"２９３ページ、商店街活性化事業の装飾灯関連助成と、２９５ページのプレミアム付区内共通商品券についてお伺いしたいと思います。そういった補助金がなくなった場合には、同等の予算で、区単独で事業を継続していこうという方針を持たれているのかということの確認。","respondent":"山崎ものづくり・経営支援課長","answer":"今年、２６年度につきましても、補助金の確保・獲得のめどがたちましたので、同様のフレームで行う予定になってあります。区内企業の、そうした細かい一つ一つのカリキュラムにいろいろ今年の事業の反省点を活かしてまいりたいというようなことで考えているものです。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問","question":"ある程度の期間を切って、３年とか５年という見通しを定めて契約を進めるということは、方針としてきちんとしておくべきだと思います。その点について、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"４月より、経営相談の相談窓口のブースを一部活用しまして、そうした対応を充実してまいるというような予定です。その経過があって、２６年度については随契をしていくというような流れです。","id":"exchange-068"},{"speaker":"井上委員","kind":"質問・要望","question":"充実していただきたいです。随契で行くのではなくて、きちんとした期間を切って決めていくべきではないですかという質問をしたので、その答弁をお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"より効率的な事業執行のためのパートナーとなる委託事業者の選定ですので、画一的なことで考えずに、より事業の正しい執行と契約の公平性の部分も含めまして、事業の選定については考えてまいりたいと考えています。","id":"exchange-069"},{"speaker":"井上委員","kind":"質問","question":"今年はどのような名目と理由でこの予算が組まれたのかということを改めてお伺いしたいと思います。それから、２００９年から１０年のプレミアム分の総額が幾らになるのかも説明を求めました。","respondent":"米田商業・観光課長","answer":"こちらにおいては、経済状況を見きわめつつ、緊急経済対策として平成２１年度からは継続して実施しているものです。地域商業の活性化を図るために実施しておりますが、景気の好転は一部見られるものの、今年度についても継続して行っているものです。","id":"exchange-070"},{"speaker":"井上委員","kind":"質問","question":"１人５万円という金額で、最近はすごく周知がされていますので、購入に行っても既に売り切れていることが多いと伺っています。実質、これは税金を３億円配っているという事業になっているわけですから、広範な方に渡るような対策が必要というふうに思います。","respondent":"米田商業・観光課長","answer":"当初の発表においても、売り方については工夫をしていくというようなことです。週の後半からというようなことで、今、検討を進めている状況です。","id":"exchange-071"},{"speaker":"井上委員","kind":"質問・要望","question":"そういった中で、商店街の方にお聞きすると、各商店街で商品券の引き換えの担当のお店が決まっているというふうに伺いました。区はこの事業のアウトカムをどのように考えているか尋ねました。","respondent":"米田商業・観光課長","answer":"勘案して実施を行っておるものですが、いわゆる商店街組織への加入であったりとか、横のつながりであったりというようなことが見込めております。","id":"exchange-072"},{"speaker":"井上委員","kind":"質問","question":"どういう活性化に結びついているのかというようなことも含めて、アウトカム、行政が行うべき税の再配分として適切なのかどうなのか。今回、商店街の支援として、建替えなんかでもＬＥＤ照明を導入するというものはこのメニューに含まれているのか尋ねました。","respondent":"米田商業・観光課長","answer":"そういうものもありつつ、今後、また継続等について検証を図ってまいりたいと考えています。ＬＥＤ化するに当たっては、そちらのほうを使われているというような実際、事実もあります。","id":"exchange-073"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは２７３ページ、それから２８７ページの産業経済費の中の伝統的産業の振興というところを伺いたいと思います。全額１,０００万円余ですが、その辺の背景的なものというのでしょうか、教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"ですから、３月までに終わるということで、除去につきましては３件中２件来ているというこういう状況です。いずれにしましても、アスベスト対策、こういう形で、国の補助金等々活用しながら進めていくところです。","id":"exchange-074"},{"speaker":"山元委員","kind":"質問・要望","question":"人為的・技術的な支援をしてほしいという、専門職というのでしょうか、実際何人ぐらいいらっしゃるのか。調査員というのでしょうかね、なってらっしゃるのか、教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"東京都のほうも、ＯＪＴとか研修の制度もこれから充実していくということも聞いておりますので、そういう中で今後も取り組んでいきたい。このように考えております。","id":"exchange-075"},{"speaker":"山元委員","kind":"質問・要望","question":"それから、この下に冊子作成というのですか、先ほど事務所向けというふうにおっしゃっていました。それから、それでは事務所向けでない個人に対してのそういう周知というのでしょうか、教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"３０年前ぐらいにブレークというのがやってきたのですけど、１９９５年、こちらに申請していただければ実施しております。このように考えているところです。","id":"exchange-076"},{"speaker":"山元委員","kind":"質問・要望","question":"「伝統の技と味しながわ展」についてお聞かせほしいと求めました。この方たちの多分、その辺の人選というのでしょうか、その辺はどういうふうになっているのかを教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"「伝統の技と味しながわ展」ですが、毎年１月の下旬に行われておりまして、今年につきましては２１人の職人が出店していただいております。そういうことで同じです。","id":"exchange-077"},{"speaker":"山元委員","kind":"質問・要望","question":"やはり、海外の方たちも、見てすごいと、これからこの技に対しての、区として、海外向けと言っては変ですが、どのように対応していくのか。日本語は通じないと思うのですが、その辺もどうやって紹介をしていこうと思っていらっしゃるのかを教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"観光担当にこの仕事が位置づけておりますので、いわゆる観光の資源の紹介という中で、多言語化を含めて広く紹介していけるように、今後研究を深めてまいりたいと思います。","id":"exchange-078"},{"speaker":"松澤委員","kind":"質問","question":"もう廃止だと思っていたものですから。そしてまたこれがどうして再開されたのかについてお聞きしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"当時はディーゼル車が環境へ及ぼす影響が大きいということで、当時、より効率的で環境に優しい天然ガスＣＮＧ車の導入を促進してまいりました。","id":"exchange-079"},{"speaker":"松澤委員","kind":"質問","question":"２,０００リットルもここで備蓄することができるのならいいと思いますけど、環境の負荷ということで、これを順次切りかえていった。その辺の話し合い、どのようにしたのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"もしくは機種によってはディーゼル車のほうが負荷が少ないのではないかという数字をもとにして、予算要求する段階で若干すり合わせ等しながら、大きく後退しないということを前提として切りかえたことを示していきたいと考えております。","id":"exchange-080"},{"speaker":"松澤委員","kind":"意見","question":"２点目に参ります。商店街振興策、いろいろ、装飾灯維持管理費補助等がありますけれども、この商店街という数、今現在幾つあるのでしょうとの意見を述べました。","respondent":"米田商業・観光課長","answer":"商店街の数ですが、現在１０７ということで把握しています。","id":"exchange-081"},{"speaker":"松澤委員","kind":"質問","question":"１０７といいますと、２５年の４月現在では１０８ということになっていました。すると１つ減ったのかと、また商店街をやめたいというときに、またどのような手続が要るのかをお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"商店街に加入するとき、それから脱退するときも同じですけれども、商業・観光課のほうにお届け出をいただく、このような形になってあります。","id":"exchange-082"},{"speaker":"松澤委員","kind":"質問","question":"当然、廃止するときには、それで終わりですよというわけにいかないと思うのですね。それをもとに戻すというのですかね、単なる街路灯に戻してもらうのか、その辺の費用分担がどのようになるのかをお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"商店街が、いわゆるまちの安全だったり、いわゆるにぎわいの創出だったりというようなことでおつくりになるものです。そういった意味で、商店街の建てるところから、その維持管理、それから撤去するところまで、全て商店街の責任において行っていただくものです。","id":"exchange-083"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、商店街が全て負担して、もとに戻しなさいというふうになっているのか尋ねました。","respondent":"米田商業・観光課長","answer":"直接、区や東京都のほうでご支援できるメニューがございませんので、ご自身のほうで撤去していただく。このようになると考えています。","id":"exchange-084"},{"speaker":"松澤委員","kind":"質問","question":"そのときに、残ってる装飾灯、あなたの商店街は例えば２０本あるではないかと。これをみんなもとに戻しなさいと言われても、その金銭的負担、これ、商店街が負担しなくてはいけないのか尋ねました。","respondent":"米田商業・観光課長","answer":"その一つ一つの商店街のお声を踏まえて、できることは限られておりますけれども、丁寧に対応してまいりたい。そのように考えてあります。","id":"exchange-085"},{"speaker":"藤原委員","kind":"質問","question":"その次に２８７ページの景況調査委託等ですけれども、経済情勢についてお伺いしますが、区としてどう見られているか教えてください。合計では６億という形ですけれども、４億という形にしたら、その辺についてお考えをお伺いします。","respondent":"高山生活衛生課長、亀井品川保健センター所長、伊崎子育て支援課長、山崎ものづくり・経営支援課長、米田商業・観光課長","answer":"こちら、確定値として出ておりますものが、２４年の数値としまして１.１というふうに報告されています。経済推移のほうは… ３歳児健診以降のという対応、もちろんその３歳児の時点でそれなりのフォローアップが必要な方は、保健センター等でフォローアップしてる。… 今後は民間当局への調査等も行っていく予定でいます。","id":"exchange-086"},{"speaker":"藤原委員","kind":"質問・要望","question":"やはりお子さんのことですから、お１人でもわからないとかならないようにしていただきたいと考えていますが、その辺についてはいかがでしょうか。４億となるように、私はいつも願って質問しておりますが、この辺についてはいかがか尋ねました。","respondent":"黒田長期計画担当課長、伊崎子育て支援課長、米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"やはり３０代前半の方の出生率が増えているという傾向がありまして、２０代後半から３０代前半の方の比率が増えていくというような実体があります。… 新聞報道によりますと、厚生労働省は、対面確認をするという方向性を出すということを聞いておりますが、まだきちんとした説明は受けておりません。… そのうち、４月の発行が４億円ということですので、秋口は予算上、２億２,０００万円というようなことにはなろうかと思います。","id":"exchange-087"},{"speaker":"藤原委員","kind":"質問・要望","question":"２億また補正を組むということもできるわけですから、施策に邁進していってほしいと求めましたので、よろしくお願いします。そして、ものづくり、最後に１点伺いますけれども、２９７ページのところで、品川産業支援交流施設、ものづくりの拠点としてできますよね。","respondent":"山崎ものづくり・経営支援課長","answer":"産業のまち大崎に、このような拠点施設を開設できるとは、今、非常に意義深い話だとは思っております。やはり区内中小企業をはじめまして、広く交流を図る観点の施設ですので、利用者の満足度の高い、魅力ある施設にしてまいりたいと考えています。","id":"exchange-088"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは２８９ページの就業支援事業に関連して、ブラック企業に対しての区の見解など伺いたいと思います。働く者を使い捨てる、使い潰す、このブラック企業を根絶していくという立場に、区は立たれているのか伺います。","respondent":"山崎ものづくり・経営支援課長","answer":"いろいろ若者の就業を支援する区の立場としまして、あるいは区内中小企業につなげるという、そういった役割を果たしているものです。いわゆるハローワークの登録の際に、こういったことを確認させていただいて、若者就労につなぐというようなことに努めているものです。","id":"exchange-089"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"就労につなげていると、根絶していくという立場に立たれているのかというのを、ちょっともう一度お聞きしたいと思います。そういった実態調査、そして相談窓口の、今でもしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"東京都のほうに労働相談情報センター、こうしたさまざまな機関と、区のほうはハローワークも通じながら一定の協議会などの場を設けてあります。そういった場所で、区としましても、適切な企業体であるような形の要請を、労働基準監督署のほうにやりとりをして努めているです。","id":"exchange-090"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"厚生労働省も、２０１４年度の予算に、ブラック企業対策として１８億円を計上しています。区としても、こういった就業支援と同時に、ブラック企業の根絶をしていく取り組みも進めていってほしいと求めましたけれども、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"適正な企業のチェック機関といいますか、そうしたところにつきましては、先ほどの労働基準監督署を中心に、そうした取り組みをしていただいています。","id":"exchange-091"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"日本は０.６１人ということで、そこから是正されるというのは、本当に道のりが長いということですよね。区民の働く人権を守っていくという、就業支援と一緒に進めていっていただきたいと強くお願いしたいと思いますけれども、最後にいかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"もちろん、就業の相談で得たいろんな情報につきましては、やはり労基法の体制でありましたが、そうした国の機関に、きっちりとつなげていくようなこと、こういったことは努めてまいりたいと思ってあります。","id":"exchange-092"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"是正する窓口があるということが、すごく区民にとっても安心につながっていく、そして信頼にもつながっていくと思います。品川区内にブラック企業があるのかどうか、そこもぜひつかんでほしいと求めましたけれども、いかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"ちょっと繰り返しになりますが、区としましては、就業センターを開設し、地域に根差した就業支援の窓口を設定しております。そうした若者の就労の経営支援の窓口を一部開設しまして、さまざまな相談に応えていくような対応をさせていただきたいと考えています。","id":"exchange-093"},{"speaker":"若林委員","kind":"質問・要望","question":"２９０ページの中小企業対策費について伺いたいと思います。こういう一般財源をこういう割合で投入している産業経済費の今後のあり方というのですか、一般財源をこれだけ投入している意味というのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"これ、宅建品川支部と連携して、新規事業としてこの辺も強く取り組んでまいりたいです。双方連携しながら、この事業、大切に取り組んでまいりたいと考えています。","id":"exchange-094"},{"speaker":"若林委員","kind":"質問・要望","question":"お話を伺って、いわゆる交流、これは価値創造に絶対につながる。ここについての展望をお聞かせいただきたいのと、あえて創造、ものづくり創造センターが今後存続する意味というのを説明するよう求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"それから、そうした展望を持って産業支援の取り組みは行ってまいりたいと考えています。そうした意味では資源ですので、新施設の稼働とともに、いろんな施設の持つ役割など継続したいと思います。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから２９５ページ、それから２５９ページ、予防接種費について質問します。初めにプレミアム付の共通商品券ですけど、先ほど藤原委員からも指摘がありましたけれども、私ども自民党にさまざまな要望書が来ております。","respondent":"米田商業・観光課長","answer":"まずは４月の消費税率改定に伴いまして、区内の消費の落ち込みが懸念されることから、４億４,０００万円というようなことの発行を予定しています。この委員会で、重ねてのご要請があったということを踏まえまして、さらなる研究をしていく所存です。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"質問・要望","question":"３日以内で、少なくとも２つの会派から要望があったわけですから、ここでお願いしておきます。私ども自民党では、平成２６年度予算に向けた政策要望で、大井保健センター施設のあり方を含め、リナウンスを図られたいという要望を出しております。","respondent":"川島大井保健センター所長","answer":"規模は小さい、引き続き住民に身近なところで身近な保健サービスをしっかり提供していくという考え方に変わりはございません。換気扇をつけると、かなり改善されるだろうというご提案がありましたので、その換気扇を設置する工事を計上させていただいているものです。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"確認","question":"は確認したいのが、まずこういう危険性についてのお考えと、それから接種を勧める品川区のお考えをお聞かせください。お願いいたします。","respondent":"伊津野保健予防課長","answer":"このワクチンの危険性につきましては、今、国の専門部隊、副反応検討部会というところで数回にわたって検討しているところであります。今のところ、国の動向を見守るという状況であります。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"質問","question":"そういう一定の、何というか、安全性を確保した上で、品川区の責任として、対処すべきと思いますがいかがでしょうか。、答えるよう求めました。","respondent":"伊津野保健予防課長","answer":"品川区におきましても、安全性についての説明文書を医療機関のほうに配りまして、接種を希望される場合は、その文書をきちんと読んでいただいて、納得いただいた上で接種をしていただくという形になっております。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"これは別な角度で議論すべきではないかと思うのが１点と、子宮頸がんはなくせるということをおっしゃっているわけですよ。となれば、やはり健診についてもさまざまな形で対応すべきと思うのですが、いかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"ただ、今言われております危険性というのも、国のほうでも検討会、数回にわたって行っております。この医学的な検討、少なくとも現時点では、その国の結論ですね。","id":"exchange-100"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば先ほどの被害者の会の方々の話をお伺いする機会があったのですけれども、接種して１カ月以上たった時点で、もうその被害のことについては。いかがでしょうかということを十分ご説明していただいて、そういうところで品川区としての具体的話をしていくべきと思うのですがいかがか尋ねました。","respondent":"伊津野保健予防課長","answer":"接種の前の説明につきましては、先ほど言いましたように十分な説明が行われております。呼びかける必要は全くない、このままの状態で国の結論を待つということが、妥当な区としての対処ではないかと考えています。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問","question":"ワクチンの性能がわかっているわけではないのだけれども、事、このワクチンについてはさまざまなことが報道されていることも事実です。いろんな副作用等々のリスクを十分説明していっていただいた上で具体的な話をしていただきますことをお願いするのですが、最後に一言でお願いします。","respondent":"伊津野保健予防課長","answer":"非常に重要な事業であると考えていますので、そちらのほうの検診率、そちらの向上も図っていかなければいけないと考えております。あわせまして、このワクチンの有用性というか、そういうのも、結論を待ちたいと考えております。","id":"exchange-102"},{"speaker":"高橋委員","kind":"質問","question":"事務事業概要を見せていただいたところ、２４年から２５年にかけても、ものづくり・経営支援課分は９.７％のマイナス、約６億円でしょうか。このものづくり・経営支援課分というのでしょうか、そういったところはどのような事情があって、こういった形になっているのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"産経費の中の中小企業支援の部分でございまして、２６年度予算、約２３億のうち、１３億円がものづくりの予算というような形です。２０％に落ちて、少し見込みが低くなったということで、そういう調整を本年度予算で図ったものです。","id":"exchange-103"},{"speaker":"高橋委員","kind":"質問","question":"融資の金額が、３億近くでしょうか、下がったと。ほかの支援の事業というのでしょうか、そういった事業を行っていくのが、中小企業の方々にとって大変大きな支援になるのではないかと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"災害対策基本条例を受けまして、ＢＣＰの策定の支援部分に厚みを加えたり、あとワークライフバランス支援も充実させていただいてあります。環境ビジネスのほうも支援をしておりまして、製品開発の支援ですけれど、さまざまな充実をさせていく部分があります。","id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"次に２７５ページのほうの衛生費、すみません、これは何のためにどのような形でやられているのでしょうか。これをお伺いします。","respondent":"野呂瀬環境課長","answer":"平成１３年からやってきて、今のＩＳＯ１４０００、品川区独自の環境マネジメントシステムを構築していく。このための予算です。","id":"exchange-105"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、その上にあるエコアクション２１認証取得助成というのと、ちょっとどのような関係があるのか。実は産経費のほうにも２９５ページにＩＳＯ認証取得経費助成というのがありますが、これはどういうものか、ご説明をお願いします。","respondent":"野呂瀬環境課長、山崎ものづくり・経営支援課長","answer":"今までこの１２年間やってきた実績を踏まえまして、区内の事業者に向けた支援は、当然今までどおり支援は継続していく。この考えです。 こちらは、製品等の品質維持、生産性の向上に加え、社会的信頼へというような点で認識しているものです。そうした意味では環境課のほうと連携をとりながら、十分連携をとらせていただいて実施させていただいているものです。","id":"exchange-106"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから２９７ページの品川産業支援交流施設についてお伺いいたしたいと思います。あるいは自治体と企業でこういった分野、展開されている例が大分出てきましたが、品川区としての姿勢をお伺いしたいと考えています。","respondent":"江部健康課長、小林品川区清掃事務所長、山崎ものづくり・経営支援課長","answer":"健診の考え方ということで、ビッグデータに絡めてのご質問でございました。さまざまな国の考え方とか、そういうごく小さい自治体では実証が始まっているら… それで、清掃車両としましては、それ以外に雇い上げで車を用意しておりますのが３５台、合計して５３台で営業の業務を行っております。それ以外に… 品川産業支援交流施設の３階部分のイベントホールの関係です。","id":"exchange-107"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望です。直営が１８台と雇い上げが３５台ということで、定時に出動すべきだった台数というのは何台で、それぞれ何台であったか説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"雪の日、定時出庫は８時を予定しておりますけれども、８時時点で欠車、まだ用意できていなかった台数はおおむね６台程度でございました。ただ、要員の確保もあわせてそろえる必要がありまして、最終的に全車出庫完了いたしましたのは、１時間遅れの９時に全車出庫しています。","id":"exchange-108"},{"speaker":"あべ委員","kind":"質問","question":"区外の場合には、隣接区なのでしょうか、それとももっと遠くからということになっているのでしょうか。それを伺うのは、ただ、全てというつもりはありません。","respondent":"小林品川区清掃事務所長","answer":"これについては、雇い上げ先を区として特定できないシステムになっておりますので、そういう点では今後の課題というふうに考えております。最低台数は直営車で回れる範囲内で、最悪の場合、作業計画をつくることもあわせて、今後備えるべき事項と考えております。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問・要望","question":"ありがとうございました。やはり災害が起きたときに清掃の車がきちっと動かないということがないように、さまざまな仕組みの見直しを進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"浅野委員","kind":"質問","question":"この有料ごみ処理券、貼られていない場合には回収をしないで走らせてくださいと、そういうような表示でしょうか。今現在そのとおりに行われているのかどうかということと、ごみの回収量と処理券の販売量、これは整合がとれているのかどうか説明を求めました。","respondent":"高山生活衛生課長、江部健康課長、小林品川区清掃事務所長","answer":"データ消失などの危険なども今後検討していかなければなりませんので、今回、予算要求をしているものです。対応が必要な項目などは… 健康手帳についてのご質問にお答えいたしますが、予算上、交付冊数は３万７,３００冊です。毎年受けるものは５年分… もしくは排出場所がわかっているところについては、その内容をポスト等に入れて、ごみ処理券を適正に貼って排出してくださるようにしています。","id":"exchange-111"},{"speaker":"浅野委員","kind":"質問・要望","question":"健康手帳の件ですけれども、例えば要望される方に送ってもいいのかという気がします。本当に予防されているのかというのはある程度つかめるのではないかと、そのように思いますが、これはいかがか尋ねました。","respondent":"江部健康課長","answer":"カウンターでご入り用の方にお渡ししておるところです。アプリの必要性、今のところ、必要だという認識を持っておりません。","id":"exchange-112"},{"speaker":"須藤委員","kind":"質問","question":"４月の販売状況云々と、あるいは土日、休日に買いやすいような仕組みをつくるというような話がありました。その４月の動向というのはどういうことで、次に補正なら補正していこうという考え方になるのか説明を求めました。","respondent":"米田商業・観光課長","answer":"４月に、これも重ねてになりますが、個人消費の落ち込みがある程度、見込まれるであろう。このように考えてあります。","id":"exchange-113"},{"speaker":"須藤委員","kind":"質問・要望","question":"何も、手を出してというとおかしいけど、ああだ、こうだという立場ではないという状況になっているとき、このあたりについて、いかにお考えですか。これは環境課長のほうにも何度も足を現地に運んでもらっていることには感謝しながら、その状況を見て、いかに考えているか説明を求めました。","respondent":"野呂瀬環境課長","answer":"やはり、こういうことが事実としまして、関連の課と連携を図っていって、何らかの対策が必要だということは認識しております。２代目がいないから、そういう住民説明会を、そういうのも視野に入れながら考えていかなければいけない。","id":"exchange-114"},{"speaker":"南委員","kind":"質問・要望","question":"２６１ページの、３５歳からの健康診査について伺います。３５歳以上からの健診というのは、今年度初めて実施されましたけれども、受診者はどのようになっているか教えてほしいと求めました。","respondent":"江部健康課長","answer":"ニーズ的には、１月末の段階で男性の方が７５人、女性の方が５８５人いらっしゃいます。男性の方が１月に１２人弱受けていただいたということで、私どもとすると、そういう意味での効果はあると思います。","id":"exchange-115"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとそのあたりのことも含めて見解を教えていただきたいということと、それから３５歳という年齢だけではなくて、もう少し引き下げる。そのあたりについて見解と、ぜひもう一つ伺いたいのは、その点についてはどうか尋ねました。","respondent":"江部健康課長","answer":"基本的には健康なわけでございまして、数少ないケースのために行政が事業の幅を広げるということはちょっと違うだろうと認識しております。事業開始に当たりましては、１０月、２月にＰＲを行ったところです。","id":"exchange-116"},{"speaker":"南委員","kind":"質問・要望","question":"どういう対策が求められているのか、どうすれば受診率を引き上げていくことになるのかという、私は実態調査をするべきだと思います。それからあと対象の年齢を３５歳ではなく１８歳、年齢引き下げについてぜひ検討していただきたいと思っていますけど、その点についても伺います。","respondent":"江部健康課長","answer":"まず女性の健康診査は、女性特有の疾病対策ということで始めている事業ですので、別のものという認識でお願いしたいと考えています。３５歳から年齢を下げたらどうかという点につきましては、健康実態といいますか、そういったものも入れていきたいとは考えております。","id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"ですからできるだけ、健康な生活を送っていただきたいという意味でも、少なくとも２７年度の予算には反映できるようにしていただきたい。それから受診率を高めるためにという点については、ちょっとあまりよくわからなかったので、もう一度答弁をお願いしたいと思います。","respondent":"江部健康課長","answer":"私ども、それを分析する中で、まず３５歳からの健康診査という事業を組んだものです。必要な方へのＰＲにつきましては、さらに工夫を重ねてまいります。","id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことをしっかり考えていただきたいと思っていますが、先ほど紹介していただいたさまざまなＰＲ方法以外に、ちょっと考えていないでしょうか。さまざまなことが考えられると思いますけども、そういうことについて、どうか尋ねました。","respondent":"江部健康課長","answer":"若者がそんなに……。就業センターなり、そういうところにというのは、ちょっと検討します。","id":"exchange-119"},{"speaker":"南委員","kind":"質問・要望","question":"健診ですからね、受診していただくことが一番大事なわけですから、ＰＲも含めてやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"区外産業も私は同様だと思うのですが、区内の中小企業、区内産業の経済実態をどこまで把握しているのか教えてください。そして、昨年の区内企業の倒産、休業、廃業、解散の件数、わかりましたら、答えるよう求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"やはり、全業種全てで景気の好景気の高揚という意味では至っていないというようなことでお答えします。それから倒産数ですけれども、平成２５年の１月から１２月までで、区内の中小で６０件があります。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"それで今、倒産件数が６０件というお話を、今、課長からいただきましたが、私は、実態をきちんと把握しておくべきだと思うのですね。昨年は３万件以上あったということなのに、解散、これはほぼ事業をやってないのと同じではないか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"２２年度につきましては、１２０件ということで、倍近い数字になっているものです。品川区も４人以下の企業が、２万のうち半分を抱えておりますので、こういうことが実態としては多いというようなこともつかんでおります。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"それで、でもそういうことならば、品川区の、もう経済対策は頭打ちですかと、もう何にもできないよ、だから予算は縮小していくのですか。どうか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"正しく公式事業をはじいて、適正な予算化をさせていただいたものということで、マイナスの部分はご理解いただきたいという説明をしました。それから、それ以外の取り組みについては、平成２７年６月に産業支援の大きな施設をオープンする予定になってあります。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"それが経済対策に結びつくのですか。この２６年度の予算にしっかりした品川区の経済対策、私は産業振興ではないかと思うのですが、その辺に対してもう一度答えるよう求めました。","respondent":"米田商業・観光課長","answer":"その中で、その１２％は品川区の商店街がご活用いただいているというようなことで、国のほうでもさまざまな経済対策を打ってあります。少しずつではありますけれども、予算としては増額して、区内経済の浮揚を図っているというようなことでご理解いただければと思います。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"商店を助けるのですかというのが、それについてちょっと別の質問内容もありますので、ここで１回ちょっと切らせていただきます。これはちょっとどういうことか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"企業の方が、これまで取引をしていた信用金庫というようなつながりがあるところに通常、融資をつなぎます。そうした関係で、一定、会員になるための出資証券を買われて融資を受けられるというようなケースもあると聞いております。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"お金を貸せませんよというのは、私も知らなかったのですが、これはおかしいんではないですか。いや、私は何か品川区としても、自治体としても何か考えてあげなくてはいけないのではないか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"法的に会員になって出資証券をというようなこともあり得ますよというような説明をして、融資のほう、あっせんをさせていただいているです。先ほど来お話しのような状況を強要しているとか、そういった事例は一切ございませんので、ご理解いただけたらと考えています。","id":"exchange-126"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今回１,８００万円余ということで、７００万円余ほど減額されているのですが、なぜ減額されてしまったのかということが１点。いろんな専門分野の学校が多いので、そういったところにも拡大するべきだと私は思っておりますが、いかがお考えか説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"産学連携のほうにまた戻りまして、区内の教育機関と産業の連携につきましては、産業技術大学院大学などと連携するような取り組みを進めております。そういった取り組みには、産学連携も推進し、そうした意味で発展強化をさせていきたいと考えているところです。","id":"exchange-127"},{"speaker":"いながわ委員","kind":"質問・要望","question":"改めてお伺いしますけど、しっかりと今年の６月、やられるということでよろしいのでしょうか。ぜひこの１００万円台というか、地域の企業にとっても大学にとってもプラスになると思いますが、いかがお考えか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"連携の枠組みなどをちょっと考えてまいりたい、あるいは実態としてやられている取り組みを支援してまいりたいというふうに考えてあります。ちょうど実施しまして、すばらしい事業だと考えていますので、それも発展させていただきたいなと考えています。","id":"exchange-128"},{"speaker":"たけうち委員","kind":"質問","question":"それから２７２ページの環境対策費に関連して伺います。平成２４年の代表質問で積極的な活用で当たっていただいて、平成２４年度も、今の現状を説明するよう求めました。","respondent":"江部健康課長、野呂瀬環境課長","answer":"ただ、２月７日付、厚労省健康局長通知によりまして、実施要綱が出ました。４０歳の方には行いますけれども、２年に１回確実に送っております、個別勧奨券を充実させることにより対応していきたいと考えております。 ＰＰＳ、特定規模電気事業者の導入状況です。２５年度現在、東京エコサービス株式会社というところで、小中学校合計で１８校、導入しています。","id":"exchange-129"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これは要望します。それからＰＰＳについては１８ポイントで、区有施設等にはまだ進んでいないと思いますけど、その辺の状況を説明するよう求めました。","respondent":"江部健康課長、野呂瀬環境課長","answer":"４,０００万から３,０００万に減ったところで１,０００万のところですが、これはクーポン事業だけが入っているわけではございません。一応、５分の１、クーポンについては５分の１です。 それと、小中学校のほかにも、第２庁舎、いわゆる防災センター、これは株式会社エネットという会社です。こちらでＰＰＳ事業をやっております。","id":"exchange-130"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望しておきます。一応、考え方だけ、もう一言ほしいと求めました。","respondent":"米田商業・観光課長","answer":"ご指摘の点については十分検討してまいりたいと思いますが、現在、ＬＥＤ化ということでは、密接に商店街等との連携をとっております。","id":"exchange-131"},{"speaker":"本多委員","kind":"質問","question":"初めに、２５６ページの衛生費の中で、１項保健衛生費全般により、命の尊さへの取り組みがそれぞれされています。男性が２１人に対して女性が１２４人ということで、保健衛生の観点でどう捉えていくのか、こういう現状をどのように捉えているのか説明を求めました。","respondent":"矢野品川区保健所長","answer":"委員ご指摘のように、そのような状況がございまして、例えば平均寿命を見てみても、健康寿命を見てみても、そういう状況です。一つは生物学的なこともありますが、まず生活習慣の問題があると思いますので、それについては、健康福祉業務で、今後の課題と考えております。","id":"exchange-132"},{"speaker":"本多委員","kind":"質問","question":"長寿の方や１００歳以上の方の共通点は、たばこも健康な方は吸われるそうですが、本当に長寿の方の共通点はあると思うのです。その辺についてはいかがか尋ねました。","respondent":"矢野品川区保健所長","answer":"確かに、これからの超高齢化社会においての健康長寿というのが重要な課題です。この件も特に重点を置いて、次年度の健康づくりの計画の中で検討していきたいと考えます。","id":"exchange-133"},{"speaker":"本多委員","kind":"質問・要望","question":"大体３０年、４０年たつと健康に異常が出て、どのように投げかけていっているのでしょうか。分電盤の裏にアスベストがあったりするケースが多いと思うのですが、そういったところへの働きかけというのはどうなっているのか尋ねました。","respondent":"野呂瀬環境課長","answer":"アスベストについての周知ですけれども、区の広報以外にも産業ニュースその他等で周知しております。個人住宅、マンションのオーナー含めて、いわゆるアスベストの除去に関する調査ということでしています。","id":"exchange-134"},{"speaker":"本多委員","kind":"質問・要望","question":"そのような状況で、何か区にとって関連することがあるのかどうか。これについて改めてちょっと説明を求めました。","respondent":"野呂瀬環境課長","answer":"給付制度につきましては、ちょっと手元に資料がなく、ちょっと私のほうが今お答えできません。こういう状況です。","id":"exchange-135"},{"speaker":"本多委員","kind":"質問・要望","question":"働く方たちの、そういった環境も見ながら、長寿社会をさらに延ばせるように、女性も男性も長寿に向けて取り組んでいってほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663229?Template=document&Id=1008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":118330,"voices":346}}]);
